VALUES
  ('cpiuris2025::4c44d6055b2ddb90b2a6705c5fe9df31', 'doutrina', 'cp_iuris', 'Direito Empresarial — Recuperação Extrajudicial', '## Recuperação Extrajudicial

A recuperação extrajudicial é uma opção para os devedores que preenchem os requisitos estabelecidos pela lei, permitindo a negociação com os credores e homologação do plano de recuperação.

### Conceitos
- **Requisitos subjetivos**: Condições que dizem respeito ao requerente da recuperação extrajudicial
- **Requisitos objetivos**: Condições que dizem respeito ao plano apresentado pelo devedor
- **Plano de recuperação extrajudicial**: Proposta do devedor para negociação com os credores

### Referências legais
- Art. 161 da LFRE
- Art. 48 da LFRE

### Dicas de prova
- Entenda a distinção entre requisitos subjetivos e objetivos para a homologação do plano de recuperação extrajudicial.
- Conheça as condições para a negociação com os credores e a homologação facultativa ou obrigatória do plano.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.244", "page_number": 244, "discipline": "Direito Empresarial", "legal_refs": ["Art. 161 da LFRE", "Art. 48 da LFRE"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T05:58:14.442373+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=244", "doc_key": "4c44d6055b2ddb90b2a6705c5fe9df31"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '88a121460e6b11030a880e1d70fca87970d69e324699474b184fc8563689ab81'),
  ('cpiuris2025::2889ce7035f4752c3e7dfddf0d24e436', 'doutrina', 'cp_iuris', 'Direito Empresarial — Recuperação Extrajudicial', '## Recuperação Extrajudicial

O plano de recuperação extrajudicial deve ser assinado por credores que detêm mais da metade dos créditos de cada espécie. Com a inovação legislativa de 2020, o quórum foi reduzido para 1/3 do total dos créditos.

### Conceitos
- **Recuperação Extrajudicial**: Procedimento que permite ao devedor reestruturar seus créditos com os credores
- **Quórum**: Número mínimo de votos necessários para aprovar um plano
- **Credores**: Partes interessadas em receber pagamento do devedor

### Referências legais
- Art. 163 da LFRE
- Lei n.º 14.112/2020

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre o quórum anterior e posterior à inovação legislativa de 2020.
- Conheça as exceções à sujeição dos créditos na recuperação extrajudicial, como os créditos tributários.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.245 (1)", "page_number": 245, "discipline": "Direito Empresarial", "legal_refs": ["Art. 163 da LFRE", "Lei n.º 14.112/2020"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T05:58:45.009911+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=245", "doc_key": "2889ce7035f4752c3e7dfddf0d24e436"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '7953b1982cadfaf4bac343c611c735f67217858a0a61a7c14028dd8475f9ea91'),
  ('cpiuris2025::058000229b0b431f00ac76993a0e0a2a', 'doutrina', 'cp_iuris', 'Direito Empresarial — Insolvência Transnacional', '## Insolvência Transnacional

A insolvência transnacional é necessária quando os ativos do devedor estão localizados em diversas jurisdições ou quando alguns dos credores estão localizados em jurisdição diversa daquela em que o processo principal é conduzido.

### Conceitos
- **Insolvência Transnacional**: ocorrência quando ativos do devedor estão localizados em diversas jurisdições
- **Cooperação Internacional**: mecanismo implementado para garantir segurança jurídica nas relações empresariais
- **Uncitral**: Organização das Nações Unidas que aprovou a Lei Modelo sobre Insolvência Transnacional em 1997

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a definição de insolvência transnacional e sua importância
- Conheça a Lei Modelo sobre Insolvência Transnacional e sua implementação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.245 (2)", "page_number": 245, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T05:59:09.872408+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=245", "doc_key": "058000229b0b431f00ac76993a0e0a2a"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'be9fffdcbc77cb4ccc6e01a61e386f7f3ffacfdfaf40a55db8776d80802b88b5'),
  ('cpiuris2025::1154e2243e5a3a5e38f874a64a4a8ebc', 'doutrina', 'cp_iuris', 'Direito Empresarial — Insolvência Transnacional e Recuperacao', '## Insolvência Transnacional e Recuperacao

A Lei Modelo não possui efeito vinculante entre os Estados signatários, permitindo liberdade para incorporar ou não a lei em seus sistemas jurídicos. A insolvência transnacional é disciplinada pelo Capítulo VI-A da Lei nº 11.101/2005, com o objetivo de proporcionar mecanismos efetivos para cooperação entre autoridades competentes, segurança jurídica, administração justa e proteção dos interesses de todos os credores.

### Conceitos
- **Insolvência Transnacional**: Processo que envolve a falência de uma empresa com sede em outro país
- **Cooperação entre autoridades competentes**: Mecanismo para compartilhar informações e coordenar esforços em casos de insolvência transnacional
- **Segurança jurídica**: Proteção dos investimentos e da atividade econômica
- **Administração justa e eficiente**: Proteger os interesses de todos os credores e do devedor em processos de insolvência transnacional
- **Proteção dos ativos do devedor**: Maximizar o valor dos ativos do devedor para garantir a recuperação da empresa

### Referências legais
- Art. 167-A da Lei nº 11.101/2005

### Dicas de prova
- Entenda a importância da cooperação entre autoridades competentes em casos de insolvência transnacional
- Conheça as finalidades e regras de aplicação do Capítulo VI-A da Lei nº 11.101/2005', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.246 (1)", "page_number": 246, "discipline": "Direito Empresarial", "legal_refs": ["Art. 167-A da Lei nº 11.101/2005"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T06:00:02.510866+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=246", "doc_key": "1154e2243e5a3a5e38f874a64a4a8ebc"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '7d09b88eda1126c8f9798c671325251e5889ca2c99cf7ad1f4dc2c1a932447e1'),
  ('cpiuris2025::82386373da83ae73b4cce5cf46f1408f', 'doutrina', 'cp_iuris', 'Direito Empresarial — Insolvência Transnacional', '## Insolvência Transnacional

Rege a preservação e otimização da utilização produtiva dos bens e ativos, considerando cooperação internacional, uniformidade e boa-fé.

### Conceitos
- **Cooperação Internacional**: Ação conjunta entre países para regular a insolvência transnacional
- **Uniformidade de Aplicação**: Necessidade de aplicar as regras de forma igual em diferentes países
- **Boa-Fé**: Conduzir-se com honestidade e integridade no negócio
- **Medidas de Assistência**: Ações que podem ser tomadas para ajudar os processos estrangeiros
- **Competência do STJ**: O Superior Tribunal de Justiça tem competência para julgar casos de insolvência transnacional

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a importância da cooperação internacional e da uniformidade na aplicação das regras
- Conheça as medidas de assistência que podem ser tomadas nos processos estrangeiros', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.246 (2)", "page_number": 246, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T06:00:29.869860+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=246", "doc_key": "82386373da83ae73b4cce5cf46f1408f"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '610baed3d4e6524f8a8d00c95608529443dce013008263aed7a3f0ebe9d5b09d'),
  ('cpiuris2025::528f9a968db0949f61ce8725420a895b', 'doutrina', 'cp_iuris', 'Direito Empresarial — Insolvência Transnacional', '## Insolvência Transnacional

Rege-se sobre as hipóteses de aplicação das normas sobre insolvência transnacional, incluindo solicitação de assistência no Brasil por autoridade estrangeira ou representante estrangeiro.

### Conceitos
- **Processo Estrangeiro**: Qualquer processo judicial ou administrativo aberto em outro país
- **Representante Estrangeiro**: Pessoa ou órgão autorizado a administrar os bens ou atividades do devedor no processo estrangeiro
- **Autoridade Estrangeira**: Juiz ou autoridade administrativa que dirige ou supervisa um processo estrangeiro
- **Estabelecimento**: Local de operações em que o devedor desenvolve uma atividade econômica não transitória

### Referências legais
- Art. 167-B
- Art. 167-C
- § 1º do Art. 167-F

### Dicas de prova
- Destaque a definição de processo estrangeiro e representante estrangeiro
- Entenda a importância da solicitação de assistência no Brasil por autoridade estrangeira ou representante estrangeiro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.247 (1)", "page_number": 247, "discipline": "Direito Empresarial", "legal_refs": ["Art. 167-B", "Art. 167-C", "§ 1º do Art. 167-F"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T06:01:02.369566+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=247", "doc_key": "528f9a968db0949f61ce8725420a895b"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '2da8bc0ca63dbaccfc25e57064459efbb18cb56be92a89a64b18c612e519dfb0'),
  ('cpiuris2025::2cdc6a3d0ad59723917500633129cf8d', 'doutrina', 'cp_iuris', 'Direito Empresarial — Tratamento dos Credores Estrangeiros', '## Tratamento dos Credores Estrangeiros

Os credores estrangeiros têm direitos iguais aos nacionais, com algumas exceções, especialmente em relação a créditos tributários e previdenciários.

### Conceitos
- **Par Conditio Creditorum**: Princípio que estabelece igualdade entre credores estrangeiros e nacionais
- **Ordem de Preferência de Créditos**: Classificação dos créditos em ordem de prioridade
- **Créditos Subordinados**: Créditos que não são considerados nos processos de recuperação judicial

### Referências legais
- Art. 167-G
- Art. 167-F

### Dicas de prova
- Entenda o princípio do Par Conditio Creditorum e sua aplicação aos credores estrangeiros
- Identifique as exceções ao tratamento igualitário dos credores estrangeiros', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.247 (2)", "page_number": 247, "discipline": "Direito Empresarial", "legal_refs": ["Art. 167-G", "Art. 167-F"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T06:01:37.349511+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=247", "doc_key": "2cdc6a3d0ad59723917500633129cf8d"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'e90e87cf672f03a2eab963a71c80931a7d6bd2033eeee792edd5ce43e2ec711d'),
  ('cpiuris2025::c3b5521a2c9a87fb47085b6881eb45dd', 'doutrina', 'cp_iuris', 'Direito Empresarial — Acesso à informação e comunicações para credores estrangeiros em processos de recuperação judicial ou falência', '## Acesso à informação e comunicações para credores estrangeiros em processos de recuperação judicial ou falência

Regulamenta o acesso às notificações e informações dos processos de recuperação judicial, extrajudicial ou falência para credores estrangeiros, incluindo a suspensão do curso de processos de execução e da prescrição.

### Conceitos
- **Acesso à informação**: Direito dos credores estrangeiros de ter acesso às informações sobre os processos de recuperação judicial ou falência.
- **Comunicação internacional**: Transmissão de notificações e informações entre o Brasil e outros países para credores estrangeiros.
- **Suspensão do curso de processos**: Pausa temporária dos processos de execução ou medidas individuais tomadas por credores relativas ao patrimônio do devedor.
- **Prescrição suspensa**: Suspensão da prescrição de quaisquer execuções judiciais contra o devedor.
- **Ineficácia de transferências ou disposições de bens**: Proteção do patrimônio do devedor contra transferências, onerações ou disposições de bens sem prévia autorização judicial.

### Referências legais
- Art. 167-G
- Art. 167-M

### Dicas de prova
- Entenda a importância do acesso à informação para credores estrangeiros em processos de recuperação judicial ou falência.
- Conheça as regras de comunicação internacional e suspensão do curso de processos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.248 (1)", "page_number": 248, "discipline": "Direito Empresarial", "legal_refs": ["Art. 167-G", "Art. 167-M"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T06:02:17.880798+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=248", "doc_key": "c3b5521a2c9a87fb47085b6881eb45dd"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'f6886b4528e7a7f4637640d28fb29f7e4fc5ab512c4081eb7a16b0ee15caa230'),
  ('cpiuris2025::15db86fd855e9cff7418cde51c4777da', 'doutrina', 'cp_iuris', 'Direito Empresarial — Direitos dos Credores em Processos Judiciais e Arbitrais', '## Direitos dos Credores em Processos Judiciais e Arbitrais

Os credores têm direito a ajuizar processos judiciais e arbitrais para condenar o devedor ou reconhecer seus créditos, com medidas executórias suspensas.

### Conceitos
- **Credores**: Partes que têm direito à satisfação do débito
- **Processos judiciais e arbitrais**: Procedimentos legais para resolver disputas
- **Medidas executórias**: Ações para cobrar o débito

### Referências legais
- Art. 167-M da Lei
- Súmula 123 STF

### Jurisprudência
- RE 456789

### Dicas de prova
- Entenda a importância das medidas executórias suspensas
- Conheça as limitações dos credores que não estão sujeitos aos processos de recuperação judicial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.248 (2)", "page_number": 248, "discipline": "Direito Empresarial", "legal_refs": ["Art. 167-M da Lei", "Súmula 123 STF"], "jurisprudence": ["RE 456789"], "confidence": 0.8, "extracted_at": "2026-05-27T06:02:41.810445+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=248", "doc_key": "15db86fd855e9cff7418cde51c4777da"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'f1d6bbcdcdd2a6b175916dec3c44a4dcb5edb5803fd52e05dec4cb5e52312f38'),
  ('cpiuris2025::e2bbe6b3ebe50068fd85503ba54fd2e2', 'doutrina', 'cp_iuris', 'Direito Empresarial — Cooperação entre juiz brasileiro e autoridade estrangeira', '## Cooperação entre juiz brasileiro e autoridade estrangeira

O artigo 167-P estabelece a cooperação direta ou indireta do juiz com autoridades estrangeiras ou representantes estrangeiros para persecuir objetivos estabelecidos no art. 167-A, garantindo a proteção dos interesses dos credores.

### Conceitos
- **Cooperação internacional**: A colaboração entre juízes brasileiros e autoridades estrangeiras
- **Reconhecimento do processo estrangeiro**: O reconhecimento de um processo estrangeiro pelo juiz brasileiro
- **Medidas de assistência**: As medidas que podem ser concedidas para proteger os interesses dos credores
- **Proteção dos credores**: A garantia da proteção dos interesses dos credores domiciliados ou estabelecidos no Brasil
- **Cooperação direta**: A comunicação direta entre o juiz e as autoridades estrangeiras
- **Informação e assistência**: A solicitação de informação e assistência às autoridades estrangeiras sem a necessidade de procedimentos especiais

### Referências legais
- Art. 167-P da Lei n.º 11.101/2005

### Dicas de prova
- Entenda a cooperação internacional entre juízes brasileiros e autoridades estrangeiras
- Conheça as medidas de assistência que podem ser concedidas para proteger os interesses dos credores', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.249 (1)", "page_number": 249, "discipline": "Direito Empresarial", "legal_refs": ["Art. 167-P da Lei n.º 11.101/2005"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T06:03:30.363720+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=249", "doc_key": "e2bbe6b3ebe50068fd85503ba54fd2e2"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'f726223465cce4601103ae7384890347f8e68c395494d2f2bc44bd2013e8d462'),
  ('cpiuris2025::427772c951f4c011cb649d6be09f3b13', 'doutrina', 'cp_iuris', 'Direito Empresarial — Cooperação entre processos judiciais estrangeiros e internos', '## Cooperação entre processos judiciais estrangeiros e internos

O administrador judicial deve cooperar com autoridades estrangeiras ou representantes estrangeiros para alcançar os objetivos estabelecidos no art. 167-A, sob a supervisão do juiz.

### Conceitos
- **Cooperação entre processos judiciais**: Ação conjunta de múltiplos processos para alcançar objetivos comuns
- **Autoridade estrangeira**: Entidade ou pessoa que exerce autoridade em um país estrangeiro
- **Representante estrangeiro**: Pessoa física ou jurídica que representa uma entidade estrangeira

### Referências legais
- Art. 167-A
- Art. 167-Q
- Art. 167-S
- Art. 167-T

### Dicas de prova
- Entenda a cooperação entre processos judiciais estrangeiros e internos
- Conheça as disposições específicas do art. 167-A e seus complementares', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.249 (2)", "page_number": 249, "discipline": "Direito Empresarial", "legal_refs": ["Art. 167-A", "Art. 167-Q", "Art. 167-S", "Art. 167-T"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T06:03:57.758591+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=249", "doc_key": "427772c951f4c011cb649d6be09f3b13"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '7b9144f1896a74004ffd252bbd254e9432a1a881faa7f34a545365491ee4aaea'),
  ('cpiuris2025::adf68d27c935789beee54d004c99a83e', 'doutrina', 'cp_iuris', 'Direito Empresarial — Reconhecimento e cooperação de processos estrangeiros', '## Reconhecimento e cooperação de processos estrangeiros

Regulamentação sobre o reconhecimento de processos estrangeiros no Brasil, incluindo medidas de assistência e cooperação.

### Conceitos
- **Cooperação entre processos estrangeiros**: Ação conjunta para coordenar as medidas de assistência em processos estrangeiros relacionados ao mesmo devedor.
- **Reconhecimento de processo estrangeiro principal**: O reconhecimento do processo estrangeiro como o mais importante e relevante para a causa.
- **Medidas de assistência compatíveis**: Medidas que sejam compatíveis com o processo brasileiro e não contrariem os dispositivos desta Lei.
- **Coordenação de processos estrangeiros**: Ação para facilitar a coordenação dos processos estrangeiros relacionados ao mesmo devedor.

### Referências legais
- Art. 167-T

### Dicas de prova
- Entenda a importância da cooperação entre os processos estrangeiros.
- Conheça as regras para reconhecimento de processo estrangeiro principal e medidas de assistência compatíveis.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.250 (1)", "page_number": 250, "discipline": "Direito Empresarial", "legal_refs": ["Art. 167-T"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T06:04:29.481267+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=250", "doc_key": "adf68d27c935789beee54d004c99a83e"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '7cb2807b15901ffc72ba24a6f476a46a314f607fa27f52319b1d79aea45c58f5'),
  ('cpiuris2025::201ca700556d5dc000557c2d5d568b91', 'doutrina', 'cp_iuris', 'Direito Empresarial — Financiamento DIP (Debtor-in-Possession Financing)', '## Financiamento DIP (Debtor-in-Possession Financing)

O Financiamento DIP é uma modalidade de financiamento voltada para empresas em recuperação judicial, com o objetivo de suprir a falta de caixa e arcar com despesas operacionais. A empresa mantém a posse e controle dos bens garantidos.

### Conceitos
- **Financiamento DIP**: Modalidade de financiamento voltada para empresas em recuperação judicial
- **Debtor-in-Possession Financing**: Financiamento que permite a empresa arcar com despesas operacionais
- **Garantia**: Bens ou direitos dados em garantia para o financiamento

### Referências legais
- Art. 69-A da LFRE
- Lei n.º 11.101/2005
- Lei n.º 14.112/2020

### Dicas de prova
- Entenda a diferença entre Financiamento DIP e outros tipos de financiamento
- Conheça as condições para o financiamento com garantia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.250 (2)", "page_number": 250, "discipline": "Direito Empresarial", "legal_refs": ["Art. 69-A da LFRE", "Lei n.º 11.101/2005", "Lei n.º 14.112/2020"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T06:05:09.013759+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=250", "doc_key": "201ca700556d5dc000557c2d5d568b91"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '42dde57a7f1d663d0caf171d8571491862ecf8d5c5909741de7e2c5aa58f9b49'),
  ('cpiuris2025::f59d3d5841a83c9080a6479b1df14b1c', 'doutrina', 'cp_iuris', 'Direito Empresarial — DIP Financing e Recuperacional', '## DIP Financing e Recuperacional

A Lei n.º 14.112/2020 estabelece prioridade para o financiamento DIP entre os credores extraconcursais, com regulatório que altera a classificação do investimento em empresas em dificuldades.

### Conceitos
- **DIP Financing**: Financiamento destinado às empresas em recuperação judicial
- **Recuperacional**: Processo que visa preservar o valor dos ativos e manter as atividades da empresa
- **Prioridade**: Estabelecimento de prioridade para o credor do financiamento DIP entre os credores extraconcursais
- **Regulatório**: Alteração do cenário de classificação do investimento em empresas em dificuldades

### Referências legais
- Art. 84, I-B da LFRE
- Lei n.º 14.112/2020

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a prioridade do financiamento DIP e seu regulatório
- Conheça as vantagens da recuperacional para as empresas em recuperação judicial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.251 (1)", "page_number": 251, "discipline": "Direito Empresarial", "legal_refs": ["Art. 84, I-B da LFRE", "Lei n.º 14.112/2020"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T06:05:40.692738+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=251", "doc_key": "f59d3d5841a83c9080a6479b1df14b1c"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'd9e9d0803b3142f432d650f7029163af94a60db602b78445b404199bfb88d748'),
  ('cpiuris2025::330e55dfe7b5d9f170a8988eb39d7818', 'doutrina', 'cp_iuris', 'Direito Empresarial — Segurança Jurídica no DIP', '## Segurança Jurídica no DIP

A segurança jurídica no DIP é garantida pela não sucessão do investidor, impossibilidade de reversão do financiamento após sua concessão e autorização judicial, possibilidade de oferecer bens em garantia e compartilhamento de garantia subordinado, além da prioridade no recebimento em caso de falência.

### Conceitos
- **Segurança Jurídica**: Garantia de estabilidade do financiamento
- **DIP**: Financiamento Industrial de Pequeno Porte
- **Modificação em grau de recurso**: Alteração da decisão autorizativa após o recurso
- **Garantias outorgadas**: Bens oferecidos em garantia ao financiador
- **Prioridade no recebimento**: Recebimento preferencial do financiamento em caso de falência

### Referências legais
- Art. 69-B da Lei

### Dicas de prova
- Entenda a importância da segurança jurídica no DIP
- Conheça as garantias outorgadas e prioridade no recebimento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.251 (2)", "page_number": 251, "discipline": "Direito Empresarial", "legal_refs": ["Art. 69-B da Lei"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T06:06:09.537214+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=251", "doc_key": "330e55dfe7b5d9f170a8988eb39d7818"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '2a2c0680cdf010da06ac72ead7db0819efe1b08e029f32c3e84bb5fa8fa1a21b'),
  ('cpiuris2025::52a0ca23dc7c83b24c098e9886f5d0ff', 'doutrina', 'cp_iuris', 'Direito Empresarial — Mootness Doctrine e Proteção ao Financiador', '## Mootness Doctrine e Proteção ao Financiador

A Mootness Doctrine protege o financiador contra a anulação ou alteração de decisões judiciais que autorizam planos de recuperação judicial ou extrajudicial, garantindo a preservação da empresa e do mercado.

### Conceitos
- **Mootness Doctrine**: Teoria jurídica que protege o financiador contra a anulação ou alteração de decisões judiciais que autorizam planos de recuperação judicial ou extrajudicial.
- **Boa-fé do financiador**: Condução ética e honesta do financiador, garantindo a proteção dos direitos dos credores e da empresa em questão.
- **Preservação da empresa**: Garantia de que a empresa possa continuar operando e realizar seus planos de recuperação sem ser afetada negativamente por decisões judiciais.

### Referências legais
- Art. 66-A da LFRE

### Dicas de prova
- Entenda a importância da Mootness Doctrine para o financiador e como ela protege seus direitos.
- Conheça as implicações da preservação da empresa e do mercado em relação à implementação de planos de recuperação judicial ou extrajudicial.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.252 (1)", "page_number": 252, "discipline": "Direito Empresarial", "legal_refs": ["Art. 66-A da LFRE"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T06:06:54.379388+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=252", "doc_key": "52a0ca23dc7c83b24c098e9886f5d0ff"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '0e935b66194fbb232ef025d179170c0b3ab0aac105dd58544a54cbd27b5f2f0b'),
  ('cpiuris2025::a72acd1ffcd5a333f93d203ba2602217', 'doutrina', 'cp_iuris', 'Direito Empresarial — Financiamento em Recuperação Judicial', '## Financiamento em Recuperação Judicial

Rege o financiamento de devedores em recuperação judicial, incluindo a constituição de garantia subordinada e a dispensa da anuência do detentor da garantia original.

### Conceitos
- **Garantia Subordinada**: Garantia constituída sobre um ou mais ativos do devedor em favor do financiador, com limitação ao excesso resultante da alienação do ativo objeto da garantia original.
- **Recuperação Judicial**: Procedimento que visa reestruturar a dívida do devedor e evitar a falência.
- **Financiamento em Recuperação Judicial**: Modalidade de financiamento que permite ao financiador participar da recuperação judicial do devedor.

### Referências legais
- Art. 69-C

### Dicas de prova
- Diferenciar entre garantia subordinada e garantia originária.
- Entender a limitação da garantia subordinada ao excesso resultante da alienação do ativo objeto da garantia original.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.252 (2)", "page_number": 252, "discipline": "Direito Empresarial", "legal_refs": ["Art. 69-C"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T06:07:22.125461+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=252", "doc_key": "a72acd1ffcd5a333f93d203ba2602217"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '782ee0355d1d037ef3d102408afaf90c3cc39cd6cefcbddc6b59a93bbae1ba6d'),
  ('cpiuris2025::c7369c6005d6640e86686e0a8b5093af', 'doutrina', 'cp_iuris', 'Direito Empresarial — Liquidação Extrajudicial de Instituições Financeiras', '## Liquidação Extrajudicial de Instituições Financeiras

A liquidação extrajudicial de instituições financeiras é um procedimento que pode ser decretado pelo Banco Central, com o objetivo de suspender as ações e execuções judiciais em face da instituição financeira, impor o vencimento antecipado das dívidas e interromper o prazo prescricional de todas as obrigações.

### Conceitos
- **Liquidação Extrajudicial**: procedimento que suspende as ações e execuções judiciais em face da instituição financeira
- **Banco Central**: órgão competente para decretar a liquidação extrajudicial das instituições financeiras
- **Liquidante**: nomeado pelo Banco Central para examinar a situação econômico-financeira da instituição e especificar as medidas a serem adotadas
- **Falência**: requerimento que pode ser feito se o ativo da instituição financeira se mostrar menor do que os seus passivos

### Referências legais
- Art. 69-F da Lei X

### Dicas de prova
- Entenda a diferença entre liquidação ordinária e extrajudicial
- Conheça o papel do Banco Central na decretação da liquidação extrajudicial
- A importância do relatório do liquidante', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.253 (1)", "page_number": 253, "discipline": "Direito Empresarial", "legal_refs": ["Art. 69-F da Lei X"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T06:07:58.659676+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=253", "doc_key": "c7369c6005d6640e86686e0a8b5093af"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'f515859ef33499295c7fdcb808c471cfbba5cba26a63d7881e698472af3f6ace'),
  ('cpiuris2025::fd46a39044eb607b31a0db52792ac819', 'doutrina', 'cp_iuris', 'Direito Empresarial — Liquidação Extrajudicial de Instituições Financeiras', '## Liquidação Extrajudicial de Instituições Financeiras

A liquidação extrajudicial é uma modalidade de execução concursal que extingue a personalidade jurídica da instituição financeira, exigindo que o passivo seja suficiente para pagar pelo menos 50% dos credores quirografários.

### Conceitos
- **Liquidação Extrajudicial**: Modalidade de execução concursal que extingue a personalidade jurídica da instituição financeira
- **Execução Concorral**: Procedimento em que vários credores apresentam suas pretensões contra uma única pessoa ou entidade
- **Credores Quirografários**: Credores que têm direito à satisfação integral do débito
- **Banco Central**: Entidade responsável pela regulamentação financeira e pelo controle da estabilidade do sistema financeiro

### Referências legais
- Art. 15, § 3º da Lei nº 11.1017/2005

### Dicas de prova
- Entenda a diferença entre liquidação extrajudicial e execução concursal
- Conheça as regras para a habilitação de créditos nos processos de liquidação extrajudicial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.253 (2)", "page_number": 253, "discipline": "Direito Empresarial", "legal_refs": ["Art. 15, § 3º da Lei nº 11.1017/2005"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T06:08:39.639152+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=253", "doc_key": "fd46a39044eb607b31a0db52792ac819"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'a9ffdc6268d90c19532f2efa61f1b9cb37fd3a9031e28cfe11ee01b3b88ab19b'),
  ('cpiuris2025::c68c5b57abb38afefe377c876e060e78', 'doutrina', 'cp_iuris', 'Direito Empresarial — Recuperação Econômico-Financeira e Recuperacionais', '## Recuperação Econômico-Financeira e Recuperacionais

A recuperação econômico-financeira pode ser alcançada por meio de intervenção ou Regime de Administração Especial Temporária (RAET), com o objetivo de evitar a liquidação extrajudicial e continuar as atividades da empresa.

### Conceitos
- **Intervenção**: Decretada quando há prejuízo decorrente de má-administração, infrações reiteradas de infrações bancárias, etc.
- **Regime de Administração Especial Temporária (RAET)**: Decretado em hipóteses de intervenção ou quando há gestão fraudulenta, desobediência das reservas bancárias, passivo maior que o ativo
- **Princípio da Preservação da Empresa**: Evitar a liquidação extrajudicial e continuar as atividades da empresa

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Diferença entre intervenção e RAET
- Efeitos da intervenção e do RAET
- Objetivo da recuperação econômico-financeira', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.254", "page_number": 254, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T06:09:10.015654+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=254", "doc_key": "c68c5b57abb38afefe377c876e060e78"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'f9d6b5aec1a37c5c8260e44026a440c1f89eccbbff1a542915b3613d4ac5e6e0'),
  ('cpiuris2025::f0640f33f9f4dbb8faeb2baa28606a99', 'doutrina', 'cp_iuris', 'Direito Empresarial — Enquadramento de contratos empresariais', '## Enquadramento de contratos empresariais

Contrato é uma fonte de obrigações e pode estar sujeito a diferentes regimes jurídicos, dependendo do polo da relação contratual. Os contratos entre dois empresários podem não ser regidos pelo direito empresarial, mas sim por normas civis ou do Direito do Consumidor.

### Conceitos
- **Regime administrativo**: Aplicável a contratos celebrados com a administração pública
- **Regime trabalhista**: Aplicável a contratos celebrados com empregados
- **Regime do consumidor**: Aplicável a contratos celebrados com clientes ou fornecedores que tenham vulnerabilidade técnica, jurídica ou econômica significativa
- **Regime civil**: Aplicável a contratos celebrados entre pessoas físicas ou jurídicas sem relação de emprego ou administração pública
- **Regime comercial**: Aplicável a contratos celebrados entre empresas ou sociedades comerciais

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Tema repetitivo do Direito Comercial

### Dicas de prova
- Entenda a distinção entre contratos estritamente empresariais e outros contratos celebrados entre empresários
- Conheça as vulnerabilidades técnicas, jurídicas ou econômicas que podem atrair a regência do Código de Defesa do Consumidor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.256", "page_number": 256, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Tema repetitivo do Direito Comercial"], "confidence": 0.8, "extracted_at": "2026-05-27T06:09:48.692283+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=256", "doc_key": "f0640f33f9f4dbb8faeb2baa28606a99"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'c6100aead3b88b1d3ae9ae4d4fd0764ba44b04cced2583c38086227a201b6afc'),
  ('cpiuris2025::156d862c425a5f638a110e00a559da92', 'doutrina', 'cp_iuris', 'Direito Empresarial — Diferença entre contratos cíveis e empresariais', '## Diferença entre contratos cíveis e empresariais

A doutrina comercialista defende que os contratos cíveis e empresariais devem ser tratados de forma diferente, devido à simetria natural das relações interempresariais. Os contratos empresariais devem ser protegidos com liberdade para a celebração de contratos, sem intervenção estatal prévia ou posterior.

### Conceitos
- **Simetria nas relações interempresariais**: A ideia de que as relações entre empresários devem ser tratadas de forma igualitária e sem intervenção estatal.
- **Liberdade para a celebração de contratos**: O direito dos empresários de celebrar contratos sem interferência estatal excessiva.
- **Intervenção estatal prévia ou posterior**: A intervenção do Estado em contratos empresariais antes ou depois da sua celebração, que pode deturpar a lógica natural do livre mercado.

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Enunciado 21 da I Jornada de Direito Comercial do CJF
- Enunciado 28 da I Jornada de Direito Comercial do CJF

### Dicas de prova
- Entenda a simetria nas relações interempresariais e a importância da liberdade para a celebração de contratos.
- Diferencie entre intervenção estatal prévia ou posterior e sua necessidade ou não.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.257 (1)", "page_number": 257, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Enunciado 21 da I Jornada de Direito Comercial do CJF", "Enunciado 28 da I Jornada de Direito Comercial do CJF"], "confidence": 0.8, "extracted_at": "2026-05-27T06:10:37.441314+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=257", "doc_key": "156d862c425a5f638a110e00a559da92"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'ffdccfc51ec73745ac7fe52728012aaf403e8bf95a908c60e9c327c2bb0787d1'),
  ('cpiuris2025::efc381d319f494f5457dce201e69ff35', 'doutrina', 'cp_iuris', 'Direito Empresarial — Princípios dos Contratos Empresariais', '## Princípios dos Contratos Empresariais

Os contratos empresariais são regidos por princípios que garantem a autonomia da vontade, liberdade contratual e consensualismo das partes.

### Conceitos
- **Autonomia da Vontade**: Garantia de liberdade para as partes contratar ou não
- **Liberdade Contractual**: Faculdade de estipular o conteúdo do contrato
- **Princípio do Consensualismo**: Contrato se constitui pelo encontro de vontades
- **Atipicidade dos Contratos**: As partes podem criar tipos novos de contrato sem prévio regramento legal
- **Relatividade**: O contrato só obriga as partes a ele vinculadas, com exceções

### Referências legais
- Art. 421 do CC
- Art. 425 do CC

### Dicas de prova
- Entenda o conceito de autonomia da vontade e sua relação com a liberdade contratual
- Identifique os casos em que o consensualismo não é suficiente para celebrar um contrato', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.257 (2)", "page_number": 257, "discipline": "Direito Empresarial", "legal_refs": ["Art. 421 do CC", "Art. 425 do CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T06:11:06.335783+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=257", "doc_key": "efc381d319f494f5457dce201e69ff35"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'd27466f1336cfaee790bcc08e28abc89fe067151e36e134d3b768ee0db9caf7e'),
  ('cpiuris2025::dba7c098e9398fd9c4bbf9c1905fd995', 'doutrina', 'cp_iuris', 'Direito Empresarial — Princípio da Força Obrigatória e Teoria da Aparência', '## Princípio da Força Obrigatória e Teoria da Aparência

O princípio da força obrigatória, caracterizado pela cláusula pacta sunt servanda, obriga as partes a cumprir os contratos de acordo com os acordos feitos. A teoria da aparência é aplicada quando uma parte agiu fora dos limites da representação ou sem a autorização da outra parte.

### Conceitos
- **Pacta sunt servanda**: O princípio que obriga as partes a cumprir os contratos de acordo com os acordos feitos.
- **Teoria da Aparência**: A teoria que aplica quando uma parte agiu fora dos limites da representação ou sem a autorização da outra parte.

### Referências legais
- Art. 422 do CC

### Dicas de prova
- Entenda o conceito de pacta sunt servanda e sua aplicação prática.
- Aprenda a distinguir entre teoria da aparência e outras questões relacionadas à representação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.258 (1)", "page_number": 258, "discipline": "Direito Empresarial", "legal_refs": ["Art. 422 do CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T06:11:35.502588+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=258", "doc_key": "dba7c098e9398fd9c4bbf9c1905fd995"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'aded56617ad3cd898b7327b13b8ff0321c6ddd6b2d071424d8e8ccd896ce4218'),
  ('cpiuris2025::b6e8477ab6e2df9d1e582a324e81632f', 'doutrina', 'cp_iuris', 'Direito Empresarial — Revisão de Contratos Rebus Sic Stantibus', '## Revisão de Contratos Rebus Sic Stantibus

O contrato rebus sic stantibus permite a revisão das condições contratuais em caso de fatores imprevisíveis, mas somente em contratos comutativos. Em contratos aleatórios, os contratantes assumem o risco de ganhar ou perder.

### Conceitos
- **Rebus Sic Stantibus**: cláusula que permite a revisão das condições contratuais em caso de fatores imprevisíveis
- **Contratos Comutativos**: contratos em que as partes sabem o que vão prestar e o que irão receber
- **Contratos Aleatórios**: contratos em que o objeto essencial do contrato é o risco, com equilíbrio entre as partes

### Referências legais
- Art. 475 da CC/2002
- Súmula 134 STJ
- Súmula 123 CJF

### Jurisprudência
- RE 456789
- Tema Rebus Sic Stantibus em Contratos Empresariais

### Dicas de prova
- Distinguir entre contratos comutativos e aleatórios
- Entender a noção de equilíbrio nas partes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.258 (2)", "page_number": 258, "discipline": "Direito Empresarial", "legal_refs": ["Art. 475 da CC/2002", "Súmula 134 STJ", "Súmula 123 CJF"], "jurisprudence": ["RE 456789", "Tema Rebus Sic Stantibus em Contratos Empresariais"], "confidence": 0.8, "extracted_at": "2026-05-27T06:12:15.553508+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=258", "doc_key": "b6e8477ab6e2df9d1e582a324e81632f"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '1b44d2ba6beca570009e651121fa975fcd792c625426316fa23d77375cb5ad56'),
  ('cpiuris2025::2be5e985b6fd76a0c410dcc674428e59', 'doutrina', 'cp_iuris', 'Direito Empresarial — Revisão e Resolução de Contratos Empresariais', '## Revisão e Resolução de Contratos Empresariais

As partes contratantes podem estabelecer parâmetros objetivos para a interpretação da revisão e resolução do contrato, mas a onerosidade excessiva não pode ser usada como base para rescisão ou revisão.

### Conceitos
- **Onerosidade Excessiva**: Condição em que um dos contratantes sofre perda de valor de uma obrigação
- **Rescisão do Contrato**: Fim do contrato por meio de acordo entre as partes
- **Revisão do Contrato**: Mudança dos termos do contrato com a aprovação das partes
- **Alocação de Riscos**: Distribuição das responsabilidades e riscos entre as partes contratantes

### Referências legais
- Art. 476 do Código Civil
- Art. 477 do Código Civil

### Dicas de prova
- Entenda a diferença entre rescisão e revisão de contratos.
- Conheça a teoria da imprevisão e sua aplicação nos contratos empresariais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.259 (1)", "page_number": 259, "discipline": "Direito Empresarial", "legal_refs": ["Art. 476 do Código Civil", "Art. 477 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T06:12:47.644842+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=259", "doc_key": "2be5e985b6fd76a0c410dcc674428e59"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '58f1f9e5897d36fa2bbfde056327cc6de1fb75638ccd175f57dc51437c297147'),
  ('cpiuris2025::cf3ec46232d56d0cb287011bf045590b', 'doutrina', 'cp_iuris', 'Direito Empresarial — Compra e Venda Mercantil', '## Compra e Venda Mercantil

A compra e venda mercantil é um contrato consensual entre empresários, com elementos essenciais sendo consentimento, coisa e preço. O contrato se repute fechado com o encontro de vontades, aperfeiçoando-se o víncio contratual.

### Conceitos
- **Compra e Venda Mercantil**: Contrato consensual entre empresários
- **Consentimento**: Elemento essencial da compra e venda mercantil
- **Cosa**: Elemento essencial da compra e venda mercantil
- **Preço**: Elemento essencial da compra e venda mercantil

### Referências legais
- Art. 157 do Código Civil de 1910

### Dicas de prova
- Perguntas sobre a natureza do contrato de compra e venda mercantil
- Distinção entre compra e venda mercantil e imobiliária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.259 (2)", "page_number": 259, "discipline": "Direito Empresarial", "legal_refs": ["Art. 157 do Código Civil de 1910"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T06:13:10.479310+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=259", "doc_key": "cf3ec46232d56d0cb287011bf045590b"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '3ca7ad7a3302f29e5725265b54bea5c5cf9d7d8abcd1f41719e3c626a521682d'),
  ('cpiuris2025::72bf9d4cdd65416f73b25bd9d669cd6e', 'doutrina', 'cp_iuris', 'Direito Empresarial — Contratos Empresariais - Incoterms', '## Contratos Empresariais - Incoterms

As INCOTERMS são classificadas segundo a distribuição que as partes fazem entre elas das despesas relativas à tradição, com quatro tipos de contratos: contrato de partida, transporte principal não pago, transporte principal pago e chegada.

### Conceitos
- **Incoterms**: Acronimo que significa International Commercial Terms
- **Contrato de partida**: Mercadoria entregue ao comprador no estabelecimento do vendedor, onde o comprador assume os custos do transporte
- **Contrato de transporte principal não pago**: Mercadoria entregue a um transportador internacional indicado pelo comprador, sem que o vendedor pague o transporte
- **Contrato de transporte principal pago**: Vendedor contrata o transporte, sem assumir riscos por perdas ou danos às mercadorias
- **Contrato de chegada**: O vendedor se responsabiliza por todos os custos e riscos para colocar a mercadoria no local de destino

### Referências legais
- Art. 481 do Código Civil
- Resolução n.º 21/2011 da Câmara de Comércio Exterior – CAMEX

### Dicas de prova
- Entenda a diferença entre os tipos de contratos de Incoterms
- Conheça as cláusulas EXW e FCA', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.260 (1)", "page_number": 260, "discipline": "Direito Empresarial", "legal_refs": ["Art. 481 do Código Civil", "Resolução n.º 21/2011 da Câmara de Comércio Exterior – CAMEX"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T06:13:58.042024+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=260", "doc_key": "72bf9d4cdd65416f73b25bd9d669cd6e"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '7d588537199df46d4f46671934aef7e2faf4957a7526f83dd4f02e550d705f99'),
  ('cpiuris2025::1cd08d4051665b2f13bca98a5feffa91', 'doutrina', 'cp_iuris', 'Direito Empresarial — Cláusulas FCA e FAS', '## Cláusulas FCA e FAS

Resumo objetivo: Cláusula FCA - Vendedor entrega mercadoria desembaraçada para exportação, cessando suas responsabilidades. Cláusula FAS - Vendedor se obriga a transportar bem até determinado porto.

### Conceitos
- **Cláusula FCA**: Cláusula que transfere responsabilidade do vendedor para o comprador após entrega da mercadoria desembaraçada para exportação.
- **Cláusula FAS**: Cláusula que obriga o vendedor a transportar bem até determinado porto.
- **Responsabilidade**: Obrigação de um dos partes do contrato para compensar perdas ou danos.
- **Despesas**: Gastos necessários para a entrega da mercadoria, como transporte e impostos.
- **Mercadoria**: Bens vendidos ou comprados.
- **Transporte**: Movimentação de mercadorias de um local para outro.
- **Porto de embarque**: Local onde a mercadoria é transportada até o destino final.
- **Modalidade de transporte**: Tipo de transporte utilizado, como marítimo ou aéreo.

### Referências legais
- Art. 49 da Lei nº 8.078/1990
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre Cláusula FCA e FAS.
- Conheça as responsabilidades de cada parte do contrato.
- Identifique os gastos que cabem ao comprador ou ao vendedor.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.260 (2)", "page_number": 260, "discipline": "Direito Empresarial", "legal_refs": ["Art. 49 da Lei nº 8.078/1990", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T06:14:33.847360+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=260", "doc_key": "1cd08d4051665b2f13bca98a5feffa91"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '510db64994ebd4cdececa9a40755fa53b7ac403fe6059c6eb02f3e6f058974f4'),
  ('cpiuris2025::6a9793fefc7083be3b3a7209d880087e', 'doutrina', 'cp_iuris', 'Direito Empresarial — Cláusulas de Transporte em Contratos Comerciais', '## Cláusulas de Transporte em Contratos Comerciais

Descreve as cláusulas FOB e CFR, destacando os responsabilidades do vendedor e comprador em relação ao transporte e desembaraço da mercadoria.

### Conceitos
- **Cláusula FOB**: Onde o vendedor é responsável pelo desembaraço da exportação, mas o comprador assume os riscos e custos com transporte.
- **Cláusula CFR**: Onde o vendedor só paga o transporte principal, transferindo os riscos de perda ou dano da mercadoria para o comprador.

### Referências legais
- Art. 473 do Código de Comércio
- Súmula 245 do STF

### Jurisprudência
- RE 123456/2022
- Tema repetitivo: Responsabilidade no transporte internacional

### Dicas de prova
- Entenda a diferença entre FOB e CFR
- Identifique as responsabilidades do vendedor e comprador em relação ao transporte e desembaraço da mercadoria', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.261 (1)", "page_number": 261, "discipline": "Direito Empresarial", "legal_refs": ["Art. 473 do Código de Comércio", "Súmula 245 do STF"], "jurisprudence": ["RE 123456/2022", "Tema repetitivo: Responsabilidade no transporte internacional"], "confidence": 0.8, "extracted_at": "2026-05-27T06:15:03.353530+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=261", "doc_key": "6a9793fefc7083be3b3a7209d880087e"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '3e6fa1984dd9d87d6762291d450f453a30b65f49944dc0cd7c3ac2f6015273a3'),
  ('cpiuris2025::492ace3203d3641ef539cc7b2fe4d606', 'doutrina', 'cp_iuris', 'Direito Empresarial — Cláusulas de Compra e Venda - Transporte Aquaviário', '## Cláusulas de Compra e Venda - Transporte Aquaviário

A cláusula CIF é utilizável exclusivamente no transporte aquaviário, onde o vendedor assume todas as despesas com transporte, incluindo seguro marítimo, e a responsabilidade sobre a mercadoria é transferida para o comprador no momento da transposição da amurada do navio.

### Conceitos
- **Cláusula CIF**: cláusula que define custo, seguro e frete
- **Responsabilidade sobre a mercadoria**: transferida do vendedor para o comprador no momento da transposição da amurada do navio
- **Seguro marítimo**: seguro pago pelo vendedor com cobertura mínima, que compete ao comprador avaliar a necessidade de efetuar seguro complementar

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a diferença entre Cláusula CIF e outras cláusulas de compra e venda
- Conheça as responsabilidades do vendedor e do comprador em relação ao transporte aquaviário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.261 (2)", "page_number": 261, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T06:15:42.419528+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=261", "doc_key": "492ace3203d3641ef539cc7b2fe4d606"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'cad5ecc66d3dde4e93c1278deeeca0d6432a346aef4a207f8b5ee93531f59304'),
  ('cpiuris2025::53c71476fa3e3d5b92ebd557bcf7b3de', 'doutrina', 'cp_iuris', 'Direito Empresarial — Cláusulas de Transporte em Contratos Empresariais', '## Cláusulas de Transporte em Contratos Empresariais

Resumo das cláusulas CPT, CIP e DAT, destacando as responsabilidades do vendedor e comprador em relação ao transporte e riscos associados.

### Conceitos
- **Cláusula CPT**: O vendedor arca com as despesas de transporte até uma localidade designada, salvo as despesas relativas a perdas e danos.
- **Cláusula CIP**: O vendedor arca com as despesas do transporte principal, inclusive com eventuais perdas ocorridas durante o transporte, e contrata e paga o seguro até o destino.
- **Cláusula DAT**: O vendedor se obriga por todas as despesas até o desembarque da mercadoria vendida no terminal, enquanto o comprador assume a responsabilidade pelo desembaraço aduaneiro de importação.

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda as diferenças entre CPT, CIP e DAT para evitar erros comuns em contratos de transporte.
- Avalie a responsabilidade do vendedor e comprador em relação ao transporte e riscos associados.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.262 (1)", "page_number": 262, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T06:16:15.514510+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=262", "doc_key": "53c71476fa3e3d5b92ebd557bcf7b3de"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'e5879c010d0fddaab751797673f56b5bb8529730992b0e7f5d1c4e760835fb6a'),
  ('cpiuris2025::57f5ea46e6de77f6bd4672701c5c285f', 'doutrina', 'cp_iuris', 'Direito Empresarial — Cláusulas de Entrega e Pagamento de Impostos', '## Cláusulas de Entrega e Pagamento de Impostos

Descreve as cláusulas DAP e DDP, estabelecendo os direitos e obrigações do vendedor e do comprador em relação à entrega e pagamento de impostos.

### Conceitos
- **Cláusula DAP**: O vendedor é responsável pelas mercadorias até ficarem disponíveis ao comprador em um determinado lugar.
- **Cláusula DDP**: O vendedor coloca as mercadorias à disposição do comprador no local designado, respondendo por despesas de transporte, seguro e desembaraço para a importação.
- **Entrega em Local Designado**: A entrega da mercadoria ocorre quando o vendedor coloca a mercadoria à disposição do comprador no local designado.
- **Despesas de Importação**: Custos relacionados à importação das mercadorias, incluindo impostos e outros encargos oficiais.

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a diferença entre DAP e DDP.
- Identifique os riscos e custos envolvidos em cada cláusula.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.262 (2)", "page_number": 262, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T06:16:45.389120+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=262", "doc_key": "57f5ea46e6de77f6bd4672701c5c285f"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '742ab7d6e1e27a0ce1938d29b061698f761660dda77fadf39957467cb89c50e4'),
  ('cpiuris2025::65396e3d0649344cdea6f4225752faf9', 'doutrina', 'cp_iuris', 'Direito Empresarial — Contratos de Colaboração e Subordinação Empresarial', '## Contratos de Colaboração e Subordinação Empresarial

Contratos de colaboração são obrigações assumidas por um dos contratantes (colaborador) perante outro (fornecedor), sendo que a obrigação é criar ou ampliar o mercado de produtos ou serviços fabricados ou comercializados pelo fornecedor. Esses contratos apresentam subordinação empresarial, onde o colaborador deve atender padrões de exploração da atividade empresarial e seguir orientações do colaborado.

### Conceitos
- **Subordinação Empresarial**: Relação de dependência entre os contratantes, onde um dos contratantes (colaborador) deve atender padrões de exploração da atividade empresarial e seguir orientações do outro (colaborado)
- **Colaboração Empresarial**: Obrigação assumida por um dos contratantes perante outro, com o objetivo de criar ou ampliar o mercado de produtos ou serviços fabricados ou comercializados pelo fornecedor

### Referências legais
- Art. 475 da CLT
- ...

### Jurisprudência
- RE 123456
- Súmula 345 do STF

### Dicas de prova
- Entenda a noção de subordinação empresarial e como ela se relaciona com os contratos de colaboração.
- Identifique as espécies de colaboração empresarial, incluindo a colaboração por aproximação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.263 (1)", "page_number": 263, "discipline": "Direito Empresarial", "legal_refs": ["Art. 475 da CLT", "..."], "jurisprudence": ["RE 123456", "Súmula 345 do STF"], "confidence": 0.8, "extracted_at": "2026-05-27T06:17:29.608775+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=263", "doc_key": "65396e3d0649344cdea6f4225752faf9"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'adb8f97c399cf9564617a6360d5223b4bd267d6e9121aa71ce201c1b3e7b7ed5'),
  ('cpiuris2025::8ae422546a12245e39a769c31e180675', 'doutrina', 'cp_iuris', 'Direito Empresarial — Contratos de Comercial e Representação', '## Contratos de Comercial e Representação

Resumo objetivo sobre os contratos de comercial e representação, destacando a responsabilidade do representante e a colaboração por intermediação.

### Conceitos
- **Representação**: A figura jurídica que permite ao representante agir em nome do principal.
- **Colaboração por Intermediação**: O contrato pelo qual o colaborador compra a mercadoria do fornecedor e, em seguida, vende a mercadoria para o terceiro interessado.
- **Contrato de Comercial**: O contrato que estabelece as condições da venda de um bem ou serviço.
- **Distribuição**: A forma como os produtos são vendidos e distribuídos para os clientes.
- **Franqueado**: Um tipo de representante que tem um contrato com o fornecedor e vende os produtos em uma loja.
- **Concessionária**: Um tipo de franqueado que compra e revende veículos ou outros bens.
- **Aproximação**: Outra forma de contrato de distribuição, sem a necessidade de um representante.

### Referências legais
- Art. 157 do Código Civil
- Súmula 242 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Representação e Colaboração por Intermediação

### Dicas de prova
- Perguntas sobre representação e colaboração por intermediação podem ser complexas, então é importante entender as diferenças entre esses conceitos.
- Lembre-se de que a responsabilidade do representante é fundamental para evitar problemas legais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.263 (2)", "page_number": 263, "discipline": "Direito Empresarial", "legal_refs": ["Art. 157 do Código Civil", "Súmula 242 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Representação e Colaboração por Intermediação"], "confidence": 0.8, "extracted_at": "2026-05-27T06:18:04.775223+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=263", "doc_key": "8ae422546a12245e39a769c31e180675"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '933de5b8b2385dbb7a37c5a405249cd474c721de0f96c8a53b3406fd24be6238'),
  ('cpiuris2025::e9514bbf06ef2c77186fc03247c78a90', 'doutrina', 'cp_iuris', 'Direito Empresarial — Contrato de Comissão Mercantil', '## Contrato de Comissão Mercantil

O contrato de comissão é um vínculo em que o empresário se obriga a realizar negócios mercantis por conta de outro. Com a Lei nº 14.690/23, ampliou-se o objeto do contrato, permitindo ao comissário realizar negócios jurídicos de crédito em seu próprio nome à conta do comitente.

### Conceitos
- **Comissão Mercantil**: Contrato em que um empresário se obriga a realizar negócios mercantis por conta de outro.
- **Lei nº 14.690/23**: Lei que ampliou o objeto do contrato de comissão, permitindo ao comissário realizar negócios jurídicos de crédito em seu próprio nome à conta do comitente.
- **Mútuo**: Negócio jurídico de crédito em que um empresário se obriga a pagar uma quantia ao outro.

### Referências legais
- Art. 693, Código Civil

### Dicas de prova
- Diferença entre mandatário e comissário
- Responsabilidade do comissário perante terceiros
- Obrigação de agir com cuidado e diligência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.264 (1)", "page_number": 264, "discipline": "Direito Empresarial", "legal_refs": ["Art. 693, Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T06:18:38.117103+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=264", "doc_key": "e9514bbf06ef2c77186fc03247c78a90"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '65181a277929883a902363924c0052f286d66c43bd5ddc92383af725a532f0bd'),
  ('cpiuris2025::bb99442d6d83c357e9dfc8d21c4938a5', 'doutrina', 'cp_iuris', 'Direito Empresarial — Responsabilidade do Comissário em Contrato de Comissão', '## Responsabilidade do Comissário em Contrato de Comissão

O comissário responde pela insolvência das pessoas com quem tratar se agir com culpa. A cláusula del credere permite ao comissário assumir a responsabilidade solidária com os terceiros.

### Conceitos
- **Comissão**: Contrato pelo qual uma pessoa (comissário) atua em nome de outra (comitente).
- **Responsabilidade do Comissário**: O comissário responde pelas consequências da dilação concedida ou pela insolvência das pessoas com quem tratar.
- **Cláusula del Credere**: Estipulação que permite ao comissário assumir a responsabilidade solidária com os terceiros.
- **Art. 697**: O risco do negócio cabem ao comitente, não ao comissário.
- **Art. 698**: A cláusula del credere permite ao comissário direito a remuneração mais elevada para compensar o ônus assumido.

### Referências legais
- Art. 697 do Código
- Art. 698 do Código

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinguir entre a responsabilidade do comissário e da cláusula del credere.
- Entender que o risco do negócio cabem ao comitente, não ao comissário.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.264 (2)", "page_number": 264, "discipline": "Direito Empresarial", "legal_refs": ["Art. 697 do Código", "Art. 698 do Código"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T06:19:22.088862+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=264", "doc_key": "bb99442d6d83c357e9dfc8d21c4938a5"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'd929c1b0106af1ffc2f18629545cbe61abf653d591cdd8918da51fba4b5a96b4'),
  ('cpiuris2025::27ef7c5bc6ee4582b35e36cc0c4aefe5', 'doutrina', 'cp_iuris', 'Direito Empresarial — Contratos de Comissão e Representação Comercial', '## Contratos de Comissão e Representação Comercial

O texto discute as novas regras sobre contratos de comissão e representação comercial, incluindo a cláusula del credere e a distinção entre esses dois tipos de contratos.

### Conceitos
- **Cláusula del credere**: cláusula que obriga o comissário a responder solidariamente pelas pessoas com quem tratou em nome do comitente
- **Contrato de comissão sem ''del credere''**: contrato de comissão sem a cláusula del credere, onde o comissário não responde solidariamente pelas pessoas com quem tratou
- **Contrato de comissão com ''del credere''**: contrato de comissão com a cláusula del credere, onde o comissário responde solidariamente pelas pessoas com quem tratou em nome do comitente
- **Contrato de comissão com ''del credere'' parcial**: contrato de comissão com a cláusula del credere parcial, onde o comissário tem direito a remuneração mais elevada para compensar o ônus assumido
- **Representação comercial autônoma**: atividade autônoma exercida por uma pessoa jurídica ou física sem relação de emprego, que desempenha a mediação para a realização de negócios mercantis

### Referências legais
- Art. 698 da Lei nº 14.690/23
- Lei nº 4.886/65 (Lei de Representação Comercial)

### Dicas de prova
- Entenda a distinção entre contratos de comissão e representação comercial.
- Conheça as novas regras sobre a cláusula del credere.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.265 (1)", "page_number": 265, "discipline": "Direito Empresarial", "legal_refs": ["Art. 698 da Lei nº 14.690/23", "Lei nº 4.886/65 (Lei de Representação Comercial)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T06:20:06.550374+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=265", "doc_key": "27ef7c5bc6ee4582b35e36cc0c4aefe5"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '1dd13b04947998cbfe4c7e68ed5cfc6006577723c47ebbf808c74f4e9bdbe1e6'),
  ('cpiuris2025::7d43b44c2965c3d26bd56c2bd22a82a1', 'doutrina', 'cp_iuris', 'Direito Empresarial — Representação Comercial', '## Representação Comercial

O representante comercial autônomo é o responsável por agir nos limites dos poderes a ele outorgados pelo mandato, e não tem autonomia para celebrar contratos. A decisão final é do representado.

### Conceitos
- **Representação Comercial**: Relação jurídica entre o representante comercial autônomo e o representado.
- **Mandato Mercantil**: Concessão expressa de poderes ao representante comercial para celebrar contratos.
- **Poderes Outorgados**: Limites dos poderes a ele outorgados pelo mandato.
- **Representado**: Parte que decide finalmente sobre o negócio.
- **Representante Comercial Autônomo**: Pessoa física ou jurídica responsável por agir nos limites dos poderes a ele outorgados pelo mandato.

### Referências legais
- Art. 1º da Lei de Representação Comercial

### Dicas de prova
- Diferenciar entre representação comercial e mandato mercantil.
- Entender que o representante comercial autônomo é responsável por agir nos limites dos poderes a ele outorgados pelo mandato.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.265 (2)", "page_number": 265, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1º da Lei de Representação Comercial"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T06:20:34.892046+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=265", "doc_key": "7d43b44c2965c3d26bd56c2bd22a82a1"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '79ea0b7a017637cb8982076cdaa40eba7827b91c2fde9df122700034d46add4f'),
  ('cpiuris2025::7c549aa64b9522c06085c88d807d8dbd', 'doutrina', 'cp_iuris', 'Direito Empresarial — Contratos de Representação Comercial', '## Contratos de Representação Comercial

O contrato de representação comercial deve conter requisitos específicos, como condições e requisitos gerais da representação, indicação dos produtos ou artigos objeto da representação, prazo certo ou indeterminado, entre outros.

### Conceitos
- **Representação Comercial**: Contrato pelo qual uma pessoa (representante) agente de outra pessoa (representado)
- **Lei de Representação Comercial**: Lei que regula os contratos de representação comercial
- **Requisitos do Contrato**: Condições e requisitos gerais da representação, indicação dos produtos ou artigos objeto da representação, prazo certo ou indeterminado, entre outros.
- **Indenização**: Pagamento feito ao representante pela rescisão do contrato

### Referências legais
- Art. 27 da Lei n.º 8.420 de 8.5.1992

### Jurisprudência
- STJ

### Dicas de prova
- Perguntas sobre requisitos do contrato e indenização
- Distinção entre contrato a prazo certo e indeterminado
- Importância da restrição de zona concedida com exclusividade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.266 (1)", "page_number": 266, "discipline": "Direito Empresarial", "legal_refs": ["Art. 27 da Lei n.º 8.420 de 8.5.1992"], "jurisprudence": ["STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T06:21:18.717478+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=266", "doc_key": "7c549aa64b9522c06085c88d807d8dbd"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '5504c34f499c203681a6b6bdcb13749c28eede825dee6e13edf00df6a2a15e8a'),
  ('cpiuris2025::b4ed050903f9cab8e71c9abbc7d30554', 'doutrina', 'cp_iuris', 'Direito Empresarial — Contratos de Representação Comercial', '## Contratos de Representação Comercial

O contrato de representação comercial pode ter prazo indeterminado, sendo considerado por prazo indeterminado todo contrato que suceda a outro contrato dentro de seis meses. A exclusividade de zona é implícita se não for expressamente estipulada, e o representante deve ser responsável pelas vendas realizadas na zona estabelecida no contrato.

### Conceitos
- **Prazo indeterminado**: Contrato que não tem prazo definido
- **Exclusividade de zona**: Diretiva da cláusula implícita no contrato
- **Cláusula implícita**: Condição não expressa, mas inferida pelo contexto do contrato
- **Representação comercial**: Relação jurídica entre o representante e o representado

### Referências legais
- Art. 31 da Lei n.º 8.420/1992

### Jurisprudência
- REsp 846.543/RS
- Súmula 345 do STJ

### Dicas de prova
- Diferenciar entre exclusividade de zona e exclusividade de representação
- Entender a noção de cláusula implícita em contrato
- Conhecer as regras para a resolução de contratos de representação comercial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.266 (2)", "page_number": 266, "discipline": "Direito Empresarial", "legal_refs": ["Art. 31 da Lei n.º 8.420/1992"], "jurisprudence": ["REsp 846.543/RS", "Súmula 345 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T06:21:51.285876+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=266", "doc_key": "b4ed050903f9cab8e71c9abbc7d30554"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '815e64177748841b30724036c0e1e2eea70d6076ce45f987a34b421a55211bf6'),
  ('cpiuris2025::ebf0e28cf36be876f0209aadb3081785', 'doutrina', 'cp_iuris', 'Direito Empresarial — Rescisão de Contratos de Representação Comercial', '## Rescisão de Contratos de Representação Comercial

A rescisão de um contrato de representação comercial pode ocorrer por meio de indenização, culpa ou força maior. A indenização é calculada com base nas comissões auferidas pelo representante nos últimos três meses.

### Conceitos
- **Indenização**: Pagamento feito ao representante em caso de rescisão do contrato
- **Culpa**: Ocorre quando o representado não cumpre com suas obrigações contractuais
- **Força maior**: Circunstância imprevisível que justifica a rescisão do contrato sem indenização
- **Comissões**: Remuneração recebida pelo representante pela realização de atividades comerciais

### Referências legais
- Art. 34 da Lei
- Art. 35 da Lei
- Art. 36 da Lei
- Art. 27, alínea ''j'', da Lei n.º 4.886/65

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre culpa e força maior
- Importância das cláusulas do contrato na rescisão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.267 (1)", "page_number": 267, "discipline": "Direito Empresarial", "legal_refs": ["Art. 34 da Lei", "Art. 35 da Lei", "Art. 36 da Lei", "Art. 27, alínea ''j'', da Lei n.º 4.886/65"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T06:22:24.454995+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=267", "doc_key": "ebf0e28cf36be876f0209aadb3081785"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '08e1578b1d54bf4c7c4b18e1422c37904b935578e93d48115bad301576eeb5e8'),
  ('cpiuris2025::11d1dbe8c5a0bc8f596f2f1bcfd26f68', 'doutrina', 'cp_iuris', 'Direito Empresarial — Concessão Mercantil', '## Concessão Mercantil

A concessão mercantil é um contrato atípico que obriga o concessionário a comercializar produtos fabricados por outro empresário, com ou sem exclusividade e cláusula de territorialidade.

### Conceitos
- **Concessão Mercantil**: Contrato atípico que obriga o concessionário a comercializar produtos fabricados por outro empresário
- **Cláusula de Territorialidade**: Proibição de o concedente comercializar direta ou indiretamente, os seus produtos na área de atuação reservada a um concessionário
- **Subordinação Empresarial**: Grau maior de subordinação exercido pelo concedente sobre a organização da atividade prestada pelo concessionário

### Referências legais
- Art. 5º, II e §§ 1º e 3º do Código Civil
- Lei n.º 6.729/1979
- Súmula 476 STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Concessão Mercantil

### Dicas de prova
- Entenda a noção de concessão mercantil e suas características
- Identifique a cláusula de territorialidade e sua importância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.267 (2)", "page_number": 267, "discipline": "Direito Empresarial", "legal_refs": ["Art. 5º, II e §§ 1º e 3º do Código Civil", "Lei n.º 6.729/1979", "Súmula 476 STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Concessão Mercantil"], "confidence": 0.8, "extracted_at": "2026-05-27T06:23:04.871842+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=267", "doc_key": "11d1dbe8c5a0bc8f596f2f1bcfd26f68"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '6a8d0f37d1df94336c7f5ce5a8d578b65c734afbf3c5d11eed475ac71d542dd9'),
  ('cpiuris2025::740faf15acb6b6966b588ec94061de51', 'doutrina', 'cp_iuris', 'Direito Empresarial — Franquias e Concessões Empresariais', '## Franquias e Concessões Empresariais

A franquia é um contrato que permite ao concessionário usar a marca ou patente do franqueador e comercializar seus produtos ou serviços. O franqueador autoriza o uso de marcas, direito de produção ou distribuição exclusiva ou não exclusiva, além de métodos e sistemas de implantação e administração de negócio.

### Conceitos
- **Franquia**: Contrato que permite ao concessionário usar a marca ou patente do franqueador e comercializar seus produtos ou serviços.
- **Concessão Empresarial**: Acordo pelo qual uma empresa concede direitos de uso e exploração de sua marca, patente ou outros objetos de propriedade intelectual.
- **Franqueador**: Empresa que autoriza o uso de sua marca ou patente e permite a comercialização de seus produtos ou serviços.
- **Concessionário**: Empresa que recebe os direitos de uso e exploração da marca, patente ou outros objetos de propriedade intelectual do franqueador.
- **Licença**: Permissão para usar uma marca, patente ou outro objeto de propriedade intelectual.

### Referências legais
- Art. 1º da Lei n.º 13.966/2019

### Dicas de prova
- Entenda a diferença entre franquia e concessão empresarial.
- Conheça os tipos de contratos que podem ser decorrentes de uma franquia (engineering, management, marketing).
- Avalie as implicações legais e fiscais da franquia.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.268 (1)", "page_number": 268, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1º da Lei n.º 13.966/2019"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T06:23:44.088084+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=268", "doc_key": "740faf15acb6b6966b588ec94061de51"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'f7d010113be90e5c7f1127fff46f158ae73ca7a7e0e0d2d55b8d4ec3f7676fe4'),
  ('cpiuris2025::2366e0a025b1986fbc39ce5abc298484', 'doutrina', 'cp_iuris', 'Direito Empresarial — Franquia como contrato empresarial', '## Franquia como contrato empresarial

A franquia é um contrato empresarial que não está sujeita às regras protetivas do CDC, pois não há relação de consumo entre o franqueador e o franqueado, mas sim de fomento econômico.

### Conceitos
- **Franquia**: Contrato empresarial
- **Franqueador**: Pessoa que concede a franquia
- **Franqueado**: Pessoa que recebe a franquia
- **Cadeia de consumo**: Relação entre vários atores na cadeia de fornecimento e distribuição de produtos ou serviços
- **Responsabilidade solidária**: Responsabilidade conjunta de duas ou mais pessoas por uma obrigação

### Referências legais
- Art. 1º da Lei n.º 13.966/2019
- Súmula 245 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Franquia e responsabilidade solidária

### Dicas de prova
- Entenda a diferença entre franqueador e franqueado
- Conheça o conceito de cadeia de consumo e sua importância
- Aprenda a aplicar a responsabilidade solidária em casos de fraude', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.268 (2)", "page_number": 268, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1º da Lei n.º 13.966/2019", "Súmula 245 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Franquia e responsabilidade solidária"], "confidence": 0.8, "extracted_at": "2026-05-27T06:24:12.051228+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=268", "doc_key": "2366e0a025b1986fbc39ce5abc298484"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '083423caa53ad9be87c048cb2dc6770ae5eb084e980463ad8fc3e867cb590100'),
  ('cpiuris2025::23644c6952f658c2b1d92a73ca938798', 'doutrina', 'cp_iuris', 'Direito Empresarial — Cláusulas limitativas de responsabilidade nos contratos de franquia', '## Cláusulas limitativas de responsabilidade nos contratos de franquia

A cláusula limitativa da responsabilidade é válida apenas entre as partes do contrato, não se aplicando à responsabilidade regressiva. O contrato de franquia é considerado um contrato de adesão, caracterizado pela desigualdade entre as partes.

### Conceitos
- **Cláusula limitativa de responsabilidade**: Válida apenas entre as partes do contrato
- **Contrato de adesão**: Caracterizado pela desigualdade entre as partes contratantes
- **Franqueador**: Pessoa ou empresa que concede a franquia
- **Franqueado**: Pessoa ou empresa que adquire a franquia

### Referências legais
- Art. 2º, § 1º da Lei n.º 13.966/2019

### Jurisprudência
- RE 123456
- Tema repetitivo: contrato de adesão

### Dicas de prova
- Entenda a noção de cláusula limitativa de responsabilidade e como ela se aplica aos contratos de franquia
- Conheça as características do contrato de adesão e sua aplicação às relações entre o franqueador e o franqueado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.269 (1)", "page_number": 269, "discipline": "Direito Empresarial", "legal_refs": ["Art. 2º, § 1º da Lei n.º 13.966/2019"], "jurisprudence": ["RE 123456", "Tema repetitivo: contrato de adesão"], "confidence": 0.8, "extracted_at": "2026-05-27T06:24:56.156153+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=269", "doc_key": "23644c6952f658c2b1d92a73ca938798"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '683062e2a89dded4cf90e760730c108cc2dff341167420b8209150f8d28b5b95'),
  ('cpiuris2025::7d540f584af5a13c7ee5fefaffb66018', 'doutrina', 'cp_iuris', 'Direito Empresarial — Requisitos e Informações para Franquia', '## Requisitos e Informações para Franquia

Descreve os requisitos e informações necessárias para uma franquia, incluindo detalhes sobre o investimento inicial, taxas periódicas e remuneração pelo uso de sistemas e marcas.

### Conceitos
- **Franquia**: Acordo entre as partes que estabelece os termos da relação comercial
- **Investimento inicial**: Valor estimado necessário à aquisição, implantação e entrada em operação da franquia
- **Taxa de franquia**: Valor pago pela parte que adquire o direito de usar um sistema ou marca
- **Remuneração periódica**: Pagamento feito pelo franqueado ao franqueador por uso do sistema, marca ou outros objetos de propriedade intelectual

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a importância das informações claras sobre taxas periódicas e remuneração pelo uso de sistemas e marcas
- Reconheça os requisitos específicos para cada tipo de pagamento (aluguel de equipamentos, seguro mínimo, etc.)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.269 (2)", "page_number": 269, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T06:25:23.729420+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=269", "doc_key": "7d540f584af5a13c7ee5fefaffb66018"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '020b150f8a5e7d988789fe472d9d9587b541bb912eb055d7e70b72f0aad82ae6'),
  ('cpiuris2025::6eaeb40e84a705c77d8226613e4a642d', 'doutrina', 'cp_iuris', 'Direito Empresarial — Contratos Empresariais', '## Contratos Empresariais

Regras para a relação entre o franqueador e o franqueado, incluindo informações sobre política de atuação territorial, obrigação de adquirir bens e serviços, suporte e treinamento.

### Conceitos
- **Franqueador**: Pessoa física ou jurídica que concede a franquia.
- **Franqueado**: Pessoa física ou jurídica que recebe a franquia.
- **Política de atuação territorial**: Regra que determina o território onde a franquia pode ser exercida.
- **Obrigação de adquirir bens e serviços**: Regra que exige ao franqueado adquirir bens e serviços apenas de fornecedores indicados e aprovados pelo franqueador.

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a relação entre o franqueador e o franqueado, especialmente sobre a política de atuação territorial.
- Leia a obrigação de adquirir bens e serviços com atenção, pois é um aspecto importante da franquia.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.270 (1)", "page_number": 270, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T06:25:55.562196+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=270", "doc_key": "6eaeb40e84a705c77d8226613e4a642d"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '8f48da8cbeb6a2b06b74dda50bb13624f3a0d686efbecabc506d7b397c6935db'),
  ('cpiuris2025::09e990f79d794296924217ead41a3c9b', 'doutrina', 'cp_iuris', 'Direito Empresarial — Requisitos e Informações para Contratos de Franquia', '## Requisitos e Informações para Contratos de Franquia

O contrato de franquia deve conter informações específicas sobre o modelo do contrato-padrão, regras de transferência ou sucessão, penalidades, cotas mínimas de compra, conselho ou associação de franqueados, limitação à concorrência e condições de renovação.

### Conceitos
- **Contrato de Franquia**: Acordo entre o franqueador e o franqueado que estabelece as regras e condições para a operação da franquia.
- **Regras de Transferência ou Sucessão**: Regulamentações que determinam como a franquia pode ser transferida ou sucedida.
- **Penalidades, Multas ou Indenizações**: Sanções aplicadas ao franqueado caso não cumpra com as condições estabelecidas no contrato de franquia.
- **Cotas Mínimas de Compra**: Quantidade mínima de produtos ou serviços que o franqueado deve comprar junto ao franqueador ou a terceiros designados.
- **Conselho ou Associação de Franqueados**: Entidade que representa os interesses dos franqueados perante o franqueador.
- **Limitação à Concorrência**: Regulamentações que limitam a concorrência entre o franqueador e os franqueados durante a vigência do contrato de franquia.

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Perguntas sobre as regras de transferência ou sucessão e penalidades podem ser mais fáceis se você entender o conceito de limitação à concorrência.
- Ainda assim, é importante ler atentamente a Circular de Oferta de Franquia para entender as condições específicas do contrato.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.270 (2)", "page_number": 270, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T06:26:49.125450+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=270", "doc_key": "09e990f79d794296924217ead41a3c9b"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '2f8738a6167cd20c57297cf706428b632b7df535ed158f79b204ecaae07b8f17'),
  ('cpiuris2025::fe4f9ad7965223cc670456e1986094de', 'doutrina', 'cp_iuris', 'Direito Empresarial — Contratos de Franquia', '## Contratos de Franquia

O contrato de franquia é uma espécie de contrato de adesão e pode prevê-lo cláusula compromissória. A notificação via e-mail é válida para o exercício do direito de preferência, desde que haja ciência inequívoca do franqueador.

### Conceitos
- **Franquia**: Condição em que uma pessoa adquire direitos exclusivos sobre a operação de outra empresa.
- **Contrato de Adesão**: Acordo entre as partes onde um dos contrapartes não tem liberdade para negar sua assinatura.
- **Cláusula Compromissória**: Disposição no contrato que estabelece a arbitragem como meio de resolução de controvérsias.

### Referências legais
- Art. 7º, § 1º da Lei de Franquias

### Jurisprudência
- RE 123456
- Súmula 123 do STJ

### Dicas de prova
- Distinção entre notificação via e-mail e cláusula compromissória
- Requisitos para a validade de uma cláusula compromissória em contrato de franquia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.271 (1)", "page_number": 271, "discipline": "Direito Empresarial", "legal_refs": ["Art. 7º, § 1º da Lei de Franquias"], "jurisprudence": ["RE 123456", "Súmula 123 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T06:27:21.380556+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=271", "doc_key": "fe4f9ad7965223cc670456e1986094de"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'd0785c8eb9a703e2dff1d2fb58659d7002d18a65202e3aea1ae62f9fc0564411'),
  ('cpiuris2025::003169ae705b38abab2e9c5dc2a33e1b', 'doutrina', 'cp_iuris', 'Direito Empresarial — Registro de contratos de franquia e validade do contrato', '## Registro de contratos de franquia e validade do contrato

A Lei n.º 13.966/2019 estabelece que os contratos de franquia devem ser registrados perante o INPI para produzirem efeitos em relação a terceiros, mas a ausência de registro não invalida o contrato.

### Conceitos
- **Franquia**: Condição que permite ao franqueado utilizar um ponto comercial instalado por outro
- **Registro no INPI**: Obrigação de registrar contratos de franquia perante o Instituto Nacional da Propriedade Industrial para produzirem efeitos em relação a terceiros
- **Validade do contrato**: Período durante o qual o contrato tem eficácia
- **Eficácia desse contrato perante terceiros**: Capacidade do contrato de produzir efeitos em relação a pessoas fora das partes contratantes

### Referências legais
- Art. 211 da LPI

### Jurisprudência
- REsp n.º 1.602.076 (STJ)

### Dicas de prova
- Entenda a diferença entre validade do contrato e eficácia desse contrato perante terceiros
- Conheça o requisito de registro no INPI para contratos de franquia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.271 (2)", "page_number": 271, "discipline": "Direito Empresarial", "legal_refs": ["Art. 211 da LPI"], "jurisprudence": ["REsp n.º 1.602.076 (STJ)"], "confidence": 0.8, "extracted_at": "2026-05-27T06:27:52.090994+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=271", "doc_key": "003169ae705b38abab2e9c5dc2a33e1b"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '790cbd867c5265d45e31b508a5d9572aeca10ff0e379a8229a1ed93748dc4e1b'),
  ('cpiuris2025::4f8325b6d21d6c5daf4bdf29da6e0519', 'doutrina', 'cp_iuris', 'Direito Empresarial — Renovação de Contrato de Locação e Sublocação', '## Renovação de Contrato de Locação e Sublocação

A renovação do contrato de locação do imóvel não permite a exclusão de cláusulas, salvo em casos de inadimplência. A sublocação também está sujeita à mesma regra.

### Conceitos
- **Renovação de Contrato**: A ação de renovar um contrato
- **Sublocação**: O ato de locar um imóvel a outra pessoa, que é responsável por pagar o aluguel ao proprietário original
- **Franquia**: Um contrato em que uma pessoa paga um valor para ter permissão para realizar atividades comerciais no imóvel
- **Inadimplência**: O não pagamento de um débito

### Referências legais
- Art. 473 do CC/2002
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre renovação e sublocação de contratos de locação.
- Conheça as regras sobre franquia e inadimplência.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.272 (1)", "page_number": 272, "discipline": "Direito Empresarial", "legal_refs": ["Art. 473 do CC/2002", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T06:28:33.744605+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=272", "doc_key": "4f8325b6d21d6c5daf4bdf29da6e0519"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '504d18a0ffe392ea685887175ad9872ee49f874d39058c735ae02356bf2464c9'),
  ('cpiuris2025::f332398d8e034a3e7602e5ba17bbc6c9', 'doutrina', 'cp_iuris', 'Direito Empresarial — Contratos de Distribuição por Aproximação', '## Contratos de Distribuição por Aproximação

Contratos celebrados entre fornecedor original e cliente, com cláusulas implícitas de exclusividade da distribuição e zona, remuneração por comissões e possibilidade de duração determinada ou indeterminada.

### Conceitos
- **Distribuição por Aproximação**: Contrato celebrado entre fornecedor original e cliente
- **Exclusividade da Distribuição**: O distribuidor/agente não pode trabalhar para outro proponente na zona de atuação
- **Exclusividade de Zona**: O proponente deverá se abster de realizar negócios naquela zona, a não ser que eles se deem por aproximação do distribuidor
- **Remuneração**: Paga por percentual dos negócios realizados, por meio de comissões

### Referências legais
- Art. 485 do Código Civil

### Dicas de prova
- Entenda a diferença entre distribuição e agência
- Identifique as cláusulas implícitas do contrato de distribuição-aproximação
- Conheça a importância da exclusividade na distribuição por aproximação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.272 (2)", "page_number": 272, "discipline": "Direito Empresarial", "legal_refs": ["Art. 485 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T06:29:03.999738+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=272", "doc_key": "f332398d8e034a3e7602e5ba17bbc6c9"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '049c2e2a847c53a6e67d6450072152743b3f0c208d4f8ed52e2ac7543f18f7be'),
  ('cpiuris2025::e5a727431fd8574921661b2c3204dcd2', 'doutrina', 'cp_iuris', 'Direito Empresarial — Contratos Empresariais', '## Contratos Empresariais

O vínculo contratual indeterminado tem um prazo de 90 dias após a notificação para cessar o contrato.

### Conceitos
- **Vínculo contratual**: Relação jurídica entre as partes que celebram um contrato
- **Cessação contratual**: Fim do contrato por meio de notificação das partes
- **Investimento**: Despesa realizada para obter lucro ou vantagem
- **Indenização**: Pagamento feito em razão de uma obrigação contratuais não cumprida

### Referências legais
- Art. 720, parágrafo único, do Código Civil

### Dicas de prova
- Entenda a diferença entre contrato de colaboração por intermediação e distribuição por intermediação
- Conheça as obrigações do distribuidor em um contrato atípico', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.273", "page_number": 273, "discipline": "Direito Empresarial", "legal_refs": ["Art. 720, parágrafo único, do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T06:29:28.966395+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=273", "doc_key": "e5a727431fd8574921661b2c3204dcd2"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'a0cce417ec9cbe462995423d817ae716f439f93c1098d660d58a277edc14fb83'),
  ('cpiuris2025::53d3009df3672b9232f8971d0cc4640e', 'doutrina', 'cp_iuris', 'Direito Empresarial — Contratos Bancários', '## Contratos Bancários

Para haver contrato bancário, é necessário um banco e atividade de coleta, intermediação e aplicação de recursos financeiros.

### Conceitos
- **Atividade Bancária**: coleta, intermediação e aplicação de recursos financeiros
- **Contrato Bancário**: acordo entre um banco e outra parte sobre atividade bancária
- **Requisitos do Contrato Bancário**: uma das partes deve ser um banco e referir-se à atividade bancária
- **Atividades Bancárias Típicas**: relacionadas ao crédito, como operações passivas e ativas
- **Atividades Bancárias Atípicas**: serviços acessórios ao cliente, como custódia de valores e locação de cofres

### Referências legais
- Art. 17 da Lei n.º 4.595/64

### Jurisprudência
- Súmula n.º 297 do STJ
- Súmula n.º 381 do STJ

### Dicas de prova
- Entenda a definição de atividade bancária e seus requisitos para formar um contrato bancário
- Conheça as diferenças entre atividades bancárias típicas e atípicas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.274", "page_number": 274, "discipline": "Direito Empresarial", "legal_refs": ["Art. 17 da Lei n.º 4.595/64"], "jurisprudence": ["Súmula n.º 297 do STJ", "Súmula n.º 381 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T06:30:13.992457+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=274", "doc_key": "53d3009df3672b9232f8971d0cc4640e"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '92f9203d15cade92ae8824ef8f3adc77085bf6e469b6ae8eaeff4e97df2a7600'),
  ('cpiuris2025::1460f965cb2022210ee80bca695e7726', 'doutrina', 'cp_iuris', 'Direito Empresarial — Contratos Bancários', '## Contratos Bancários

Descreve os contratos bancários, incluindo spread bancário e operações passivas, bem como os contratos de depósito bancário.

### Conceitos
- **Spread bancário**: Diferença entre o que os bancos pagam na captação de recursos e o que eles cobram ao conceder um empréstimo.
- **Operações passivas**: O banco é o devedor, com a função de captação de recursos no mercado.
- **Contrato de depósito bancário**: Contrato real que se aperfeiçoa com a entrega do dinheiro à instituição financeira depositária.

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a diferença entre spread bancário e operações passivas.
- Conheça as características do contrato de depósito bancário.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.275", "page_number": 275, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T06:30:42.423284+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=275", "doc_key": "1460f965cb2022210ee80bca695e7726"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '1e58bffab4f9762b15247ff62a9cb4e0681ae3f5f15bbcb740ddb905dcc8f661'),
  ('cpiuris2025::29d4e93d797d5da8f807a51bc5d8f40b', 'doutrina', 'cp_iuris', 'Direito Empresarial — Contratos Bancários', '## Contratos Bancários

Descreve os contratos bancários, incluindo conta corrente e aplicação financeira, destacando suas características e regras.

### Conceitos
- **Contrato de Conta Corrente**: Condição em que o banco recebe valor do correntista ou terceiro em seu favor e procede a pagamentos
- **Taxas**: Incidência de taxas na administração da conta corrente
- **Contrato de Aplicação Financeira**: Condição em que o depositante autoriza o banco a empregar valor em investimento
- **Operações Ativas**: Contratos em que o banco assume posição de credor, como mutuo bancário e desconto bancário

### Referências legais
- Lei n.º 370/37
- Súmula n.º 541 do STJ

### Jurisprudência
- Súmula n.º 382 do STJ
- Súmula n.º 530 do STJ

### Dicas de prova
- Entenda a diferença entre conta corrente e aplicação financeira
- Conheça as regras de taxa de juros nos contratos bancários', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.276 (1)", "page_number": 276, "discipline": "Direito Empresarial", "legal_refs": ["Lei n.º 370/37", "Súmula n.º 541 do STJ"], "jurisprudence": ["Súmula n.º 382 do STJ", "Súmula n.º 530 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T06:31:15.398640+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=276", "doc_key": "29d4e93d797d5da8f807a51bc5d8f40b"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'fadab6a4af5e43d129cd20220114e6b2e68f1188208c0263291cf50ae038e044'),
  ('cpiuris2025::c6433ddb9acb11e17f30c08c972dca8d', 'doutrina', 'cp_iuris', 'Direito Empresarial — Taxa de Juros em Contratos Bancários', '## Taxa de Juros em Contratos Bancários

Aplica-se a taxa média de mercado em contratos bancários sem comprovação da taxa efetivamente contratada. A partir da Lei nº 14.905/24, o índice oficial de atualização monetária é o IPCA.

### Conceitos
- **Taxa Média de Mercado**: taxa aplicada em contratos bancários sem comprovação da taxa efetivamente contratada
- **Bacen**: Banco Central do Brasil
- **SELIC**: Sistema Especial de Liquidação e Custodia
- **Índice de Atualização Monetária**: índice utilizado para atualizar o valor dos juros

### Referências legais
- Art. 14.905/24
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre taxa média de mercado e taxa efetivamente contratada
- Conhecer a Lei nº 14.905/24 e sua aplicação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.276 (2)", "page_number": 276, "discipline": "Direito Empresarial", "legal_refs": ["Art. 14.905/24", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T06:31:50.734636+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=276", "doc_key": "c6433ddb9acb11e17f30c08c972dca8d"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '0c473be31505fcdc6b78f9525764e8f78269e3f3e8f4195d9f7fdab58ea90fe6'),
  ('cpiuris2025::a68214be0b2ba1f192b77f9a25f7bb57', 'doutrina', 'cp_iuris', 'Direito Empresarial — Contratos Bancários', '## Contratos Bancários

O art. 3º da Lei nº 14.905/24 estabelece exceções à ''Lei de Usura'', incluindo contratos entre pessoas jurídicas, representados por títulos de crédito ou valores mobiliários, e contraídos perante instituições financeiras e demais instituições autorizadas a funcionar pelo BACEN.

### Conceitos
- **Lei de Usura**: Lei que proíbe práticas abusivas de crédito
- **Contrato Bancário**: Contrato entre banco e cliente
- **Mútuo Bancário**: Empréstimo feito pelo banco ao cliente

### Referências legais
- Art. 3º da Lei nº 14.905/24

### Jurisprudência
- Súmula n.º 381
- Súmula n.º 380
- Súmula n.º 379

### Dicas de prova
- Entenda a noção de ''Lei de Usura'' e suas exceções
- Conheça as características do contrato bancário, incluindo o mútuo bancário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.277 (1)", "page_number": 277, "discipline": "Direito Empresarial", "legal_refs": ["Art. 3º da Lei nº 14.905/24"], "jurisprudence": ["Súmula n.º 381", "Súmula n.º 380", "Súmula n.º 379"], "confidence": 0.8, "extracted_at": "2026-05-27T06:32:20.859691+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=277", "doc_key": "a68214be0b2ba1f192b77f9a25f7bb57"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '3bd618690913ba4d102450372a8f706bdc779201ef0358993acc395b09dc6df5'),
  ('cpiuris2025::1d3c7aa5747274782a3e5ebcdf76f415', 'doutrina', 'cp_iuris', 'Direito Empresarial — Devolução antecipada de empréstimo', '## Devolução antecipada de empréstimo

A devolução antecipada de empréstimo é possível apenas com a concordância do mutuante, considerando-se o Direito Comercial. No entanto, se a relação for regida pelo CDC, o consumidor terá direito à redução proporcional dos juros e demais encargos.

### Conceitos
- **Devolução antecipada**: A devolução do valor emprestado antes do prazo fixado
- **Mútuo bancário**: Financiamento é uma espécie de mútuo bancário, onde o banco empresta ao mutuário valor para que o empregue com finalidade específica determinada

### Referências legais
- Art. 52, § 2º, do CDC

### Dicas de prova
- Pegar a distinção entre empréstimo e financiamento
- Entender que a devolução antecipada depende da concordância do mutuante', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.277 (2)", "page_number": 277, "discipline": "Direito Empresarial", "legal_refs": ["Art. 52, § 2º, do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T06:32:46.126337+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=277", "doc_key": "1d3c7aa5747274782a3e5ebcdf76f415"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'f97c4e6772c190634c35c98e31f2231259ed8e14ee69db3062c653938c0b7c2d'),
  ('cpiuris2025::ab9a31d23a77165f2b1bc5e88701be76', 'doutrina', 'cp_iuris', 'Direito Empresarial — Contratos Bancários', '## Contratos Bancários

Resumo sobre os contratos bancários, incluindo financiamento, tarifa de emissão de carnê e desconto bancário.

### Conceitos
- **Financiamento**: Condição em que o banco antecipa um crédito ao cliente
- **Tarifa de emissão de carnê**: Cobrança feita pelo banco aos seus clientes após 30/4/2008
- **Desconto bancário**: Contrato em que o banco antecipa um crédito ao cliente com deságio

### Referências legais
- Art. X da Lei Y
- Súmula n.º 565 do STJ
- Súmula n.º 30 do STJ
- Resolução-CMN n.º 3.518/2007

### Jurisprudência
- RE 123456
- Súmula n.º 566 do STJ

### Dicas de prova
- Entenda a diferença entre financiamento e desconto bancário
- Conheça as súmulas do STJ relacionadas a tarifa de emissão de carnê
- Aprenda sobre a Resolução-CMN n.º 3.518/2007', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.278 (1)", "page_number": 278, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y", "Súmula n.º 565 do STJ", "Súmula n.º 30 do STJ", "Resolução-CMN n.º 3.518/2007"], "jurisprudence": ["RE 123456", "Súmula n.º 566 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T06:33:30.890282+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=278", "doc_key": "ab9a31d23a77165f2b1bc5e88701be76"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '1aab218b17357c4d344670a7796e0f3c8ad7827054dd4a9492a2c95facbef353'),
  ('cpiuris2025::bd73c46fe5b620dc541905eb76388483', 'doutrina', 'cp_iuris', 'Direito Empresarial — Redesconto e Contrato de Abertura de Crédito', '## Redesconto e Contrato de Abertura de Crédito

O redesconto é um acordo entre bancos, onde o banco central paga ao banco que descontou o crédito. O contrato de abertura de crédito ocorre quando o banco coloca valor à disposição do cliente, mas só há pagamento de juros se o cliente utilizá-lo.

### Conceitos
- **Redesconto**: Acordo entre bancos para pagamento do crédito descontado
- **Contrato de Abertura de Crédito**: Acordo pelo qual o banco coloca valor à disposição do cliente
- **Juros**: Pagamento por uso do dinheiro
- **Demais Encargos**: Outros pagamentos obrigatórios

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a diferença entre redesconto e contrato de abertura de crédito
- Conheça as condições para pagamento de juros', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.278 (2)", "page_number": 278, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T06:33:56.049586+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=278", "doc_key": "bd73c46fe5b620dc541905eb76388483"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'a848895c2e368079094346eefd2b3b80284b081f0179fc0f32c87a41fa18a54e'),
  ('cpiuris2025::2635a1f10c5d86ca06373aaf8724d604', 'doutrina', 'cp_iuris', 'Direito Empresarial — Contratos Bancários', '## Contratos Bancários

Resumo do texto sobre contratos bancários, incluindo características e exemplos de contratos bancários impróprios.

### Conceitos
- **Contrato Bilateral**: Contrato entre duas partes
- **Contrato Consensual**: Acordo de vontades entre as partes
- **Título Executivo**: Documento que pode ser executado em juízo
- **Ação Monitória**: Ação para cobrar um débito
- **Crédito Documentário**: Crédito baseado em documentos
- **Alienação Fiduciária em Garantia**: Alienação de um bem com fé depositada
- **Faturização (Factoring)**: Contrato que permite a venda de créditos
- **Arrendamento Mercantil (Leasing)**: Contrato que permite o uso de um bem por um período determinado

### Referências legais
- Art. 333 do Código Civil
- Súmula n.º 233 do STJ
- Súmula n.º 247 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo da Súmula n.º 247 do STJ

### Dicas de prova
- Memorizar a Súmula n.º 233 e 247 do STJ
- Entender a diferença entre contrato bilateral e consensual
- Conhecer os exemplos de contratos bancários impróprios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.279", "page_number": 279, "discipline": "Direito Empresarial", "legal_refs": ["Art. 333 do Código Civil", "Súmula n.º 233 do STJ", "Súmula n.º 247 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo da Súmula n.º 247 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T06:34:42.137451+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=279", "doc_key": "2635a1f10c5d86ca06373aaf8724d604"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '956e965e42e7fddcc5288e587a274d569984157830679362d5af578d8e4f7c51'),
  ('cpiuris2025::b57b7243581ccbe56b445fba5d909c59', 'doutrina', 'cp_iuris', 'Direito Empresarial — Alienação Fiduciária em Garantia', '## Alienação Fiduciária em Garantia

A alienação fiduciária é um contrato que instrumentaliza um contrato principal, geralmente um mútuo, servindo-lhe de garantia. O contrato pode ter por objeto bem móvel ou imóvel e não requer registro em cartório para sua validade.

### Conceitos
- **Alienação Fiduciária**: Contrato que instrumentaliza um contrato principal, geralmente um mútuo
- **Garantia**: Serviço de garantia oferecido pelo credor ao devedor
- **Mútuo**: Contrato em que uma pessoa presta dinheiro a outra em troca de uma promessa de devolver o valor
- **Registro em Cartório**: Obrigação legal de registrar um contrato em cartório para sua validade
- **Teoria do Adimplemento Substancial**: Teoria que afirma que o credor não pode extinguir o contrato estabelecido entre o devedor e terceiro, mesmo se o devedor já adimpliu significativa parte da dívida
- **Busca e Apreensão**: Ação do credor para recuperar um bem que foi alienado em garantia
- **Integração Patrimonial**: Obrigação do devedor de integrar o patrimônio do credor com a propriedade do bem

### Referências legais
- Art. 1.234, Código Civil
- Súmula n.º 28, STJ

### Jurisprudência
- RE 123456
- Informativo n.º 599, STJ

### Dicas de prova
- Entenda a diferença entre alienação fiduciária e garantia
- Conheça as hipóteses em que o contrato de alienação fiduciária é devolvido ao fiduciante', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.280 (1)", "page_number": 280, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1.234, Código Civil", "Súmula n.º 28, STJ"], "jurisprudence": ["RE 123456", "Informativo n.º 599, STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T06:35:37.151566+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=280", "doc_key": "b57b7243581ccbe56b445fba5d909c59"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '40fe8070efb36e8d94e63084bd92b348be4f698af6c778f51bdacea97f1f7a07'),
  ('cpiuris2025::eee64f46b92bf2762fe06f72eca99543', 'doutrina', 'cp_iuris', 'Direito Empresarial — Alienação Fiduciária', '## Alienação Fiduciária

O Código Civil se limitou a tratar da propriedade fiduciária de bens móveis infungíveis, não aplicando-se às demais espécies de propriedade fiduciária ou de titularidade fiduciária disciplinadas em lei especial.

### Conceitos
- **Alienação Fiduciária**: Transferência de direitos de propriedade de um devedor para um credor, sem transferência de posse do bem
- **Propriedade Fiduciária**: Direito de propriedade que é subordinado a condições e limitações estabelecidas por uma lei ou contrato
- **Bens Móveis Infungíveis**: Bens móveis que não podem ser alienados ou transferidos, como imóveis ou bens de uso exclusivo

### Referências legais
- Art. 1.361 a 1.368-A do Código Civil
- Decreto-Lei 911/1969
- Lei n. 10.931/2004, art. 3º, § 2º

### Jurisprudência
- REsp n. 1.418.593-MS
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre alienação fiduciária e propriedade fiduciária
- Conheça as limitações do Código Civil em relação à alienação fiduciária
- Aprenda a aplicar a Lei n. 10.931/2004 no contexto da alienação fiduciária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.280 (2)", "page_number": 280, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1.361 a 1.368-A do Código Civil", "Decreto-Lei 911/1969", "Lei n. 10.931/2004, art. 3º, § 2º"], "jurisprudence": ["REsp n. 1.418.593-MS", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T06:36:16.404913+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=280", "doc_key": "eee64f46b92bf2762fe06f72eca99543"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'fc412188959150cbd51e06c0aa206e4f671e4b6784e7e3c78913e766183fc457'),
  ('cpiuris2025::d4dc89e1cb11874f37889c0f40eb4f56', 'doutrina', 'cp_iuris', 'Direito Empresarial — Alienação Fiduciária de Bens Imóveis e Contratos de Factoring', '## Alienação Fiduciária de Bens Imóveis e Contratos de Factoring

O contrato de factoring envolve a cobrança de dívidas por uma sociedade, enquanto a alienação fiduciária de bens imóveis pode ser utilizada para garantia de operações de crédito não vinculadas ao SFI.

### Conceitos
- **Alienação Fiduciária**: Constituição de garantia de bem imóvel para operações de crédito
- **Contrato de Factoring**: Acordo que envolve a cobrança de dívidas por uma sociedade
- **Faturização**: Modalidade de factoring que envolve a gestão dos créditos do faturizado
- **Maturity Factoring**: Modalidade de factoring que envolve a antecipação do valor do crédito ao faturizado
- **Conventional Factoring**: Modalidade de factoring que não envolve a antecipação do valor do crédito

### Referências legais
- Art. 22, § 1º, da Lei n.º 9.514/1997
- Art. 51 da Lei n.º 10.931/2004

### Jurisprudência
- Súmula n.º 245 do STJ

### Dicas de prova
- Entenda a diferença entre alienação fiduciária e contrato de factoring
- Conheça as modalidades de faturização (maturity e conventional factoring)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.281 (1)", "page_number": 281, "discipline": "Direito Empresarial", "legal_refs": ["Art. 22, § 1º, da Lei n.º 9.514/1997", "Art. 51 da Lei n.º 10.931/2004"], "jurisprudence": ["Súmula n.º 245 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T06:36:55.016989+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=281", "doc_key": "d4dc89e1cb11874f37889c0f40eb4f56"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '7e7cecec29e1caa7fe2107f073859d0f3b6ffd672389949f010f500f89c87850'),
  ('cpiuris2025::9f01b31729c84099217dd01a1db575e7', 'doutrina', 'cp_iuris', 'Direito Empresarial — Conventional Factoring', '## Conventional Factoring

O conventional factoring envolve a antecipação dos valores de créditos do faturizado, mas não ocorre no maturity factoring, que apenas oferece administração de crédito.

### Conceitos
- **Faturização**: Prática de antecipar os valores de créditos a um cliente
- **Administração do Crédito**: Serviço de gestão e cobrança de dívidas
- **Financiamento**: Procedimento pelo qual uma instituição financeira fornece capital a um cliente

### Referências legais
- Art. X da Lei Y
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre conventional factoring e maturity factoring
- Conheça os elementos típicos do conventional factoring', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.281 (2)", "page_number": 281, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T06:37:28.013649+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=281", "doc_key": "9f01b31729c84099217dd01a1db575e7"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '227bd1b5f9933ab1e035b912424e573b1922935140b8a94a751011083b9edf96'),
  ('cpiuris2025::dabe7494399f1bf94c4a928d937c837f', 'doutrina', 'cp_iuris', 'Direito Empresarial — Contratos Bancários e Factoring', '## Contratos Bancários e Factoring

O STJ decidiu que o sacado pode opor à faturizadora exceções pessoais em operações de factoring, mas após julgamento de embargos, mudou a interpretação para considerar o endosso como efetivo endosso cambial. Além disso, empresas em recuperação judicial podem celebrar contratos de factoring sem autorização judicial.

### Conceitos
- **Cessão civil de crédito**: negociação de um crédito cuja origem é objeto de análise pela faturizadora
- **Endosso cambial**: negociação de um crédito cuja origem é objeto de análise pela faturizadora, considerado efetivo endosso cambial
- **Arrendamento mercantil**: locação especial marcada pela opção dada ao locatário de, ao término da locação, decidir pela compra ou não do bem locado

### Referências legais
- Art. 294 do CC
- Informativo 640 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo sobre contratos bancários e factoring no STJ

### Dicas de prova
- Entenda a diferença entre cessão civil de crédito e endosso cambial
- Conheça as regras do arrendamento mercantil e suas implicações tributárias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.282 (1)", "page_number": 282, "discipline": "Direito Empresarial", "legal_refs": ["Art. 294 do CC", "Informativo 640 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre contratos bancários e factoring no STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T06:38:04.800445+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=282", "doc_key": "dabe7494399f1bf94c4a928d937c837f"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '74af27df19e0f15d866284065fefef7d992407bac066298a002d32ac881c68d3'),
  ('cpiuris2025::e24c08c35b76f88c17b507aa11656252', 'doutrina', 'cp_iuris', 'Direito Empresarial — Arrendamento Mercantil', '## Arrendamento Mercantil

O arrendamento mercantil é considerado apenas se atender ao conceito legal estabelecido no parágrafo único do art. 1º da Lei, que especifica o objeto e o uso do bem. Caso contrário, não há arrendamento mercantil para fins tributários.

### Conceitos
- **Arrendamento Mercantil**: Negócio jurídico entre pessoa jurídica (arrendadora) e pessoa física ou jurídica (arrendatária)
- **Conceito Legal**: Objeto e uso do bem especificados pela arrendatária
- **Art. 1º da Lei**: Regula o tratamento tributário das operações de arrendamento mercantil

### Referências legais
- Art. 1º da Lei n.º 6.099/1974

### Jurisprudência
- REsp 1.783.068-SP
- 22/02/2019

### Dicas de prova
- Entenda o conceito de arrendamento mercantil e sua especificação
- Diferencie entre contrato de arrendamento mercantil e operação de compra e venda a prestação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.282 (2)", "page_number": 282, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1º da Lei n.º 6.099/1974"], "jurisprudence": ["REsp 1.783.068-SP", "22/02/2019"], "confidence": 0.8, "extracted_at": "2026-05-27T06:38:32.173505+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=282", "doc_key": "e24c08c35b76f88c17b507aa11656252"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '435b53933cf68b812ef9aaf8becbcf44efacd2e1ffcdd08fef4cafa1224ddcdc'),
  ('cpiuris2025::f9a207f6618f46ad84190ddf769d12ff', 'doutrina', 'cp_iuris', 'Direito Empresarial — Arrendamento Mercantil e Leasing', '## Arrendamento Mercantil e Leasing

O arrendamento mercantil inclui leasing financeiro e operacional. O leasing financeiro é a modalidade típica, onde o bem não pertence à arrendadora, mas sim ao arrendatário. Já o leasing operacional é caracterizado pela arrendadora alugando o bem sem custo inicial de aquisição.

### Conceitos
- **Arrendamento Mercantil**: Modalidade de contratos que envolve a alocação de bens para uso por tempo determinado
- **Leasing Financeiro**: Modalidade típica de arrendamento mercantil, onde o bem não pertence à arrendadora
- **Leasing Operacional**: Modalidade caracterizada pela arrendadora alugando o bem sem custo inicial de aquisição
- **Valor Residual**: Montante que deve ser pago ao proprietário do bem no final do contrato

### Referências legais
- Art. 2º da Lei n.º 6.099/74
- Art. 401, I, do CC
- Lei n.º 13.043/2014
- Decreto-Lei n.º 911/1969

### Jurisprudência
- RE 123456
- Tema repetitivo ...
- CRUZ, 2016

### Dicas de prova
- Entenda a diferença entre leasing financeiro e operacional
- Conheça o conceito de valor residual
- Aprenda com as regras do arrendamento mercantil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.283 (1)", "page_number": 283, "discipline": "Direito Empresarial", "legal_refs": ["Art. 2º da Lei n.º 6.099/74", "Art. 401, I, do CC", "Lei n.º 13.043/2014", "Decreto-Lei n.º 911/1969"], "jurisprudence": ["RE 123456", "Tema repetitivo ...", "CRUZ, 2016"], "confidence": 0.8, "extracted_at": "2026-05-27T06:39:22.132341+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=283", "doc_key": "f9a207f6618f46ad84190ddf769d12ff"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '754ea14c2b78f4f4b743780a29b857a42a12506071ebe3ae6bf66b4e679dc243'),
  ('cpiuris2025::98a531919b184e9395bc8646c8e31875', 'doutrina', 'cp_iuris', 'Direito Empresarial — Residual Garantido no Arrendamento Mercantil', '## Residual Garantido no Arrendamento Mercantil

O pagamento do valor residual antecipado pode transformar o leasing em compra e venda a preços, mas não é sempre assim. O STJ decidiu que o arrendatário tem direito à diferença se o valor antecipado ultrapassa o valor residual previsto contratualmente.

### Conceitos
- **Arrendamento Mercantil**: Contrato pelo qual uma empresa concede uso de um bem a outra em troca de uma prestação mensal
- **Valor Residual Garantido (VRG)**: Valor pago ao final do contrato, que pode ser antecipado para transformar o leasing em compra e venda a preços
- **Leasing**: Contrato pelo qual uma empresa concede uso de um bem a outra em troca de uma prestação mensal, sem a aquisição do bem

### Referências legais
- Art. 1.234 da Lei X
- Súmula n.º 263/STJ
- Súmula n.º 293/STJ

### Jurisprudência
- RE 123456/STJ
- Tema repetitivo: Arrendamento Mercantil e Valor Residual Garantido

### Dicas de prova
- Entenda a diferença entre leasing e compra e venda a preços
- Conheça as regras do valor residual garantido e como ele pode ser antecipado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.283 (2)", "page_number": 283, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1.234 da Lei X", "Súmula n.º 263/STJ", "Súmula n.º 293/STJ"], "jurisprudence": ["RE 123456/STJ", "Tema repetitivo: Arrendamento Mercantil e Valor Residual Garantido"], "confidence": 0.8, "extracted_at": "2026-05-27T06:39:54.189012+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=283", "doc_key": "98a531919b184e9395bc8646c8e31875"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '57944441def8f8fc92c625bd33cd5a42c3b5995366bfcc3869fc6e722b223611'),
  ('cpiuris2025::9ff405137a63e7cf83c17bc2c06d2b32', 'doutrina', 'cp_iuris', 'Direito Empresarial — Contratos Intelectuais', '## Contratos Intelectuais

Contratos que dizem respeito a direitos autorais ou propriedade industrial, como licença de uso de marca ou patente.

### Conceitos
- **Cessão de Patente**: Transferência dos direitos de uma patente para outro
- **Cessão de Registro Industrial**: Transferência dos direitos de exploração de um desenho industrial ou marca
- **Limitação Material**: Acessão a apenas alguns dos direitos industriais abrangidos pela cessão
- **Limitação Territorial**: Acessão a utilizar a patente em determinado local, mas não em outro
- **Condomínio sobre Patente**: Instituição de condomínio sobre a patente, permitindo que os condôminos explorem a patente isoladamente

### Referências legais
- Art. 135 da LPI

### Dicas de prova
- Entenda a distinção entre cessão de patente e registro industrial
- Conheça as limitações materiais e territoriais na cessão de direitos industriais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.285", "page_number": 285, "discipline": "Direito Empresarial", "legal_refs": ["Art. 135 da LPI"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T06:40:25.414085+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=285", "doc_key": "9ff405137a63e7cf83c17bc2c06d2b32"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '63972115eb7cf76cbb219557347bc8c085e2558ea778abdf4b7307ebb3dc6a88'),
  ('cpiuris2025::b9af4d42f49a38bbb5ae68b95fcd702a', 'doutrina', 'cp_iuris', 'Direito Empresarial — Licença de Uso de Patente ou Registro', '## Licença de Uso de Patente ou Registro

A licença de uso de patente ou registro é um contrato pelo qual o proprietário de direito industrial lícencia o uso da patente ou do registro a terceiros, sem transferência da titularidade do direito industrial.

### Conceitos
- **licença de uso**: contrato pelo qual o proprietário de direito industrial lícencia o uso de sua patente ou registro a terceiros
- **cessão**: transferência da titularidade do direito industrial
- **intuito personae**: contrato feito com intenção específica de atender a uma necessidade particular
- **exclusividade**: direito exclusivo sobre o uso da patente ou registro
- **prazo de proteção**: período durante o qual o direito industrial está protegido

### Referências legais
- Art. 61 a 63 da LPI
- Art. 68 a 74 da LPI

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar licença de uso de cessão
- Entender o conceito de intuito personae
- Conhecer as cláusulas que podem ser incluídas em um contrato de licença de uso', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.286 (1)", "page_number": 286, "discipline": "Direito Empresarial", "legal_refs": ["Art. 61 a 63 da LPI", "Art. 68 a 74 da LPI"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T06:41:10.985438+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=286", "doc_key": "b9af4d42f49a38bbb5ae68b95fcd702a"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '8dea31c6c6b1719c850f33bd5a91d50fda67de35960885ec1a130f5f37615057'),
  ('cpiuris2025::8abccd6e51a667615ae3befab64c6c4b', 'doutrina', 'cp_iuris', 'Direito Empresarial — Transferência de Tecnologia', '## Transferência de Tecnologia

A transferência de tecnologia envolve a prestação de serviços técnicos e científicos, além da licença de uso de marca ou patente, que pode implicar a transferência de tecnologia. O contrato de transferência de tecnologia visa capacitar o cessionário para o emprego da tecnologia.

### Conceitos
- **Transferência de Tecnologia**: Prestação de serviços técnicos e científicos, além da licença de uso de marca ou patente
- **Licença de Uso**: Permissão para o uso de uma marca ou patente
- **Patente**: Direito exclusivo concedido pelo Estado sobre um invenção
- **Cessão**: Transferência de direitos ou bens de uma pessoa para outra

### Referências legais
- Art. 1º da Lei n.º 9.609/1998

### Dicas de prova
- Entenda a diferença entre licença de uso e transferência de tecnologia
- Conheça o conceito de patente e sua importância na transferência de tecnologia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.286 (2)", "page_number": 286, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1º da Lei n.º 9.609/1998"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T06:41:36.713964+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=286", "doc_key": "8abccd6e51a667615ae3befab64c6c4b"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'a69201122018024d3023a98ebc1c88c767b92f89bdad96b4d079e2a8ee5ee349'),
  ('cpiuris2025::0b1614844412395d32f7bec091da9fb2', 'doutrina', 'cp_iuris', 'Direito Empresarial — Contratos Intelectuais', '## Contratos Intelectuais

O direito autoral protege os direitos dos criadores de obras, limitando a forma de tutela e proibindo o plágio. A titularidade decorre da apresentação da obra ao público, sem necessidade de registro.

### Conceitos
- **Direito Autoral**: Protege os direitos dos criadores de obras
- **Propriedade Industrial**: Não é o mesmo que direito autoral
- **Tutela**: Limita a forma de proteção da obra
- **Plágio**: Proibido pelo direito autoral
- **Titularidade**: Decorre da apresentação da obra ao público
- **Registro**: Não é necessário para proteção do direito autoral, mas sim para marca e invenções
- **Pirataria**: Veda a utilização não comercial de um programa idêntico criado por terceiro
- **Prazo de Proteção**: 50 anos a contar do dia 1º de janeiro seguinte à publicação ou criação do produto

### Referências legais
- Art. 8º, I, da Lei de Direitos Autorais

### Dicas de prova
- Diferenciar direito autoral e propriedade industrial
- Entender a titularidade do direito autoral
- Conhecer o prazo de proteção do direito autoral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.287", "page_number": 287, "discipline": "Direito Empresarial", "legal_refs": ["Art. 8º, I, da Lei de Direitos Autorais"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T06:42:10.440142+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=287", "doc_key": "0b1614844412395d32f7bec091da9fb2"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '7414d8bc17834243375e935300e541929816bd071da82ed94605104781a4d839'),
  ('cpiuris2025::40fd649e4b2e84756877f8941c1330e1', 'doutrina', 'cp_iuris', 'Direito Empresarial — Contratos de Seguro', '## Contratos de Seguro

O contrato de seguro é um acordo entre a seguradora e o contratante, com o objetivo de garantir o interesse legítimo do contratante ou de terceiro contra riscos predeterminados. É regido pelos arts. 757 a 802 do CC/2002.

### Conceitos
- **Contrato de Adesão**: O contrato de seguro observa preceitos normativos legais, regulamentares ou exarados por órgãos do Sistema Nacional de Seguros Privados.
- **Seguradora**: É uma empresa autorizada pelo governo federal que oferece seguros.
- **Corretor**: Pode ser pessoa jurídica ou física, e é fiscalizado pela SUSEP.
- **Resseguro**: É a ''operação de transferência de riscos de uma cedente para um ressegurado''.
- **Retrocessão**: É a ''operação de transferência de riscos de resseguradores para resseguradores, ou de resseguradores para sociedades seguradoras locais''.
- **Sistema Nacional de Seguros Privados**: Integra as seguradoras e é regulamentado pelo CNSP e SUSEP.
- **CNSP**: É um órgão da administração direta federal que normatiza as operações securitárias.

### Referências legais
- Art. 757 a 802 do CC/2002
- Art. 32 da Lei dos Seguros

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a natureza do contrato de seguro e suas características.
- Conheça as diferentes modalidades de seguros (seguro de dano, seguro de pessoas, etc.).
- Aprenda sobre o Sistema Nacional de Seguros Privados e seus órgãos reguladores.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.288", "page_number": 288, "discipline": "Direito Empresarial", "legal_refs": ["Art. 757 a 802 do CC/2002", "Art. 32 da Lei dos Seguros"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T06:43:06.514881+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=288", "doc_key": "40fd649e4b2e84756877f8941c1330e1"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'fd5dd91ffa6c36080363508fa8b065b100a04256de9fba99828d5e693ed8984f'),
  ('cpiuris2025::82170392debf377c8cf36a1e8a9ee101', 'doutrina', 'cp_iuris', 'Direito Empresarial — Contratos de Seguro', '## Contratos de Seguro

Resumo do texto sobre contratos de seguro, incluindo tipos e obrigações dos contratantes.

### Conceitos
- **contrato comutativo**: Obrigação do segurado é pagar o prêmio
- **seguro de dano**: Seguro patrimonial, cunho indenizatório
- **contrato consensual**: Apólice ou bilhete de seguro é prova do contrato
- **obrigação recíproca**: Dever de boa-fé e veracidade entre as partes
- **declarações exatas**: Obrigação do segurado de prestar declarações precisas

### Referências legais
- Art. 757 do Código Civil
- Art. 765, 766, 768 e 769 do Código Civil

### Dicas de prova
- Distinção entre contrato comutativo e seguro de dano
- Importância das declarações exatas do segurado
- Obrigação recíproca entre as partes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.289 (1)", "page_number": 289, "discipline": "Direito Empresarial", "legal_refs": ["Art. 757 do Código Civil", "Art. 765, 766, 768 e 769 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T06:43:38.203820+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=289", "doc_key": "82170392debf377c8cf36a1e8a9ee101"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '31f67f603e0b90455029b500373ebf718c0d8fef8fedcfd7b1d81aac4727a3ad'),
  ('cpiuris2025::fe3c1939ff8b9d97807fe3f34bf91743', 'doutrina', 'cp_iuris', 'Direito Empresarial — Reembolso e Limitação da Indenização em Seguros', '## Reembolso e Limitação da Indenização em Seguros

O segurado tem direito a um reembolso proporcional ao valor do interesse segurado, sem ultrapassar o limite máximo da garantia. A indenização não pode exceder o valor do interesse segurado no momento do sinistro.

### Conceitos
- **Indenizatório**: Relacionado à compensação de perdas e danos
- **Enriquecimento**: O aumento patrimonial resultante de uma obrigação contratual
- **Garantia**: Promessa feita pelo segurador para pagar uma determinada quantia em caso de sinistro

### Referências legais
- Art. 778 do CC
- Art. 766 do CC
- Art. 781 do CC
- Art. 782 do CC

### Dicas de prova
- Diferenciar entre reembolso e indenização
- Entender a noção de garantia em seguros
- Conhecer o artigo 778 do CC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.289 (2)", "page_number": 289, "discipline": "Direito Empresarial", "legal_refs": ["Art. 778 do CC", "Art. 766 do CC", "Art. 781 do CC", "Art. 782 do CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T06:44:04.851616+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=289", "doc_key": "fe3c1939ff8b9d97807fe3f34bf91743"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '0d3008ce8b152f6752125e24b40e49d1399d7cb0b8fd2c3d62dd2189f598bf53'),
  ('cpiuris2025::c1e3c6980eec4fcec8ea786d5be1211d', 'doutrina', 'cp_iuris', 'Direito Empresarial — Seguro de Pessoas', '## Seguro de Pessoas

O seguro de pessoas não tem natureza indenizatória e o valor a ser pago é considerado como ''capital''. O Código Civil estabelece regras específicas para o pagamento do capital em caso de morte do segurado.

### Conceitos
- **Capital**: Valor a ser pago pela seguradora em caso de ocorrência do evento segurado
- **Indenização**: Pagamento feito por uma pessoa para compensar um dano ou perda sofrida
- **Omissão do beneficiário**: Situação em que o seguro de vida é contratado sem a presença do beneficiário
- **Sucessão**: Transmissão de bens ou direitos de uma pessoa para outra
- **Imposto de Transmissão Causa Mortis e Doação (ITCMD)**: Imposto pago sobre a transmissão de bens ou direitos de uma pessoa falecida

### Referências legais
- Art. 789 do CC/2002
- Art. 792 do CC/2002
- Art. 794 do CC/2002
- Súmula n.º 61 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo sobre seguro de pessoas

### Dicas de prova
- Diferenciar entre capital e indenização
- Entender a regra de omissão do beneficiário
