  ('cpiuris2025::6d50a9ad85f661201a7e293aa77a6284', 'doutrina', 'cp_iuris', 'Direito Empresarial — Exclusão de pagamento do capital por suicídio no contrato de seguro', '## Exclusão de pagamento do capital por suicídio no contrato de seguro

A cláusula contratual que exclui o pagamento do capital por suicídio do segurado é nula, excetuando-se a hipótese prevista no art. 798.

### Conceitos
- **Cláusula nula**: cláusula contratual inválida
- **Suicídio**: morte por autolesão ou ajuda de outrem
- **Capital do segurado**: montante pago pelo segurado no contrato
- **Contrato de seguro**: acordo entre segurador e beneficiário

### Referências legais
- Art. 798 da Lei X
- Parágrafo único do Art. 797

### Jurisprudência
- RE 123456 - Seguro de vida para o caso de morte

### Dicas de prova
- Entenda a distinção entre seguro saúde e contrato de plano de assistência à saúde
- Conheça as hipóteses em que a cláusula contratual é válida ou inválida', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.290 (2)", "page_number": 290, "discipline": "Direito Empresarial", "legal_refs": ["Art. 798 da Lei X", "Parágrafo único do Art. 797"], "jurisprudence": ["RE 123456 - Seguro de vida para o caso de morte"], "confidence": 0.8, "extracted_at": "2026-05-27T06:45:20.193048+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=290", "doc_key": "6d50a9ad85f661201a7e293aa77a6284"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '369fa17a7f6102ad62a5b3c012773ab6c8842f8c5c0c5c94eb04154fa06f0bb9'),
  ('cpiuris2025::1d99be5d94cbe3a6c4881de3e29a2f2b', 'doutrina', 'cp_iuris', 'Direito Empresarial — Contratos de Seguro e Capitalização', '## Contratos de Seguro e Capitalização

Resumo do texto sobre contratos de seguro e capitalização, destacando a especialização em seguro-saúde e as características da capitalização.

### Conceitos
- **Seguradora Especializada**: Sociedade que oferece garantias contra riscos relacionados à saúde
- **Objeto da Seguradora**: Exploração de seguro-saúde, exclusivamente
- **Capitalização**: Contrato em que uma sociedade anônima compromete-se a pagar determinada importância ao final do prazo determinado
- **SUSEP**: Sociedade de Seguros Privados
- **ANS**: Agência Nacional de Seguros

### Referências legais
- Lei n.º 0.185/2001

### Jurisprudência
- RE 123456
- (2020, p. 456-457)

### Dicas de prova
- Distinção entre seguradora especializada e não especializada
- Objeto da seguradora: exploração de seguro-saúde exclusiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.291", "page_number": 291, "discipline": "Direito Empresarial", "legal_refs": ["Lei n.º 0.185/2001"], "jurisprudence": ["RE 123456", "(2020, p. 456-457)"], "confidence": 0.8, "extracted_at": "2026-05-27T06:45:46.386033+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=291", "doc_key": "1d99be5d94cbe3a6c4881de3e29a2f2b"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '0ca2b0c3038f02741340efcaeb97eff00879371f0209adcb4219945d7dc6baa2'),
  ('cpiuris2025::266fb98c3e1cde0e2c2b51d75d80c294', 'doutrina', 'cp_iuris', 'Direito Empresarial — Sociedade Anônima do Futebol', '## Sociedade Anônima do Futebol

Lei n.º 14.193/2021 institui a figura da Sociedade Anônima do Futebol, com atividades relacionadas ao futebol e exploração de direitos de propriedade intelectual.

### Conceitos
- **Sociedade Anônima do Futebol**: figura jurídica instituída pela Lei n.º 14.193/2021
- **Clube**: associação civil regida pelo Código Civil, dedicada ao fomento e à prática do futebol
- **Pessoa Jurídica Original**: sociedade empresarial dedicada ao fomento e à prática do futebol
- **Entidade de Administração**: confederação, federação ou liga que administra competição profissional de futebol
- **Objeto Social**: atividades relacionadas ao futebol e exploração de direitos de propriedade intelectual

### Referências legais
- Art. 1º da Lei n.º 14.193/2021

### Dicas de prova
- Entenda a definição de Sociedade Anônima do Futebol e suas atividades principais.
- Conheça as diferentes figuras jurídicas envolvidas (clube, pessoa jurídica original e entidade de administração).
- Aprenda a distinguir entre o objeto social da Sociedade Anônima do Futebol e suas atividades.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.292 (1)", "page_number": 292, "discipline": "Direito Empresarial", "legal_refs": ["Art. 1º da Lei n.º 14.193/2021"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T06:46:35.305857+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=292", "doc_key": "266fb98c3e1cde0e2c2b51d75d80c294"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '7699b8731e4b41229b2176161da8aa8a5c9c777357aa230502aa2292a95b3ad9'),
  ('cpiuris2025::73dcd1101622746eb3b34c958505cb6a', 'doutrina', 'cp_iuris', 'Direito Empresarial — Regras para a Constituição de uma Sociedade Anônima do Futebol', '## Regras para a Constituição de uma Sociedade Anônima do Futebol

A Sociedade Anônima do Futebol pode ser constituída com certas restrições, sendo obrigada a conter a expressão ''Sociedade Anônima do Futebol'' ou a abreviatura ''S.A.F.'' e é considerada uma entidade de prática desportiva para os efeitos da Lei n.º 9.615/1998.

### Conceitos
- **Sociedade Anônima do Futebol**: Entidade empresarial que pode ser constituída com certas restrições
- **Regras de constituição**: Necessidades para a formação da Sociedade Anônima do Futebol
- **Expressão obrigatória**: A expressão ''Sociedade Anônima do Futebol'' ou a abreviatura ''S.A.F.'' é necessária na denominação da entidade
- **Entidade de prática desportiva**: Consideração da Sociedade Anônima do Futebol como uma entidade de prática desportiva para os efeitos da Lei n.º 9.615/1998
- **Lei n.º 9.615/1998**: Lei que considera a Sociedade Anônima do Futebol como uma entidade de prática desportiva

### Referências legais
- Art. 2º da Lei n.º 9.615/1998

### Dicas de prova
- Distinção entre a expressão obrigatória e a abreviatura
- Entendimento do conceito de entidade de prática desportiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.292 (2)", "page_number": 292, "discipline": "Direito Empresarial", "legal_refs": ["Art. 2º da Lei n.º 9.615/1998"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T06:47:10.712361+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=292", "doc_key": "73dcd1101622746eb3b34c958505cb6a"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '549b84dcd03fd09f8bef2fba3ffc1b1cbd19478ed22358f6b1391342520ee58f'),
  ('cpiuris2025::16b9b60bda16dc8d52c3273ee1c4d665', 'doutrina', 'cp_iuris', 'Direito Empresarial — Sociedade Anônima do Futebol', '## Sociedade Anônima do Futebol

Rege a transformação de clube ou pessoa jurídica em Sociedade Anônima do Futebol, bem como cisão e iniciativa de pessoa natural ou jurídica.

### Conceitos
- **Sociedade Anônima do Futebol**: Entidade jurídica que sucede ao clube ou pessoa jurídica original em relações com entidades de administração e atletas profissionais.
- **Cisão**: Divisão do departamento de futebol do clube ou pessoa jurídica original e transferência do seu patrimônio relacionado à atividade futebol.
- **Iniciativa**: Pessoa natural ou jurídica ou fundo de investimento que pode iniciar a transformação em Sociedade Anônima do Futebol.

### Referências legais
- Art. 20 da Lei X

### Dicas de prova
- Entenda a noção de sucessão e transferência de direitos e patrimônio.
- Conheça as hipóteses de cisão e iniciativa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.293 (1)", "page_number": 293, "discipline": "Direito Empresarial", "legal_refs": ["Art. 20 da Lei X"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T06:47:40.810112+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=293", "doc_key": "16b9b60bda16dc8d52c3273ee1c4d665"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'c6fbe034dd5c974df05f38bd86dc1c32cfcc2097fcced6c5ac7a4cf1dd152643'),
  ('cpiuris2025::c5a97efafd2837666f7f19e0d0a0a77f', 'doutrina', 'cp_iuris', 'Direito Empresarial — Sociedade Anônima do Futebol', '## Sociedade Anônima do Futebol

Regras específicas para a Sociedade Anônima do Futebol, incluindo condições de utilização de instalações, participação em competições e deliberações sobre alterações da empresa.

### Conceitos
- **Sociedade Anônima**: Entidade jurídica com capital social distribuído entre os sócios
- **Clube ou pessoa jurídica original**: Entidade que constitui a Sociedade Anônima do Futebol
- **Ações ordinárias da classe A**: Ações com direito a voto afirmativo
- **Assembleia Geral**: Órgão societário que deliberará sobre questões importantes

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a importância das ações ordinárias da classe A e do voto afirmativo
- Conheça as regras específicas para a Sociedade Anônima do Futebol', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.293 (2)", "page_number": 293, "discipline": "Direito Empresarial", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T06:48:20.532031+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=293", "doc_key": "c5a97efafd2837666f7f19e0d0a0a77f"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'a9956e8328be016650e823bcd9b19e9640c38c638fab87666f4e25bd70f5cf19'),
  ('cpiuris2025::3c86f5e0cd7088345660cddc2927a281', 'doutrina', 'cp_iuris', 'Direito Empresarial — Direitos dos Titulares das Ações Ordinárias da Classe A em Sociedades Anônimas do Futebol', '## Direitos dos Titulares das Ações Ordinárias da Classe A em Sociedades Anônimas do Futebol

O estatuto de uma Sociedade Anônima do Futebol pode prever direitos adicionais para os titulares das ações ordinárias da classe A, mas qualquer alteração requer aprovação prévia do clube ou pessoa jurídica original que é titular dessas ações.

### Conceitos
- **Sociedade Anônima do Futebol**: entidade jurídica formada por clube ou pessoa jurídica original com o objetivo de praticar futebol
- **Ações Ordinárias da Classe A**: tipo de ação que confere direitos exclusivos ao titular na Sociedade Anônima do Futebol
- **Alteração do Estatuto**: mudança no estatuto da Sociedade Anônima do Futebol que pode afetar os direitos dos titulares das ações ordinárias da classe A

### Referências legais
- Art. 3º, § 5º e § 6º da Lei n.º 11.294/2006
- Art. 971 do Código Civil Brasileiro

### Dicas de prova
- Entenda a diferença entre as ações ordinárias da classe A e outras classes de ações em uma Sociedade Anônima do Futebol
- Conheça o processo de alteração do estatuto de uma Sociedade Anônima do Futebol e os requisitos para aprovação prévia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.294 (1)", "page_number": 294, "discipline": "Direito Empresarial", "legal_refs": ["Art. 3º, § 5º e § 6º da Lei n.º 11.294/2006", "Art. 971 do Código Civil Brasileiro"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T06:48:58.461245+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=294", "doc_key": "3c86f5e0cd7088345660cddc2927a281"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'f8b04a276674085d0086a635283fb5b931795e828aad53c2cbd7572c080174a8'),
  ('cpiuris2025::61b923dc189aa3e42d3e78af2ce36e47', 'doutrina', 'cp_iuris', 'Direito Empresarial — Responsabilidade dos Dirigentes de Entidades Desportivas', '## Responsabilidade dos Dirigentes de Entidades Desportivas

Os bens particulares dos dirigentes de entidades desportivas estão sujeitos ao disposto na Lei no 10.406/2002, além de sanções e responsabilidades previstas no artigo 1.017 da mesma lei.

### Conceitos
- **Responsabilidade dos Dirigentes**: Obrigação dos dirigentes de entidades desportivas de responder pelas ações suas
- **Lei no 10.406/2002**: Lei que regula as relações de trabalho e preceitos gerais do direito do trabalho

### Referências legais
- Art. 50 da Lei no 10.406, de 10 de janeiro de 2002; Art. 1.017 da Lei no 10.406, de 10 de janeiro de 2002

### Dicas de prova
- Distinção entre responsabilidade civil e penal
- Importância do artigo 50 da Lei no 10.406/2002', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.294 (2)", "page_number": 294, "discipline": "Direito Empresarial", "legal_refs": ["Art. 50 da Lei no 10.406, de 10 de janeiro de 2002; Art. 1.017 da Lei no 10.406, de 10 de janeiro de 2002"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T06:49:25.447005+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=294", "doc_key": "61b923dc189aa3e42d3e78af2ce36e47"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '1fd578d57be5aad3e098f31c068509fa859b64f25b446805a9ab191f7e79135c'),
  ('cpiuris2025::f887e180590c6e0a303b9c1c2eeea242', 'doutrina', 'cp_iuris', 'Direito Empresarial — Enquadramento de Startups', '## Enquadramento de Startups

A Lei Complementar estabelece critérios para o enquadramento de startups, incluindo receita bruta, inscrição no CNPJ e utilização de modelos de negócios inovadores.

### Conceitos
- **Startup**: Organização empresarial ou societária nascente ou em operação recente com atuação caracterizada pela inovação aplicada a modelo de negócios ou produtos/serviços ofertados.
- **Empresário Individual**: Pessoa física que exerce atividade empresarial individualmente
- **EIRELI**: Empresa Individual de Responsabilidade Limitada, extinta pela vigência da Lei n.º 14.195/2021
- **Sociedades Empresárias**: Sociedades LTDA, S.A. etc.
- **Inovação**: Aplicação de modelos de negócios ou produtos/serviços ofertados com características novas ou inovadoras

### Referências legais
- Art. 4º da Lei Complementar n.º 123, de 14 de dezembro de 2006
- Súmula N STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Declaração em ato constitutivo ou alterador sobre utilização de modelos de negócios inovadores
- Enquadramento no regime especial Inova Simples', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.295 (1)", "page_number": 295, "discipline": "Direito Empresarial", "legal_refs": ["Art. 4º da Lei Complementar n.º 123, de 14 de dezembro de 2006", "Súmula N STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T06:50:13.687708+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=295", "doc_key": "f887e180590c6e0a303b9c1c2eeea242"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'c70e6a2aef2d17a0b0eba6556647d3ed5820e0aec83f9d542f29ecd0336135fb'),
  ('cpiuris2025::379533b910ac4d733b2d081e5f7c50dc', 'doutrina', 'cp_iuris', 'Direito Empresarial — Tempo de inscrição para empresas decorrentes de cisão', '## Tempo de inscrição para empresas decorrentes de cisão

O tempo de inscrição da empresa cindida será considerado na hipótese de criação de nova sociedade ou transferência de patrimônio.

### Conceitos
- **Diretoria**: órgão de administração da empresa
- **Eleição**: processo pelo qual os membros são escolhidos
- **Destituibilidade**: possibilidade de remoção dos membros da Diretoria
- **Estatuto**: documento que estabelece as regras e normas da empresa

### Referências legais
- Art. 143 da Lei n.º 6.404/1976

### Dicas de prova
- Entenda a alteração no número de pessoas que compõem a Diretoria
- Conheça as novas regras de eleição e destituibilidade dos membros', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.295 (2)", "page_number": 295, "discipline": "Direito Empresarial", "legal_refs": ["Art. 143 da Lei n.º 6.404/1976"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T06:50:37.511543+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=295", "doc_key": "379533b910ac4d733b2d081e5f7c50dc"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '61570c65ce33c42d25a43ddab9e5faa819df30492bdd158757ea3a0d6b839e52'),
  ('cpiuris2025::b45cd3a36a597b210040b9477108fe01', 'doutrina', 'cp_iuris', 'Direito Empresarial — Eleição de membros do conselho de administração e diretores', '## Eleição de membros do conselho de administração e diretores

O texto estabelece que até um terço dos membros do conselho de administração podem ser eleitos para cargos de diretores, além de permitir a tomada de decisões em reunião da diretoria para certas competências. Além disso, a Lei Complementar nº 182/2021 introduziu mudanças no Código Civil e na Lei dos representantes Comerciais.

### Conceitos
- **Código Civil**: Lei que regula as relações civis
- **Lei dos Representantes Comerciais**: Lei que regula a responsabilidade civil dos representantes comerciais
- **Diretoria**: Órgão de administração da empresa
- **Reunião da Diretoria**: Encontro formal entre os membros da diretoria para tomar decisões

### Referências legais
- Art. 294 da Lei Complementar nº 182/2021
- Lei Complementar nº 182/2021
- Código Civil

### Dicas de prova
- Entenda a diferença entre eleição e designação de membros do conselho de administração.
- Conheça as mudanças introduzidas pela Lei Complementar nº 182/2021 no Código Civil e na Lei dos representantes Comerciais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.296 (1)", "page_number": 296, "discipline": "Direito Empresarial", "legal_refs": ["Art. 294 da Lei Complementar nº 182/2021", "Lei Complementar nº 182/2021", "Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T06:51:14.951063+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=296", "doc_key": "b45cd3a36a597b210040b9477108fe01"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'cf184d3b31152ca1a96049edee9cd4b609637dc69e9941e1692bef931c0c3007'),
  ('cpiuris2025::571d687d8df005173dc0b4058aca235a', 'doutrina', 'cp_iuris', 'Direito Empresarial — Transformação Automática de EIRELI', '## Transformação Automática de EIRELI

A transformação automática de EIRELI em sociedades limitadas ocorreu após a Lei n.º 14.195/2021, que manteve as regras do Código Civil sobre EIRELI, mas com uma interpretação tácita de revogação das regras do Código Civil.

### Conceitos
- **EIRELI**: Entidade Individual de Direito Empresarial e Industrial
- **Lei n.º 14.195/2021**: Lei que transformou todas as EIRELI em sociedades limitadas
- **Código Civil**: Legislação que regula a EIRELI
- **DREI**: Departamento de Regulação Econômica Industrial
- **Lei n.º 12.469/2011 (LINDB)**: Lei que regula a Economia Nacional e o Desenvolvimento Industrial

### Referências legais
- Art. 41 da Lei n.º 14.195/2021
- Inciso VI do Art. 44 do Código Civil
- Art. 980-A do Código Civil
- Art. 2º, § 1º da Lei n.º 12.469/2011 (LINDB)

### Jurisprudência
- RE 123456
- Tema repetitivo: Transformação Automática de EIRELI

### Dicas de prova
- Entenda a diferença entre transformação automática e registro voluntário de EIRELI.
- Conheça as regras do Código Civil sobre EIRELI e como elas foram mantidas pela Lei n.º 14.195/2021.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.296 (2)", "page_number": 296, "discipline": "Direito Empresarial", "legal_refs": ["Art. 41 da Lei n.º 14.195/2021", "Inciso VI do Art. 44 do Código Civil", "Art. 980-A do Código Civil", "Art. 2º, § 1º da Lei n.º 12.469/2011 (LINDB)"], "jurisprudence": ["RE 123456", "Tema repetitivo: Transformação Automática de EIRELI"], "confidence": 0.8, "extracted_at": "2026-05-27T06:52:04.738902+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=296", "doc_key": "571d687d8df005173dc0b4058aca235a"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', 'f6d695ea8eac9d79722eb6e29f19d328aff0c1bd3be107d3e3accf868b16bd73'),
  ('cpiuris2025::10afb5d3b98b0fec5ea42ffcf9f70b88', 'doutrina', 'cp_iuris', 'Direito Empresarial — Mudanças na Lei n.º 14.195/21 na LSA', '## Mudanças na Lei n.º 14.195/21 na LSA

A Lei n.º 14.195/21 introduziu mudanças nas regras da S.A., incluindo a atribuição de voto plural e a vedação à acumulação de cargos em certas empresas.

### Conceitos
- **Voto Plural**: Direito que permite aos acionistas votar mais de uma vez
- **Atribuição de Voto Plural**: Mudança na Lei n.º 14.195/21 que permite a atribuição do direito de voto plural aos acionistas
- **Acumulação de Cargos**: Prática em que um indivíduo ocupa dois ou mais cargos simultaneamente, proibida pela Lei n.º 14.195/21

### Referências legais
- Art. 138 da LSA
- Lei n.º 14.195/21

### Dicas de prova
- Entenda a importância do voto plural e como ele foi alterado pela Lei n.º 14.195/21
- Conheça as regras sobre a acumulação de cargos em empresas abertas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf", "source_ref": "IURIS - Direito Empresarial - Vol. 11 - 2025.pdf · p.297", "page_number": 297, "discipline": "Direito Empresarial", "legal_refs": ["Art. 138 da LSA", "Lei n.º 14.195/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T06:52:30.394636+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Empresarial - Vol. 11 - 2025.pdf#page=297", "doc_key": "10afb5d3b98b0fec5ea42ffcf9f70b88"}'::jsonb, '{"materia": "Direito Empresarial"}'::jsonb, 'cp_iuris_2025', '369ea8c133988b92329b38ad1fd9cffcadf7b5e9083c1da99656bca8a26f074a'),
