  ('cpiuris2025::6d3c6366616605073440cda9b0524465', 'doutrina', 'cp_iuris', 'Direito Empresarial — Lei nº 7.357/1985 e outras leis relevantes', '## Lei nº 7.357/1985 e outras leis relevantes

Lista de leis brasileiras relacionadas à legislação empresarial, incluindo a Lei nº 7.357/1985.

### Conceitos
- **Lei nº 7.357/1985**: Lei que regula as relações entre os sócios e o estabelecimento
- **Lei nº 8.078/1990**: Lei do Consumidor, que regula as relações entre consumidores e fornecedores
- **Lei nº 8.137/1990**: Lei de Licenças e Autorizações, que regula a concessão de licenças e autorizações para atividades econômicas
- **Lei nº 8.245/1991**: Lei de Acesso à Informação, que regula o acesso à informação pública

