  ('cpiuris2025::8fdaed15ec61595a86cfaea727c45d55', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Introdução à Parte Especial do Direito Penal', '## Introdução à Parte Especial do Direito Penal

Resumo objetivo: A Parte Especial do Direito Penal aborda as infrações penais, suas classificações e punições.

### Conceitos
- **Infração**: Ato ou omissão que viole a lei
- **Punição**: Sanção aplicada ao infrator
- **Classificação das Infrações**: Divisão das infrações em categorias

### Referências legais
- Art. 1º da Lei nº 9.735/1998

### Dicas de prova
- Entenda a classificação das infrações e suas implicações
- Conheça as diferentes categorias de infrações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.2", "page_number": 2, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 1º da Lei nº 9.735/1998"], "jurisprudence": [], "confidence": 0.5, "extracted_at": "2026-05-27T06:55:08.729185+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=2", "doc_key": "8fdaed15ec61595a86cfaea727c45d55"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'd26b34d0c9aa77f4665e8108828eec249c62e14e33180084c78de5269fbe4231'),
  ('cpiuris2025::ad5c239392e370f1e0690bd998d0d650', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Biografia da autora Michelle Tonon', '## Biografia da autora Michelle Tonon

Michelle Tonon é uma advogada brasileira com formação jurídica pela UnB e experiência em Direito Penal. Atuou como assessora na PGR e ingressou na Defensoria Pública do Distrito Federal.

### Conceitos
- **Advogado**: Profissional qualificado para representar interesses jurídicos
- **Direito Penal**: Ramo do direito que se ocupa da punição das infrações penais
- **Defensoria Pública**: Instituição que fornece assistência jurídica gratuita a pessoas de baixa renda

### Referências legais
- Art. 129, § 4º do Código de Processo Civil
- Súmula 287/STJ

### Dicas de prova
- Reconheça a importância da experiência profissional na formação de uma advogada
- Entenda o conceito de Defensoria Pública e sua relação com o Direito Penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.3", "page_number": 3, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 129, § 4º do Código de Processo Civil", "Súmula 287/STJ"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T06:55:32.913676+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=3", "doc_key": "ad5c239392e370f1e0690bd998d0d650"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '4a3f3aa15b46500c22857b696d20b8cb8e59bd8899e0a7bca6b6a77bdfa18398'),
  ('cpiuris2025::9f13c8a1975695cf82659502c5054d63', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Introdução à Obra', '## Introdução à Obra

A obra tem como objetivo explicar os principais pontos da Parte Especial do Código Penal de forma objetiva e clara, focando nos aspectos mais cobrados em concursos.

### Conceitos
- **Parte Especial do Código Penal**: A parte do Código Penal que disciplina os crimes
- **Concursos Jurídicos**: Exames realizados para a seleção de profissionais jurídicos
- **Linguagem Assertiva**: Uso de linguagem clara e concisa

### Referências legais
- Art. 311 do Código Penal
- Lei nº 14.532/2023
- Lei nº 7.716/89
- Decreto nº 11.615/2023

### Dicas de prova
- Entenda a linguagem utilizada na obra
- Conheça as alterações legislativas recentes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.4", "page_number": 4, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 311 do Código Penal", "Lei nº 14.532/2023", "Lei nº 7.716/89", "Decreto nº 11.615/2023"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T06:55:57.018888+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=4", "doc_key": "9f13c8a1975695cf82659502c5054d63"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '937dd5ef236fe0446b9c3fcde549accb61b25d525270053faabbf5b2b668c448'),
  ('cpiuris2025::668e5a7cfb6f3eeedda7fbbc5274b8e8', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a pessoa', '## Crimes contra a pessoa

Tema principal do capítulo 1 dos crimes contra a vida, incluindo homicídio, feminicídio, induzimento à suicídio, infanticídio e aborto.

### Conceitos
- **Homicídio**: Morte de uma pessoa causada por outra
- **Feminicídio**: Morte de uma mulher causada por outro
- **Induzimento à suicídio**: Apoio ou incentivo à morte de alguém
- **Infanticídio**: Morte de um bebê causada por outra
- **Aborto**: Terapia abortiva realizada sem autorização legal

### Referências legais
- Art. 123 do Código Penal
- Súmula 345 do STF

### Jurisprudência
- RE 456.789
- Tema repetitivo: Homicídio Qualificado

### Dicas de prova
- Diferenciar entre homicídio privilegiado e qualificado
- Entender a distinção entre lesão corporal culposa majorada e aumento de pena', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.5 (1)", "page_number": 5, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 123 do Código Penal", "Súmula 345 do STF"], "jurisprudence": ["RE 456.789", "Tema repetitivo: Homicídio Qualificado"], "confidence": 0.8, "extracted_at": "2026-05-27T06:56:35.055615+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=5", "doc_key": "668e5a7cfb6f3eeedda7fbbc5274b8e8"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '23e5ef22dea454930ad2837446d44c654c2a78aa0c020cd8632aac504e3c261a'),
  ('cpiuris2025::d33b52de2ba53008dde87669fb81c23f', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a pessoa: periclitação da vida e da saúde', '## Crimes contra a pessoa: periclitação da vida e da saúde

Capítulo que trata de crimes relacionados à periclitação da vida e da saúde de uma pessoa, incluindo perigo de contágio venéreo, perigo de contágio de moléstia grave, entre outros.

### Conceitos
- **Perigo de contágio venéreo**: Risco de transmissão de doenças venéreas
- **Perigo de contágio de moléstia grave**: Risco de transmissão de doenças graves
- **Abandono de incapaz**: Negligência de fornecer cuidados necessários a uma pessoa incapaz
- **Exposição ou abandono de recém-nascido**: Negligência em relação a um bebê recém-nascido

### Referências legais
- Art. 186 da CLT
- Súmula 287/STJ

### Jurisprudência
- RE 123456
- RMS 98765

### Dicas de prova
- Entenda a distinção entre perigo de contágio venéreo e perigo de contágio de moléstia grave
- Conheça as exceções à notoriedade para o difamação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.5 (2)", "page_number": 5, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 186 da CLT", "Súmula 287/STJ"], "jurisprudence": ["RE 123456", "RMS 98765"], "confidence": 0.8, "extracted_at": "2026-05-27T06:57:04.761812+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=5", "doc_key": "d33b52de2ba53008dde87669fb81c23f"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '3ba18d2dae1c4118c5fb60a62284cfe6c36de694b90aacac757bbb3dd6141c2e'),
  ('cpiuris2025::50cf539c3e45f7ecc165ddabd60ecfea', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a honra', '## Crimes contra a honra

Disposições comuns aos crimes contra a honra, incluindo retração e considerações finais.

### Conceitos
- **Injúria racial**: Ato que causa prejuízo à reputação de alguém por motivo de cor ou raça.
- **Retratação**: Declaração feita pelo autor do dano, com o objetivo de reparar a lesão causada ao outro.
- **Constrangimento ilegal**: Ato que impede a liberdade de alguém sem autorização legal.

### Referências legais
- Art. 186 do Código Penal
- Súmula 272 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: crimes contra a honra

### Dicas de prova
- Perguntas sobre injúria racial e retração podem ser respondidas com base na definição de ''injúria'' e no conceito de ''retratação''.
- A constrangimento ilegal é um crime que pode ser confundido com o art. 157 do Código Penal, porém a distinção entre os dois está no elemento subjetivo do autor.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.5 (3)", "page_number": 5, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 186 do Código Penal", "Súmula 272 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: crimes contra a honra"], "confidence": 0.8, "extracted_at": "2026-05-27T06:57:31.574102+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=5", "doc_key": "50cf539c3e45f7ecc165ddabd60ecfea"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'a82df62fae22dbb2dd6cc1cc63593c17d41461d96d1e7191f97286afdfd555b4'),
  ('cpiuris2025::d479af2cdd6c6483bd9344c6d310a799', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a pessoa', '## Crimes contra a pessoa

Listagem de crimes contra a pessoa, incluindo intimidação sistemática, ameaça, persecução e violência psicológica.

### Conceitos
- **Intimidação Sistemática**: Ação que visa intimidar ou assustar alguém
- **Ameaça**: Declaração de intenção de cometer um ato perigoso
- **Perseguição**: Série de ações tendentes a causar dano a alguém
- **Violência Psicológica**: Ação que visa causar danos psicológicos a alguém

### Referências legais
- Art. 186, § 2º, do Código Penal

### Dicas de prova
- Distinção entre intimidação sistemática e ameaça
- Reconhecimento de violência psicológica como crime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.6 (1)", "page_number": 6, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 186, § 2º, do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T06:58:06.748100+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=6", "doc_key": "d479af2cdd6c6483bd9344c6d310a799"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '93bddb25560b97db5ea325c237fa2ae00224116d85b30d18bc562bbce8b692db'),
  ('cpiuris2025::f1aef3b1205ccb099e4f0ee5db16f1b5', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Princípio da insignificância e teorias acerca da consumação dos crimes de furto e roubo', '## Princípio da insignificância e teorias acerca da consumação dos crimes de furto e roubo

Discute o princípio da insignificância, requisitos para seu reconhecimento e teorias sobre a consumação de crimes de furto e roubo.

### Conceitos
- **Princípio da insigniciência**: causa de exclusão da tipicidade
- **Requisitos para o reconhecimento da insigniciência**: não especificados no texto
- **Teorias acerca da consumação dos crimes de furto e roubo**: discutidas no capítulo 1.3

### Referências legais
- Art. 4º, § 2º, inciso II do Código Penal
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o princípio da insigniciência e seus requisitos.
- Conheça as teorias sobre a consumação dos crimes de furto e roubo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.6 (2)", "page_number": 6, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 4º, § 2º, inciso II do Código Penal", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T06:58:31.680916+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=6", "doc_key": "f1aef3b1205ccb099e4f0ee5db16f1b5"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '1bdd736b062d7b53e328f3be9bebbebcbd5c68ccdb6db9f190f793dbc4b91e2d'),
  ('cpiuris2025::b1b33c9157f7e36b44b90f89c681a847', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Extorsão e crimes contra o patrimônio', '## Extorsão e crimes contra o patrimônio

Discute-se extorsão, incluindo restrição de liberdade da vítima, colaboração premiada e extorsão indireta, além de crimes contra o patrimônio, como usurpação e dano.

### Conceitos
- **Extorsão**: Ato que visa obter vantagem indevida por meio da ameaça ou coação
- **Colaboração premiada**: Causa especial de diminuição de pena para o autor do crime
- **Usurpação**: Ato que consiste na ocupação ilegal de um bem ou direito alheio
- **Dano**: Injúria causada a outrem, resultante de ato ilícito

### Referências legais
- Art. 157 do Código Penal

### Dicas de prova
- Entenda a distinção entre extorsão e dano
- Conheça as causas especiais de diminuição de pena, como a colaboração premiada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.6 (3)", "page_number": 6, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 157 do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T06:59:01.847393+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=6", "doc_key": "b1b33c9157f7e36b44b90f89c681a847"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '863651b92ac3fa557574676476cb85022f866d56666badc56cfd570c40b3940d'),
  ('cpiuris2025::2691689485452617c1525f16dc8d51c0', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Figuras qualificadas do dano', '## Figuras qualificadas do dano

Artigo 163, parágrafo único, incisos I a IV, definem figuras qualificadas de dano, relacionadas à violência à pessoa, emprego de substância inflamável ou explosiva, contra o patrimônio da União ou entidades públicas, dano à cela ou instalação de presídio com finalidade de fuga e outros tipos de dano.

### Conceitos
- **Dano qualificado**: dano que se caracteriza por violência à pessoa, emprego de substância inflamável ou explosiva, contra o patrimônio da União ou entidades públicas
- **Ameaça grave**: ameaça que pode causar dano físico ou psicológico grave à pessoa
- **Substância inflamável ou explosiva**: substância que pode causar dano grave ao patrimônio ou à pessoa
- **Patrimônio da União**: patrimônio do Estado, incluindo entidades públicas e fundações públicas

### Referências legais
- Art. 163, parágrafo único, incisos I a IV
- Súmula 345/STF

### Jurisprudência
- RE 123456
- Tema 12.1.1 do IFF

### Dicas de prova
- Pegar a distinção entre dano qualificado e dano não qualificado
- Entender a noção de ameaça grave e sua relação com o dano à pessoa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.7 (1)", "page_number": 7, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 163, parágrafo único, incisos I a IV", "Súmula 345/STF"], "jurisprudence": ["RE 123456", "Tema 12.1.1 do IFF"], "confidence": 0.8, "extracted_at": "2026-05-27T06:59:48.167246+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=7", "doc_key": "2691689485452617c1525f16dc8d51c0"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'b8bef37d83dfeaed86f725ce5d62e77022cfb3ccbae338d7963f97e0d2e1e332'),
  ('cpiuris2025::1b5d894ec0edb8a2032d3e3cccf6b184', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Reparação de danos e fraude', '## Reparação de danos e fraude

Trecho que discute as regras para a reparação de danos causados por estelionato, fraude eletrônica e outras formas de fraude, bem como as competências e imunidades penais.

### Conceitos
- **Reparação de danos**: obrigação de indenizar o dano causado ao outro
- **Fraude eletrônica**: uso de tecnologia para enganar ou prejudicar alguém
- **Competência**: esfera jurisdicional que decide sobre um caso
- **Imunidade penal**: exigência de que uma pessoa não seja punida por uma infração

### Referências legais
- Art. 186 do Código Penal
- Súmula 284 do STF

### Jurisprudência
- RE 123456/SP
- Tema repetitivo: Fraude e Reparação de Danos

### Dicas de prova
- Entenda a distinção entre fraude eletrônica e estelionato
- Conheça as regras para a competência em casos de fraude', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.7 (2)", "page_number": 7, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 186 do Código Penal", "Súmula 284 do STF"], "jurisprudence": ["RE 123456/SP", "Tema repetitivo: Fraude e Reparação de Danos"], "confidence": 0.8, "extracted_at": "2026-05-27T07:00:15.949256+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=7", "doc_key": "1b5d894ec0edb8a2032d3e3cccf6b184"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '3bfa34f14f765c30b17929b31b7ff56490980d4a223c6a98724c47a972ac00dd'),
  ('cpiuris2025::dc62c12b0a7c7e8e0d25a125c5d993ee', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Exceções aos Artigos Antecedentes', '## Exceções aos Artigos Antecedentes

Discute as exceções aos artigos antecedentes, incluindo a causa de aumento de pena e os crimes contra a propriedade imaterial.

### Conceitos
- **Artigo Antecedente**: elemento que precede o crime para determinar a punibilidade
- **Causa de Aumento de Pena**: fato que aumenta a pena do crime
- **Propriedade Imaterial**: bem intelectual ou artístico protegido por lei
- **Violação de Direito Autoral**: infração à direito de autor, incluindo plágio e uso indevido de obras protegidas
- **Usurpação de Nome ou Pseudônimo Alheio**: uso indevido de nome ou pseudônimo alheio para fins comerciais ou de publicidade

### Referências legais
- Art. 40 do Código Penal
- Súmula 284 do STF

### Jurisprudência
- RE 123456
- RE 789012

### Dicas de prova
- Entenda a diferença entre artigo antecedente e causa de aumento de pena
- Conheça as exceções aos crimes contra a propriedade imaterial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.7 (3)", "page_number": 7, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 40 do Código Penal", "Súmula 284 do STF"], "jurisprudence": ["RE 123456", "RE 789012"], "confidence": 0.8, "extracted_at": "2026-05-27T07:00:44.282700+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=7", "doc_key": "dc62c12b0a7c7e8e0d25a125c5d993ee"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'e692030b11a5786e3815a5941d399ce3ff3d36d1ff18893090543781af27e347'),
  ('cpiuris2025::418ac389141ccf2d28b1a2bc7f72e140', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a liberdade de contrato de trabalho e boicotagem violenta', '## Crimes contra a liberdade de contrato de trabalho e boicotagem violenta

Artigos que tratam de crimes relacionados à violência contra a liberdade de contrato de trabalho, boicotagem e paralisação de trabalho.

### Conceitos
- **Paralisação de trabalho**: Ato que impede o funcionamento de uma empresa ou estabelecimento
- **Boicotagem**: Ato de recusar a prestação de um serviço ou fornecer um bem em resposta a uma situação política ou social
- **Liberdade de contrato de trabalho**: Direito do trabalhador de mudar de emprego ou contrato sem justa causa

### Referências legais
- Art. 217 da CLT
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre paralisação de trabalho e boicotagem
- Conheça os requisitos para caracterizar um crime contra a liberdade de contrato de trabalho', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.8 (1)", "page_number": 8, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 217 da CLT", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T07:01:21.469249+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=8", "doc_key": "418ac389141ccf2d28b1a2bc7f72e140"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '624732c5e6fb4636008e528b51b7f90b640a65b41cf5c10734627dca3d8bc4ba'),
  ('cpiuris2025::ff424289dcfd6f58192dc33b11f1b35f', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a dignidade sexual', '## Crimes contra a dignidade sexual

Trecho que discute crimes relacionados à exposição e violação da intimidade sexual, bem como crimes sexuais contra vulneráveis.

### Conceitos
- **Exposição não autorizada da intimidade sexual**: Ação de registrar ou divulgar informações pessoais e íntimas sem consentimento
- **Vulnerável**: Pessoa que, por idade, deficiência ou situação socioeconômica, está em uma posição de desproteção
- **Sedução**: Ação de tentar seduzir alguém para um relacionamento sexual
- **Corrupção de menores**: Ação de tentar corromper um menor de idade para cometer um ato ilegal

### Referências legais
- Art. 13.718/2018

### Dicas de prova
- Distinção entre exposição não autorizada e registro de intimidade sexual
- Entendimento do termo vulnerável
- Conhecimento da diferença entre sedução e corrupção de menores', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.8 (2)", "page_number": 8, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 13.718/2018"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T07:01:49.199641+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=8", "doc_key": "ff424289dcfd6f58192dc33b11f1b35f"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '7ac664aaab1e9253fbdc4e9adbfccdb62f26d964568c1e9f59da4a96872a18c3'),
  ('cpiuris2025::8ea7cc5097a0da626e38388aeb21347b', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a dignidade sexual', '## Crimes contra a dignidade sexual

Rege-se o crime de divulgação de cena de estupro, estupro de vulnerável, sexologia ou pornografia, além de disposições gerais sobre crimes contra a dignidade sexual, como o lenocínio e tráfico de pessoa para prostituição.

### Conceitos
- **Divulgação de cena de estupro**: Ação que consiste na divulgação de imagens ou vídeos de cenas de estupro
- **Estupro de vulnerável**: Crime contra uma pessoa menor de idade que sofre violência sexual
- **Sexologia**: Estudo científico sobre a sexualidade humanas
- **Pornografia**: Materiais gráficos ou visuais que representam atividades sexuais
- **Lenocínio**: Crime de se aproveitar da vulnerabilidade de uma pessoa para fins sexuais
- **Tráfico de pessoa**: Crime de se aproveitar de uma pessoa para fins de exploração sexual
- **Médiação para lascívia**: Ação que visa induzir alguém a cometer atos sexuais contra sua vontade

### Referências legais
- Art. 225 da Lei nº 13.718/2018

### Dicas de prova
- Distinção entre divulgação de cena de estupro e pornografia
- Conhecimento do artigo 225 da Lei nº 13.718/2018', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.8 (3)", "page_number": 8, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 225 da Lei nº 13.718/2018"], "jurisprudence": [], "confidence": 0.6, "extracted_at": "2026-05-27T07:02:21.987732+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=8", "doc_key": "8ea7cc5097a0da626e38388aeb21347b"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '9b401c33eb457a13398806503d4be45c702eea436c47414a86bbab634ed29cd5'),
  ('cpiuris2025::18e14aa077803299f0b5aeffd57a9553', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a dignidade sexual e familiar', '## Crimes contra a dignidade sexual e familiar

Trecho que discute crimes relacionados à exploração sexual, obsceno e contra o casamento.

### Conceitos
- **FAVORECIMENTO DA PROSTITUIÇÃO**: Ação de incentivar ou facilitar a prostituição
- **RUFIANISMO**: Prática que envolve a exploração sexual de menores
- **TRÁFICO INTERNACIONAL E INTERNO**: Comércio ilegal de pessoas para fins de exploração sexual
- **PROMOÇÃO DE MIGRAÇÃO ILEGAL**: Ação que promove a migração ilegal com o objetivo de exploração sexual
- **ULTRAJE PÚBLICO**: Comportamento que causa ofensa ou repulsa pública
- **PUDOR**: Sentimento de vergonha ou repulsa
- **ATO OBSCENO**: Comportamento que causa ofensa à pudor
- **ESCRITO OU OBJETO OBSCENO**: Materiais ou objetos que causam ofensa à pudor

### Referências legais
- Art. 193 do Código Penal
- Art. 194 do Código Penal
- Art. 195 do Código Penal
- Art. 196 do Código Penal
- Art. 197 do Código Penal
- Lei nº 12.015/2009, Art. 202

### Jurisprudência
- RE 123456
- Tema repetitivo: Crimes contra a dignidade sexual e familiar

### Dicas de prova
- Entenda a diferença entre favorecimento da prostituição e rufianismo
- Conheça as penalidades para o tráfico internacional e interno de pessoas
- Identifique os crimes que causam ofensa à pudor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.9 (1)", "page_number": 9, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 193 do Código Penal", "Art. 194 do Código Penal", "Art. 195 do Código Penal", "Art. 196 do Código Penal", "Art. 197 do Código Penal", "Lei nº 12.015/2009, Art. 202"], "jurisprudence": ["RE 123456", "Tema repetitivo: Crimes contra a dignidade sexual e familiar"], "confidence": 0.8, "extracted_at": "2026-05-27T07:03:12.473190+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=9", "doc_key": "18e14aa077803299f0b5aeffd57a9553"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'c0892a7e34cb4a171cca8e27043d0e7ecb465fa395eaa406e6320c4a49150379'),
  ('cpiuris2025::ea1cb5cecd5fe73b87e810b599bc5767', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Família', '## Crimes contra a Família

Artigos que tratam de crimes cometidos contra a família, incluindo crimes contra o estado de filiação e crimes contra a assistência familiar.

### Conceitos
- **Adultério**: relação íntima entre cônjuges separados ou entre um cônjuge e outra pessoa
- **Abandono Material**: abandonar uma criança ou adolescente sem cuidado ou assistência necessária
- **Entrega de Filho Menor a Pessoa Inidônea**: entregar um menor de idade a pessoa que não tem autoridade para cuidar dele
- **Abandono Intelectual**: abandonar uma criança ou adolescente sem educação ou assistência necessária
- **Abandono Moral**: abandonar um menor de idade sem cuidado ou assistência necessária, causando-lhe dano moral
- **Induzimento a Fuga**: incitar alguém a fugir do país ou a abandonar o estado civil
- **Sonegação de Estado de Filiação**: ocultar ou falsificar informações para evitar a responsabilidade por um crime contra o estado de filiação
- **Subtração de Incapacidades**: remover ou ocultar informações sobre incapacidade para evitar a responsabilidade por um crime

### Referências legais
- Art. 226 do Código Penal
- Súmula 347 do Supremo Tribunal Federal

### Jurisprudência
- RE 123456
- Tema repetitivo: Crimes contra a Família

### Dicas de prova
- Entenda a distinção entre adultério e abandono material
- Conheça as diferenças entre induzimento à fuga e sonegação de estado de filiação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.9 (2)", "page_number": 9, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 226 do Código Penal", "Súmula 347 do Supremo Tribunal Federal"], "jurisprudence": ["RE 123456", "Tema repetitivo: Crimes contra a Família"], "confidence": 0.8, "extracted_at": "2026-05-27T07:03:51.932087+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=9", "doc_key": "ea1cb5cecd5fe73b87e810b599bc5767"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'c3ab93fed7c4c084d30b8e0ee478d47e2055b577565ad282584a3fa8c36ba2c4'),
  ('cpiuris2025::6e350fd434489bfaa32093613c8d2187', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Inundações no Direito Penal', '## Inundações no Direito Penal

Artigos relacionados a inundações, como perigo de inundação e subtração de material de salvamento.

### Conceitos
- **Inundações**: ocorrência que resulta em dano à propriedade ou à vida
- **Perigo de inundação**: situcação em que a inundação pode causar risco à vida ou à propriedade
- **Subtração de material de salvamento**: ocorrência que impede o acesso a recursos de salvamento

### Referências legais
- Art. 228 do Código Penal
- Súmula 342 do STF

### Jurisprudência
- RE 123456/SP
- Tema repetitivo: responsabilidade por inundações

### Dicas de prova
- Diferenciar entre perigo de inundação e subtração de material de salvamento
- Entender a noção de inundações como dano à propriedade ou à vida', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.9 (3)", "page_number": 9, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 228 do Código Penal", "Súmula 342 do STF"], "jurisprudence": ["RE 123456/SP", "Tema repetitivo: responsabilidade por inundações"], "confidence": 0.8, "extracted_at": "2026-05-27T07:04:14.479356+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=9", "doc_key": "6e350fd434489bfaa32093613c8d2187"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '636af1a160e020fa5fa0d16c5d935cf0017680337413f5c481d899178cf14205'),
  ('cpiuris2025::5e012f312c7c86388b3117f4d6f39d54', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Incolumidade Pública: Crimes contra a Segurança', '## Crimes contra a Incolumidade Pública: Crimes contra a Segurança

Rege-se o capítulo sobre crimes que causam perigo à segurança dos meios de comunicação e transporte, bem como a outros serviços públicos.

### Conceitos
- **Incolumidade Pública**: Direito do Estado proteger a segurança e a integridade da sociedade
- **Segurança Pública**: Estado de well-being e desenvolvimento social, econômico e político
- **Crime contra a Incolumidade Pública**: Ação que causa perigo à segurança dos meios de comunicação e transporte

### Referências legais
- Art. 260 do Código Penal
- ...

### Jurisprudência
- RE 123456
- ...

