  ('cpiuris2025::03e9da541606d94a3e445324bb6bce73', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Emprego de processos proibidos ou substâncias não permitidas', '## Emprego de processos proibidos ou substâncias não permitidas

Artigo que trata do emprego de processos proibidos ou substâncias não permitidas no comércio, posse ou uso de entorpecente ou substância que determine dependência física ou psíquica.

### Conceitos
- **Emprego de processos proibidos**: Uso de processos proibidos em atividades criminosas
- **Substâncias não permitidas**: Materiais ou substâncias que não são autorizadas por lei para uso ou comércio
- **Comércio, posse ou uso de entorpecente**: Atividades relacionadas ao comércio, posse ou uso de substâncias que determinam dependência física ou psíquica
- **Crimes contra a paz pública**: Atividades que prejudicam a ordem social e a segurança pública

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Distinção entre emprego de processos proibidos e substâncias não permitidas
- Conhecimento do artigo que regula o comércio, posse ou uso de entorpecente ou substância que determine dependência física ou psíquica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.10 (2)", "page_number": 10, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T07:05:20.645723+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=10", "doc_key": "03e9da541606d94a3e445324bb6bce73"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '16b8b1fefca53144dda97e89d11d979f9bc65fd161fe9ae9aea42e81ebf2174f'),
  ('cpiuris2025::d3b05b9415911354e82f55e61dcfe582', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Fé Pública', '## Crimes contra a Fé Pública

Artigos relacionados a crimes cometidos contra a fé pública, incluindo falsidade e petrechos.

### Conceitos
- **Falsidade**: Ação de apresentar algo como verdade o que não é.
- **Petrecho**: Objeto utilizado para cometer um crime
- **Crimes contra a Fé Pública**: Tipos de crimes cometidos contra a fé pública

### Referências legais
- Art. 28 da Lei nº 9.449/1997

