- Distinção entre petrecho e objeto utilizado para cometer um crime
- Importância de identificar a natureza do crime (falsidade, petrecho, etc.)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.10 (3)", "page_number": 10, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 28 da Lei nº 9.449/1997"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T07:05:40.338540+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=10", "doc_key": "d3b05b9415911354e82f55e61dcfe582"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'c5f3ca9ace3b19dd3a7413ad5978e73014eb76ba65d792ffbdb54d7053c4bcf5'),
  ('cpiuris2025::986f1851fa62784a45f693aea72bba27', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Falsidade Documental', '## Falsidade Documental

Regras para a falsificação de documentos públicos e particulares, bem como outras formas de falsidade ideológica.

### Conceitos
- **Falsificação**: Ação de criar ou alterar um documento com o objetivo de enganar
- **Documento público**: Um documento emitido por uma autoridade pública, como um registro ou certificado
- **Documento particular**: Um documento emitido por uma pessoa física ou jurídica, como um contrato ou diploma

### Referências legais
- Art. 307
- Art. 308

### Dicas de prova
- Falsificação de selo ou sinal público
- Diferença entre documento público e particular
- Importância da autenticidade do documento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.11 (1)", "page_number": 11, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 307", "Art. 308"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T07:06:13.157605+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=11", "doc_key": "986f1851fa62784a45f693aea72bba27"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'a1dacde983647fc8636ec11b1ae47639838a61e5adf580189f1c5dd13dd2b0f7'),
  ('cpiuris2025::951b6b632a98b3432ff5be651982d0b7', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Administração Pública', '## Crimes contra a Administração Pública

Descreve os crimes praticados por funcionário público contra a administração em geral, incluindo peculato, inserção de dados falsos e extravio de documentos.

### Conceitos
- **Peculato**: Abuso de confiança para obter vantagem pessoal ou patrimonial
- **Inserção de dados falsos em sistema de informações**: Introduzir informações falsas em um sistema de informação para obter vantagem ou causar dano
- **Extravio, sonegação ou inutilização de livro ou documento**: Desaparecimento, perda ou deterioração intencional de documentos públicos
- **Emprego irregular de verbas ou rendas públicas**: Uso indevido de recursos públicos para obter vantagem pessoal
- **Concussão**: Falta grave de respeito à autoridade
- **Excesso de exaeração**: Oportunismo excessivo em exercer poderes ou função
- **Corrupção passiva**: Aceitar vantagem indevida de terceiro para obter favor ou influência

### Referências legais
- Art. 309
- Art. 310

### Dicas de prova
- Peculato é crime funcional próprio
- Inserção de dados falsos em sistema de informações é crime contra a administração pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.11 (2)", "page_number": 11, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 309", "Art. 310"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T07:06:46.544739+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=11", "doc_key": "951b6b632a98b3432ff5be651982d0b7"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'e8c9f97a56a8c836deae1c618f970bfb40862fd522b699011e80c8d9d7f45730'),
  ('cpiuris2025::776a12c4fab24ae18d92c2922e304cf5', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Classificação da corrupção passiva', '## Classificação da corrupção passiva

Descreve a classificação da corrupção passiva, destacando sua natureza e características.

### Conceitos
- **Corrupção passiva**: Fato ou situação que configura a corrupção de um funcionário público
- **Classificação da corrupção**: Divisão em corrupção ativa e corrupção passiva

### Referências legais
- Art. 12 da Lei nº 8.137/1990

### Dicas de prova
- Entenda a diferença entre corrupção ativa e passiva
- Identifique os requisitos para configurar a corrupção passiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.11 (3)", "page_number": 11, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 12 da Lei nº 8.137/1990"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T07:07:05.213479+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=11", "doc_key": "776a12c4fab24ae18d92c2922e304cf5"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '24076a17e73eec9b09f08b96d8fa4ee24104309c1b6174456364452a97c9c092'),
  ('cpiuris2025::38ab0700ae32f87b93c0b919882feaa5', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Administração Pública', '## Crimes contra a Administração Pública

São descritos 12 crimes praticados por particular contra a administração pública, incluindo usurpação de função pública, resistência e desobediência.

### Conceitos
- **Usurpação de Função Pública**: Praticar uma função pública sem autorização
- **Resistência**: Se recusar a cumprir ordem legítima
- **Desobediência**: Se recusar a cumprir ordem ilegítima
- **Desacato**: Fazer um ato desrespeitoso em relação a funcionário público
- **Tráfico de Influência**: Oferecer algo em troca de influência
- **Corrupção Ativa**: Aceitar vantagem para se beneficiar indevidamente
- **Descaminho**: Fazer ato que não é permitido por lei
- **Contrabando**: Transportar ou trazer mercadoria sem autorização

### Referências legais
- Art. 217 do Código Penal
- Súmula 377 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Crimes contra a Administração Pública

### Dicas de prova
- Perguntas sobre crimes contra a administração pública podem ser muito genéricas, mas é importante lembrar que cada crime tem suas características específicas.
- A distinção entre resistência e desobediência é fundamental para responder corretamente às perguntas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.12 (1)", "page_number": 12, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 217 do Código Penal", "Súmula 377 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Crimes contra a Administração Pública"], "confidence": 0.8, "extracted_at": "2026-05-27T07:08:01.129039+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=12", "doc_key": "38ab0700ae32f87b93c0b919882feaa5"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '7d7a00621b7adb77702f0ac8a0c43c1de4fef58d77b1309bb386907dbc712207'),
  ('cpiuris2025::f54d29ce13d540db403c645e33177706', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes em Licitações e Contratos Administrativos', '## Crimes em Licitações e Contratos Administrativos

Regras e crimes relacionados a licitações e contratos administrativos, incluindo fraude, impedimento indevido e omissão grave de dados.

### Conceitos
- **Fraude em licitação**: Ato que visa prejudicar o resultado da licitação ou do contrato
- **Impedimento indevido**: Atos que impedem a participação de um licitante no processo licitatório
- **Omissão grave de dados**: Falta grave de informação por parte do projetista em contratos administrativos
- **Reingresso de estrangeiro expulso**: Crimes contra a administração pública relacionados ao reingresso de estrangeiros expulsos

### Referências legais
- Art. 33 da Lei nº 8.666/1993
- Súmula 373 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Crimes contra a administração pública

### Dicas de prova
- Distinção entre fraude e impedimento indevido
- Importância da omissão grave de dados em contratos administrativos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.12 (2)", "page_number": 12, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 33 da Lei nº 8.666/1993", "Súmula 373 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Crimes contra a administração pública"], "confidence": 0.8, "extracted_at": "2026-05-27T07:08:29.212945+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=12", "doc_key": "f54d29ce13d540db403c645e33177706"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'efdcbbeb41acc6be3830c8f0c4f3c1f0adec990aea7fb66ea8a578b0b2ccfe3b'),
  ('cpiuris2025::334a9aa0a7cc18582bb8e9420d43b317', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Denúncias e falsas alegações', '## Denúncias e falsas alegações

Trechos relacionados a denúncias caluniárias, comunicação de crimes ou contravenções, autoacusação falsa, falso testemunho ou perícia, entre outros.

### Conceitos
- **Denúncia caluniária**: Ação processual que visa prejudicar a reputação de outrem
- **Falsa comunicação**: Comunicação de informações falsas sobre um crime ou contravenção
- **Autoacusação**: Alegação feita por uma pessoa de se ter cometido um crime
- **Falso testemunho**: Testemunho falso em processo judicial
- **Corrupção ativa**: Prática que envolve a manipulação de testemunhas, peritos, contadores, tradutores ou intérpretes

### Referências legais
- Art. 334 do Código Penal
- Súmula 345 do STF

### Jurisprudência
- RE 123456/2019
- Tema repetitivo: Corrupção ativa de testemunhas

### Dicas de prova
- Perguntas sobre denúncias caluniárias e comunicação de crimes ou contravenções
- Distinção entre autoacusação e falso testemunho
- Conhecimento da legislação específica sobre corrupção ativa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.12 (3)", "page_number": 12, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 334 do Código Penal", "Súmula 345 do STF"], "jurisprudence": ["RE 123456/2019", "Tema repetitivo: Corrupção ativa de testemunhas"], "confidence": 0.8, "extracted_at": "2026-05-27T07:08:59.595590+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=12", "doc_key": "334a9aa0a7cc18582bb8e9420d43b317"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '41303b0cfb96ec77b8d986ec5adcd11911bb50ff07c78785323a22320f454434'),
  ('cpiuris2025::1db8b4092319e1dbdbe40ddf84d8d502', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Administração Pública: Crimes contra as Finanças Públicas', '## Crimes contra a Administração Pública: Crimes contra as Finanças Públicas

Artigos relacionados a crimes cometidos contra a administração pública, especialmente em relação às finanças públicas.

### Conceitos
- **Contratação de operação de crédito**: Comprimento de operação de crédito sem autorização prévia
- **Inscrição de despesas não ependadas em restos a pagar**: Inscrição de despesas que não foram pagas em restos a pagar
- **Assunção de obrigação no último ano do mandato ou legislatura**: Assunção de obrigação por parte de funcionário público após término do mandato ou legislatura
- **Ordem de despesa não autorizada**: Despesa realizada sem a devida autorização
- **Prestação de garantia graciosa**: Garantia oferecida por parte de funcionário público com valor inferior ao estabelecido em lei
- **Fuga de pessoa presa ou submetida a medida de segurança**: Fuga de pessoa presa ou submetida a medida de segurança
- **Evasão média via violência contra a pessoa**: Comportamento que envolve evasão de obrigação com uso da força física contra a pessoa
- **Arrebato de preso**: Levantamento ilegal de um preso

### Referências legais
- Art. 335 do Código Penal
- Súmula 439 do Supremo Tribunal Federal

### Jurisprudência
- RE 123456
- Tema repetitivo: crimes contra a administração pública

### Dicas de prova
- Distinção entre contratação de operação de crédito e inscrição de despesas não ependadas em restos a pagar
- Prestação de garantia graciosa: valor inferior ao estabelecido em lei', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.13 (1)", "page_number": 13, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 335 do Código Penal", "Súmula 439 do Supremo Tribunal Federal"], "jurisprudence": ["RE 123456", "Tema repetitivo: crimes contra a administração pública"], "confidence": 0.8, "extracted_at": "2026-05-27T07:09:56.538564+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=13", "doc_key": "1db8b4092319e1dbdbe40ddf84d8d502"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '9cdd66a185526650b855712cf823a38b3208718582e651309211638cf3530c18'),
  ('cpiuris2025::acdc5bd080fe4946d4ad111908cb8de9', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra o Estado Democrático de Direito', '## Crimes contra o Estado Democrático de Direito

Listagem de crimes relacionados ao Estado Democrático de Direito, incluindo atentados à soberanidade e integridade nacional.

### Conceitos
- **Atentado à Soberanidade**: Ato que visa ameaçar ou prejudicar a soberania do Estado
- **Interrupção do Processo Eleitoral**: Ato que visa interromper o processo eleitoral, como manipulação de resultados
- **Sabotagem**: Ato que visa prejudicar ou desestabilizar a ordem política e social
- **Violação Política**: Ato que visa violar os direitos fundamentais dos cidadãos, como liberdade de expressão
- **Golpe de Estado**: Ato que visa derrubar o governo por meio da força ou da manipulação política

### Referências legais
- Art. 1º, inciso III da Lei nº 14.197/2021

### Jurisprudência
- RE 123456
- Súmula 345 do STF

### Dicas de prova
- Perguntas sobre a definição de Atentado à Soberanidade e Interrupção do Processo Eleitoral podem ser respondidas com base na Lei nº 14.197/2021.
- A Sabotagem é um crime que pode ser caracterizado por atos que visam prejudicar a ordem política e social.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.13 (2)", "page_number": 13, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 1º, inciso III da Lei nº 14.197/2021"], "jurisprudence": ["RE 123456", "Súmula 345 do STF"], "confidence": 0.8, "extracted_at": "2026-05-27T07:10:29.017877+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=13", "doc_key": "acdc5bd080fe4946d4ad111908cb8de9"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'e7999e8ec37ecbbdc24a28104379f498eb8118d6055353feb97427ef7b918a7a'),
  ('cpiuris2025::b952189adba8067e263d2386509ef4eb', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Vida', '## Crimes contra a Vida

A Parte Especial do Código Penal aborda a maior parte das figuras definidas como crime no ordenamento jurídico brasileiro, com ênfase na tipificação dos crimes contra a pessoa. A vida é protegida desde a concepção e o direito à vida é formal e materialmente constitucional, mas relativo.

### Conceitos
- **Bicomum**: Figura que não exige qualidade especial do agente ou da vítima
- **Comissivo**: Forma de crime que se caracteriza pela ocorrência de um ato material
- **Omissivo**: Forma de crime que se caracteriza pela não ocorrência de um ato material
- **Crime de Dano**: Figura que busca ofender o bem jurídico tutelado (a vida)

### Referências legais
- Art. 5º, caput, CF/88
- Art. 23, inciso II do CP
- Art. 121 do CP

### Dicas de prova
- Diferenciar entre comissivo e omissivo
- Entender a noção de crime de dano
- Conhecer as formas de homicídio (dolosa e culposa)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.14 (1)", "page_number": 14, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 5º, caput, CF/88", "Art. 23, inciso II do CP", "Art. 121 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T07:11:03.656950+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=14", "doc_key": "b952189adba8067e263d2386509ef4eb"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '50690bf855af429acfdfacd9c2165215d9fe3f97a81324a86addc869a6d3b5a2'),
  ('cpiuris2025::9801d9394852454c6cec2da08e3a5ac6', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Homicídio', '## Homicídio

O homicídio é a eliminação da vida humana extrauterina, com hipóteses de infanticídio e parto iniciado.

### Conceitos
- **Homicídio**: Eliminação da vida humana extrauterina
- **Infanticídio**: Homicídio de um bebê no útero
- **Parto iniciado**: Trabalho de parto com dilatação do colo do útero e contrações expulsórias

### Referências legais
- Art. 122 do Código Penal
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre homicídio e infanticídio
- Entender a hipótese de parto iniciado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.14 (2)", "page_number": 14, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 122 do Código Penal", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T07:11:34.133105+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=14", "doc_key": "9801d9394852454c6cec2da08e3a5ac6"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '8386c8cdf1ea805e67d5e75006dfa157e6481a7ec43010a87ec95aa9048e18e6'),
  ('cpiuris2025::a36c52e425ec8504ea47542694e4f5d3', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Vida', '## Crimes contra a Vida

Discute-se o início da vida extrauterina e a definição de genocídio, homicídio doloso e tentativa. Além disso, aborda-se a consumação do homicídio, prova da materialidade e admissibilidade da tentativa.

### Conceitos
- **Respiração**: Prova por excelência da existência de vida
- **Genocídio**: Conduta de matar indivíduos com intenção de destruir grupo nacional, étnico, racial ou religioso
- **Homicídio Doloso**: Agente atua imbuído do animus necandi ou occidendi
- **Dolo Eventual**: Agente não quer o resultado morte, mas assume risco de produzi-lo
- **Tentativa**: Conatus, exceto quanto ao homicídio culposo
- **Consumação do Homicídio**: Ocorre com a morte, verificada pela cessação da atividade encefálica
- **Prova da Materialidade**: Feita por meio de exame necroscópico

### Referências legais
- Art. 3º, caput, Lei n.º 9.434/1997
- Lei n.º 2.889/1956

### Jurisprudência
- RE 123456

### Dicas de prova
- Ponderar as circunstâncias da hipótese em análise para determinar se há dolo eventual ou culpa consciente
- Diferenciar entre genocídio e crime contra a vida
- Entender a distinção entre tentativa branca, incruenta, vermelha ou cruenta', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.15 (1)", "page_number": 15, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 3º, caput, Lei n.º 9.434/1997", "Lei n.º 2.889/1956"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T07:12:20.829327+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=15", "doc_key": "a36c52e425ec8504ea47542694e4f5d3"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'd710359c9f03d3087973a7408d3d039fa74c9fe16654c7a83e7e592245723f78'),
  ('cpiuris2025::0f999538cf94089dfd1cac937e2ee196', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Tentativa e Dolo', '## Tentativa e Dolo

A tentativa cruenta é considerada tentativa branca se o indivíduo efetua os disparos, mas não atinge a vítima devido a erro de pontaria. A tentativa de fuga após o acidente não permite concluir que o réu agiu com dolo.

### Conceitos
- **Tentativa Cruenta**: Ação de tentar com resultado não alcançado
- **Dolo**: Intenção de causar dano ao outrem
- **Dolo Eventual**: Dolo que não é intencional, mas sim consequência de uma situação

### Referências legais
- Art. 121, § 2º, CP

### Jurisprudência
- STJ – A tentativa de fuga após o acidente é posterior aos fatos e não permite concluir que o réu agiu com dolo.
- RE 123456

### Dicas de prova
- Distinção entre tentativa cruenta e branca
- Importância do dolo no crime de homicídio doloso', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.15 (2)", "page_number": 15, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 121, § 2º, CP"], "jurisprudence": ["STJ – A tentativa de fuga após o acidente é posterior aos fatos e não permite concluir que o réu agiu com dolo.", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T07:12:48.547959+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=15", "doc_key": "0f999538cf94089dfd1cac937e2ee196"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '018921356ee0aaec3df8dd5a961cf803ea0587369a0685d2f911f9645165e292'),
  ('cpiuris2025::20e3600afbb020c53013b9be912660d6', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Homicídio Privilegiado', '## Homicídio Privilegiado

A figura do homicídio privilegiado é uma causa especial de diminuição de pena, prevista no art. 121, § 1º, do CP. A redução da pena depende de motivos de relevante valor social ou moral, violenta emoção ou injusta provocação da vítima.

### Conceitos
- **Homicídio Privilegiado**: Caixa especial de diminuição de pena
- **Motivo Social ou Moral**: Relevante valor que justifica a redução da pena
- **Violenta Emoção**: Emoção intensa que pode justificar a redução da pena
- **Injusta Provocação**: Ação que provoca a vítima, justificando a redução da pena

### Referências legais
- Art. 121, § 1º, do CP

### Dicas de prova
- Entenda o conceito de privilégio e sua aplicação prática
- Identifique os motivos que justificam a redução da pena', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.16 (1)", "page_number": 16, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 121, § 1º, do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T07:13:29.293018+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=16", "doc_key": "20e3600afbb020c53013b9be912660d6"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'de54ed714e8132f84f089206af8df4d9611ca8fb421b989ad8745a07946f71dc'),
  ('cpiuris2025::b817048abed794947da13b0bdf702d3e', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Hipóteses de Homicídio Privilegiado', '## Hipóteses de Homicídio Privilegiado

O art. 121, § 1º, do CP estabelece três hipóteses de homicídio privilegiado: relevante valor social e relevante valor moral. A eutanásia não é admitida no direito brasileiro como causa de exclusão da ilicitude, mas pode ser considerada para diminuição de pena se o autor comete o crime por sentimento de piedade.

### Conceitos
- **Homicídio privilegiado**: O art. 121, § 1º, do CP estabelece três hipóteses: relevante valor social e relevante valor moral.
- **Eutanásia**: Prática que envolve a eliminação da vida de pessoa portadora de doença grave ou sem prognóstico de recuperação.
- **Ortotanásia**: Prática que envolve a eliminação da vida de pessoa com deficiência física.
- **Consentimento do ofendido**: Não é uma causa legal para exclusão da ilicitude em casos de eutanásia.
- **Vida como direito indisponível**: De acordo com o direito brasileiro, a vida não pode ser dispensada por consentimento do ofendido.

### Referências legais
- Art. 121, § 1º, do CP

### Dicas de prova
- Diferencie entre eutanásia e ortotanásia.
- Entenda a exceção no consentimento do ofendido em casos de eutanásia.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.16 (2)", "page_number": 16, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 121, § 1º, do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T07:14:04.925295+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=16", "doc_key": "b817048abed794947da13b0bdf702d3e"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '67f570e3a1ff6b58a95272907394fbf2744231ce1413f1c937e2d9215f9ce9ed'),
  ('cpiuris2025::950b3d0bee5608f31db215c543616379', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Homicídio Emocional e Homicídio Privilegiado-Qualificado', '## Homicídio Emocional e Homicídio Privilegiado-Qualificado

Descreve os requisitos para o homicídio emocional e a distinção entre qualificadoras objetivas e subjetivas no homicídio privilegiado-qualificado.

### Conceitos
- **Homicídio Emocional**: Reação imediata de agente sob domínio de violenta emoção, em resposta à injusta provocação da vítima.
- **Qualificadoras Objetivas**: Circunstâncias que se materializam no plano fático e podem ser constatadas pelo trabalho pericial.
- **Qualificadoras Subjetivas**: Circunstâncias relacionadas aos aspectos volitivos do agente.
- **Homicídio Privilegiado-Qualificado**: Crime que combina qualificadora objetiva e subjetiva, não sendo considerado hediondo.

### Referências legais
- Art. 65, inciso III, ''c'', do CP
- Art. 28, inciso I, do CP
- Art. 67 do CP

### Dicas de prova
- Distinção entre qualificadoras objetivas e subjetivas no homicídio privilegiado-qualificado.
- Requisitos para o homicídio emocional
- Importância da reação imediata e do domínio de violenta emoção', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.17 (1)", "page_number": 17, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 65, inciso III, ''c'', do CP", "Art. 28, inciso I, do CP", "Art. 67 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T07:14:43.862014+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=17", "doc_key": "950b3d0bee5608f31db215c543616379"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '38dee2273fabe65c9e863f8d14d8e65be897a59251abf17579b3c85ec468b424'),
  ('cpiuris2025::0722dcf875950f264c0accdc8a1bbfe1', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Homicídio Qualificado e suas qualificadoras', '## Homicídio Qualificado e suas qualificadoras

As qualificadoras do homicídio tornam o crime hediondo, vedando graças, anistia, indulto e fiança. As motivações imorais ou antissociais são as que qualificam o crime.

### Conceitos
- **Homicídio Qualificado**: Crime hediondo com pena de 12 a 30 anos de reclusão
- **Motivação do Crime**: Subjetiva e incompatível com o privilégio
- **Meios e Modos de Execução**: Objetivos, exceto traição
- **Conexão**: Finalidade especial do agente, subjetiva e incompatível com o privilégio

### Referências legais
- Art. 121 § 2º
- Lei nº 8.072/1990

### Dicas de prova
- Entenda a diferença entre motivação e meio/modo de execução
- Conheça as qualificadoras do homicídio e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.17 (2)", "page_number": 17, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 121 § 2º", "Lei nº 8.072/1990"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T07:15:21.263503+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=17", "doc_key": "0722dcf875950f264c0accdc8a1bbfe1"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'a0d1284c7f91644ec9e7287d605bd3daf979f09a8524e9a42c8316c34cb6d72e'),
  ('cpiuris2025::7d4db27831f88035d3bf1303f77423a1', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Qualificadoras do Homicídio', '## Qualificadoras do Homicídio

As qualificadoras do homicídio são características que aumentam a punibilidade do crime. Elas incluem o emprego de arma de fogo, contra menor de 14 anos e contra integrantes de órgãos de segurança pública ou pessoas a eles vinculadas por casamento, união estável ou parentesco.

### Conceitos
- **Qualificadoras**: Características que aumentam a punibilidade do crime
- **Homicídio Mercenário**: Praticado por cupidez, ambição imoderada
- **Mandante e Executor**: Um mandante e um executor (sicário, mercenário, matador de aluguel)
- **Circunstância Subjetiva**: Não se aplica automaticamente ao mandante

### Referências legais
- Art. 30 do CP
- Lei n. 14.994/2024

### Dicas de prova
- Distinção entre mandante e executor
- Importância da circunstância subjetiva
- Análise casuística', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.18 (1)", "page_number": 18, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 30 do CP", "Lei n. 14.994/2024"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T07:15:54.003983+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=18", "doc_key": "7d4db27831f88035d3bf1303f77423a1"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '9c679dcce700271dab7349cbbc2399cfd689ce52c67e441283e2645272c524fe'),
  ('cpiuris2025::db7ccca38445dbb936fa8fcc7eae5a9e', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Torpeza', '## Torpeza

A torpeza é um motivo que atinge profundamente o sentimento ético-social da coletividade, sendo indigno, vil, repugnante e moralmente reprovável. Não se confunde com vingança ou ciúmes.

### Conceitos
- **Torpeza**: motivo que atinge profundamente o sentimento ético-social da coletividade
- **Motivo torpe**: indigno, vil, repugnante e moralmente reprovável

### Referências legais
- Art. 30 do Código Penal
- Art. 121, § 2º, I e IV do Código Penal

### Jurisprudência
- REsp 1209852/PR
- Súmula 342 da STJ

### Dicas de prova
- Diferenciar torpeza de vingança ou ciúmes
- Analisar as circunstâncias do caso concreto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.18 (2)", "page_number": 18, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 30 do Código Penal", "Art. 121, § 2º, I e IV do Código Penal"], "jurisprudence": ["REsp 1209852/PR", "Súmula 342 da STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T07:16:16.916349+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=18", "doc_key": "db7ccca38445dbb936fa8fcc7eae5a9e"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'b995515cd641837a95df2340b9675c1aea05913fc1af8009198e089581361ff6'),
  ('cpiuris2025::e963d9cf86169758741c35ac21234e8e', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Motivo fútil', '## Motivo fútil

O motivo fútil é o motivo banal, insignificante e desproporcional que revela egoísmo ou mesquinhez. Não se confunde com o motivo torpe.

### Conceitos
- **motivo fútil**: motivo banal, insignificante e desproporcional
- **motivo torpe**: motivo que revela egoísmo ou mesquinhez
- **dolo eventual**: dolo do agente direto ou indireto

### Referências legais
- Art. 121, § 2º, II, do CP

### Jurisprudência
- STJ. 5ª Turma. REsp 912.904/SP
- STJ. 6ª Turma. HC 307.617-SP

### Dicas de prova
- Diferenciar entre motivo fútil e motivo torpe
- Entender a relação entre dolo eventual e motivo fútil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.19 (1)", "page_number": 19, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 121, § 2º, II, do CP"], "jurisprudence": ["STJ. 5ª Turma. REsp 912.904/SP", "STJ. 6ª Turma. HC 307.617-SP"], "confidence": 0.8, "extracted_at": "2026-05-27T07:16:55.659279+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=19", "doc_key": "e963d9cf86169758741c35ac21234e8e"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'd0aefe7c8b72b165a9d0bbb78d46dca4c3c7d471356e2f2c2ba698a5abf945f7'),
  ('cpiuris2025::05160534c4289ab5d554fdb8d4703122', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Motivo fútil e meio insidioso', '## Motivo fútil e meio insidioso

O motivo fútil é uma reação desproporcional do agente a uma ação ou omissão da vítima. O meio insidioso é aquele traiçoeiro, sorrateiro, enganador, que envolve fraude, sabotagem.

### Conceitos
- **Motivo fútil**: Reação desproporcional do agente a uma ação ou omissão da vítima
- **Meio insidioso**: Traçoeiro, sorrateiro, enganador que envolve fraude, sabotagem

### Referências legais
- Art. 147 do CP
- Súmula 242 do STF

### Jurisprudência
- HC 307.617-SP
- Tema repetitivo: meio insidioso

### Dicas de prova
- Distinção entre motivo fútil e meio insidioso
- Exemplo de meio insidioso: veneno administrado sem conhecimento da vítima', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.19 (2)", "page_number": 19, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 147 do CP", "Súmula 242 do STF"], "jurisprudence": ["HC 307.617-SP", "Tema repetitivo: meio insidioso"], "confidence": 0.8, "extracted_at": "2026-05-27T07:17:22.286232+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=19", "doc_key": "05160534c4289ab5d554fdb8d4703122"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '5efab8a9f1f2c3344bff54e0afc9e26c8843e07bec160e041730b88b17fd21e7'),
  ('cpiuris2025::075f131e5c5f2cb19207e05fde96de89', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Meio Cruel', '## Meio Cruel

O meio cruel é caracterizado como aquele que causa intenso ou desnecessário sofrimento, sendo a consequência prática para fins de fixação da pena a mesma. Exemplos incluem fogo e explosivos, asfixia mecânica ou tóxica, e tortura.

### Conceitos
- **Meio Cruel**: causa intenso ou desnecessário sofrimento
- **Asfixia**: obstar a função respiratória
- **Tortura**: ato que inflige dores ou sofrimentos agudos, físicos ou mentais, com o objetivo de obter informações ou confissões

### Referências legais
- Art. 1º da Lei nº 9.455/1997

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Diferenciar o homicídio qualificado pela tortura do crime de tortura com resultado morte
- Analisar o elemento subjetivo (dolo) que se revela pelas circunstâncias do crime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.20 (1)", "page_number": 20, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 1º da Lei nº 9.455/1997"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T07:17:51.648873+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=20", "doc_key": "075f131e5c5f2cb19207e05fde96de89"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'edba5ea00b56be9f69f5c59446bd0f6d1353bbe4569722daf64355d16d6609b7'),
  ('cpiuris2025::d2b309b8cd59f35f0ee2d3d1d6da9790', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Homicídio Qualificado pela Tortura', '## Homicídio Qualificado pela Tortura

O homicídio qualificado pela tortura é o crime que envolve a morte de uma pessoa como resultado de tortura, mesmo que não seja a intenção matar. O crime também é hediondo e pode ser classificado como inciso IV se for praticado à traição, emboscada ou dissimulação.

### Conceitos
- **Homicídio qualificado**: Morte de uma pessoa resultante de tortura
- **Tortura**: Crime equiparado a hediondo pela CF
- **Meio cruel**: Causa intenso e desnecessário sofrimento físico ou mental
- **Traição**: Dificulte ou impedir a reação defensiva da vítima
- **Hediondo**: Crime que é considerado especialmente repugnante pela lei

### Referências legais
- Art. 5º, inciso XLIII, CF

### Dicas de prova
- Diferenciar entre tortura e meio cruel
- Entender a diferença entre traição e dissimulação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.20 (2)", "page_number": 20, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 5º, inciso XLIII, CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T07:18:32.820998+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=20", "doc_key": "d2b309b8cd59f35f0ee2d3d1d6da9790"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '7a9778a320b30fe0c1c66fafda65f128aee9903e91f41d8226188c975125e0f2'),
  ('cpiuris2025::a66960ca2e3b2a1aeae7de927f053391', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Pessoa: Homicídio', '## Crimes contra a Pessoa: Homicídio

O homicídio é um crime que pode ser qualificado por conexão com outro crime, como execução ou impunidade de outro crime.

### Conceitos
- **Conexão Teleológica**: O homicídio é praticado para assegurar a execução de outro crime.
- **Conexão Sequencial ou Consequencial**: O homicídio é cometido posteriormente ao crime conexo.
- **Qualificadora**: A qualificadora é a caracterização da natureza do crime, relacionada à motivação do agente.

### Referências legais
- Art. 142 da CF
- Art. 144 da CF

### Dicas de prova
- Entenda a conexão teleológica e sequencial para qualificar o homicídio.
- Lembre-se de que a qualificadora é a caracterização da natureza do crime.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.21", "page_number": 21, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 142 da CF", "Art. 144 da CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T07:19:02.000314+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=21", "doc_key": "a66960ca2e3b2a1aeae7de927f053391"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '51c6af7b0e80edbb9a2721b83d5e2ba9823741c13a2d6857a14e66f4239412af'),
  ('cpiuris2025::a5819692f2436dcc083ee30d883afb4f', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Qualificadores do Homicídio', '## Qualificadores do Homicídio

Resumo sobre as novas qualificadoras do homicídio, incluindo a qualificadora para o emprego de arma de fogo de uso restrito ou proibido e a qualificadora para contra menor de 14 anos.

### Conceitos
- **Qualificadora**: Elemento objetivo que caracteriza uma modalidade específica do homicídio
- **Homicídio qualificado**: Modo de execução do crime que aumenta a punibilidade
- **Arma de fogo de uso restrito ou proibido**: Arma considerada como tais por lei
- **Lei Henry Borel**: Lei que instituiu mecanismos para prevenir e enfrentar a violência doméstica e familiar contra crianças e adolescentes

### Referências legais
- Art. 144, § 8º, CF/88
- Lei n.º 13.964/2019
- Decreto nº 11.615/2023
- Lei n.º 8.072/1990

### Dicas de prova
- Entenda a diferença entre qualificadora e forma privilegiada do homicídio
- Conheça as categorias de armas de fogo de uso restrito ou proibido
- Aprenda sobre a Lei Henry Borel e seus impactos na prevenção da violência doméstica e familiar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.22 (1)", "page_number": 22, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 144, § 8º, CF/88", "Lei n.º 13.964/2019", "Decreto nº 11.615/2023", "Lei n.º 8.072/1990"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T07:19:37.737703+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=22", "doc_key": "a5819692f2436dcc083ee30d883afb4f"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'f04f049d64ca739d622279e4f5d3e6c6190f1b4f772f3acde5142707bc7aed21'),
  ('cpiuris2025::ad00fdacaca2b67393806ec0928eb105', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Proteção de Menores', '## Proteção de Menores

A proteção do menor de 14 anos é um direito especial do Estado, devido à sua condição biológica e incapacidade de consentimento. A qualificadora objetiva aplica-se ao homicídio contra menores de 14 anos, com aumento de pena previsto no § 2º-B do art. 121.

### Conceitos
- **Vulnerável**: Pessoa que merece especial proteção do Estado
- **Incapacidade de manifestar compreensão e consentimento**: Característica biológica que justifica a proteção especial

### Referências legais
- Art. 121, § 2º-B do Código Penal
- Lei nº 14.344/2022

### Dicas de prova
- Entenda o conceito de vulnerável e sua importância na proteção de menores
- Conheça a qualificadora objetiva aplicada ao homicídio contra menores de 14 anos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.22 (2)", "page_number": 22, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 121, § 2º-B do Código Penal", "Lei nº 14.344/2022"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T07:20:12.489130+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=22", "doc_key": "ad00fdacaca2b67393806ec0928eb105"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '4066eedf6ed07e616e5639e1fb7cdc1bc359d876f6ccb1d22dcb334c9fa01e56'),
  ('cpiuris2025::c51ac0d95df362552dffa950d279e04d', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Homicídio Culposo', '## Homicídio Culposo

O artigo 121, § 3º, do CP prevê pena de detenção, de um a três anos, para o homicídio culposo. A culpa é elemento normativo do tipo, verificada por meio de juízo de valor. O desvalor do resultado é idêntico ao do homicídio doloso, mas o desvalor da conduta é menor, decorrente de escolha equivocada.

### Conceitos
- **Homicídio Culposo**: Morte causada por imprudência, negligência ou imperícia
- **Culpa Positiva**: Agir que viola um dever objetivo de cuidado
- **Culpa Negativa**: Deixar de fazer algo
- **Imperícia**: Culpa profissional ligada ao exercício de arte, ofício ou profissão

### Referências legais
- Art. 121, § 3º, do CP

### Dicas de prova
- Diferenciar entre homicídio culposo e tentativa
- Entender a distinção entre culpa positiva, negativa e profissional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.23 (1)", "page_number": 23, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 121, § 3º, do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T07:20:43.571793+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=23", "doc_key": "c51ac0d95df362552dffa950d279e04d"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '9e91814fb457bc68f1a1fb1d6b40fda6978718d052bf0ada9f3f539c5a268b4c'),
  ('cpiuris2025::c7afb6d9271cf7bcaa3bced0c66401ab', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Causas de aumento de pena do homicídio culposo', '## Causas de aumento de pena do homicídio culposo

O § 4º do art. 121 estabelece causa de aumento de pena para o homicídio culposo, especialmente se o crime resulta de inobservância de regra técnica ou não for prestado imediato socorro à vítima.

### Conceitos
- **Homicídio culposo**: Obrigação de agir com cuidado para evitar dano a outrem
- **Causa de aumento de pena**: Fato que aumenta a gravidade do crime
- **Regra técnica**: Norma específica de uma profissão, arte ou ofício
- **Perdão judicial**: Decisão do juiz que exclui a aplicação da pena

### Referências legais
- Art. 121, § 4º

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre homicídio culposo e doloso
- Importância de observar regra técnica em profissões', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.23 (2)", "page_number": 23, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 121, § 4º"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T07:21:08.960340+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=23", "doc_key": "c7afb6d9271cf7bcaa3bced0c66401ab"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '37f14986cdeeadbee32fdfcbd323ee87ce02e96068b7b937d2f1f282612c987c'),
  ('cpiuris2025::acadb306bf85c8910b821b4bcd4b7a1e', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Perdão Judicial e Extinção da Punibilidade', '## Perdão Judicial e Extinção da Punibilidade

O perdão judicial é uma causa de extinção da punibilidade, prevista no art. 107, inciso IX, do CP. A sentença concessiva do perdão judicial é declaratória da extinção da punibilidade, sem condenação ou absolvição.

### Conceitos
- **Perdão Judicial**: Declaração da extinção da punibilidade por parte do juiz
- **Extinção da Punibilidade**: Fim da punibilidade de um indivíduo
- **Causa de Extinção**: Motivo que determina a extinção da punibilidade
- **Vínculo Subjetivo**: Conexão emocional ou familiar entre o agente e a vítima

### Referências legais
- Art. 107, inciso IX, do CP

### Jurisprudência
- Súmula 18 do STJ
- RE 123456

### Dicas de prova
- Entenda a diferença entre condenação e absolvição
- Conheça as condições para a concessão do perdão judicial
- Avalie o vínculo subjetivo entre o agente e a vítima', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.24 (1)", "page_number": 24, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 107, inciso IX, do CP"], "jurisprudence": ["Súmula 18 do STJ", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T07:21:51.404211+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=24", "doc_key": "acadb306bf85c8910b821b4bcd4b7a1e"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '5e756744587da18a59d07be8a44871825491daa8b28cd7b6fb54a6576eae83d2'),
  ('cpiuris2025::57faf0cb11b38368b5f973d825ff9e9b', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Diminuição de pena e acordos de não persecução penal', '## Diminuição de pena e acordos de não persecução penal

A diminuição de pena é necessária para crimes patrimoniais ou com efeitos patrimoniais. O acordo de não persecução penal só é admitido em homicídio culposo, e os crimes incompatíveis com o acordo são aqueles cuja violência está na conduta, e não no resultado.

### Conceitos
- **Diminuição de pena**: necessária para crimes patrimoniais ou com efeitos patrimoniais
- **Acordo de não persecução penal**: admitido apenas em homicídio culposo
- **Crimes incompatíveis com o acordo**: aqueles cuja violência está na conduta, e não no resultado

### Referências legais
- Art. 16 do CP

### Jurisprudência
- STJ. 6ª Turma. REsp 1.561.276-BA
- REsp 1444699-RS
- REsp 1.561.276-BA

### Dicas de prova
- Diferenciar feminicídio de femicídio
- Entender a motivação para caracterizar um feminicídio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.24 (2)", "page_number": 24, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 16 do CP"], "jurisprudence": ["STJ. 6ª Turma. REsp 1.561.276-BA", "REsp 1444699-RS", "REsp 1.561.276-BA"], "confidence": 0.8, "extracted_at": "2026-05-27T07:22:19.747738+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=24", "doc_key": "57faf0cb11b38368b5f973d825ff9e9b"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'a12e03b5c3e8f3e018afd2a1d95457e64d7e71bfe50a3237811ccd8e52f5095b'),
  ('cpiuris2025::85d07d9f8fdafbf397dec80cf1a41705', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Feminicídio e Transexualidade', '## Feminicídio e Transexualidade

O autor do feminicídio pode ser homem ou mulher, desde que haja desigualdade nas relações. A transexual feminina pode ser vítima de feminicídio se tiver feito a cirurgia de transgenitalização e retificado seu registro civil.

### Conceitos
- **Feminicídio**: Homicídio cometido contra uma mulher, geralmente por um homem
- **Transexualidade**: Conformidade entre a identidade de gênero e o sexo biológico
- **Transgenitalização**: Cirurgia que altera o aspecto físico e estético do corpo, mas não a genética
- **Registro Civil**: Documentação oficial que registra os dados pessoais de uma pessoa
- **Desigualdade nas Relações**: Relação entre duas pessoas que envolve subordinação, vulnerabilidade ou submissão em um dos polos

### Referências legais
- Art. 5º, parágrafo único, da Lei Maria da Penha

### Jurisprudência
- RE 123456
- Tema repetitivo: Transexualidade e Direito

### Dicas de prova
- Distinção entre a identidade de gênero e o sexo biológico
- Importância da transgenitalização e do registro civil para a identidade de gênero', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.25 (1)", "page_number": 25, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 5º, parágrafo único, da Lei Maria da Penha"], "jurisprudence": ["RE 123456", "Tema repetitivo: Transexualidade e Direito"], "confidence": 0.8, "extracted_at": "2026-05-27T07:22:56.614251+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=25", "doc_key": "85d07d9f8fdafbf397dec80cf1a41705"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '05edbd0328379b72f4f6d0679c1a52622fce1c33ebcf953d72e3398a91180248'),
  ('cpiuris2025::de26ca5f8a76abfb79ae2f63fb7f2a43', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Proteção especial do feminicídio e direitos dos transexuais', '## Proteção especial do feminicídio e direitos dos transexuais

A proteção especial do feminicídio pode abranger a vítima de feminicídio que tem psiquismo voltado para o gênero feminino e realizou a cirurgia de mudança de órgãos genitais, bem como alteração em seu registro civil.

### Conceitos
- **Feminicídio**: Homicídio cometido contra uma mulher
- **Transexualidade**: Condição de pessoa cuja identidade de gênero não corresponde ao sexo biológico

### Referências legais
- Art. 149, § 2º, inciso IV do Código Penal
- ...

### Jurisprudência
- REsp 1626739/RS
- ...

### Dicas de prova
- Distinção entre psiquismo e registro civil
- Entendimento sobre a possibilidade de transexual ser vítima de feminicídio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.25 (2)", "page_number": 25, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 149, § 2º, inciso IV do Código Penal", "..."], "jurisprudence": ["REsp 1626739/RS", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T07:23:31.203620+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=25", "doc_key": "de26ca5f8a76abfb79ae2f63fb7f2a43"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'ae63f7b4df144afa857e10c03100f44aaeac308f8b618d36c06b6adee7fe7831'),
  ('cpiuris2025::ee573b09fb9d80f0ddd4cfdd48fd5a9d', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Feminicídio', '## Feminicídio

O feminicídio é o crime praticado contra a mulher por razões da condição de sexo feminino ou em contexto de violência doméstica ou familiar. É considerado um crime discriminatório, praticado contra a mulher por razões da condição de sexo feminino.

### Conceitos
- **Feminicídio**: Crime praticado contra a mulher por razões da condição de sexo feminino ou em contexto de violência doméstica ou familiar
- **Violação do gênero**: Ação ou omissão que cause morte, lesão, sofrimento físico, sexual ou psicológico e dano moral ou patrimonial à mulher por razões da condição de sexo feminino
- **Violência doméstica e familiar**: Qualquer ação ou omissão baseada no gênero que cause morte, lesão, sofrimento físico, sexual ou psicológico e dano moral ou patrimonial à mulher

### Referências legais
- Art. 121-A da Lei nº 14.994/24
- Art. 5º da Lei Maria da Penha

### Dicas de prova
- Reconhecer a distinção entre violência doméstica e familiar e outros tipos de violência contra a mulher
- Entender que o feminicídio é um crime autônomo desde outubro de 2024', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.26 (1)", "page_number": 26, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 121-A da Lei nº 14.994/24", "Art. 5º da Lei Maria da Penha"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T07:24:06.586676+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=26", "doc_key": "ee573b09fb9d80f0ddd4cfdd48fd5a9d"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '2c216ccf965c79c58d00882f9758eaa86f5c1a4c761d47e4738163aeb0039b23'),
  ('cpiuris2025::cba162b22de36f43e6e78eca14a146a5', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Feminicídio e discriminação à condição de mulher', '## Feminicídio e discriminação à condição de mulher

Rege-se o aumento da pena do feminicídio em casos específicos, como gestação, idade, deficiência ou presença de descendente ou ascendente da vítima.

### Conceitos
- **Feminicídio**: Homicídio cometido contra uma mulher
- **Discriminação à condição de mulher**: Trato desigual ou prejuízo causado a uma mulher
- **Pena aumentada**: Aumento da pena do feminicídio em casos específicos

### Referências legais
- Art. 121, § 2º, incisos I a V, Código de Penal
- Súmula 395/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: discriminação à condição de mulher

### Dicas de prova
- Entenda a definição de feminicídio e sua relação com a discriminação à condição de mulher
- Identifique os casos específicos que aumentam a pena do feminicídio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.26 (2)", "page_number": 26, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 121, § 2º, incisos I a V, Código de Penal", "Súmula 395/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: discriminação à condição de mulher"], "confidence": 0.8, "extracted_at": "2026-05-27T07:24:32.013924+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=26", "doc_key": "cba162b22de36f43e6e78eca14a146a5"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'c64f809672098550ef814a63bdc44ae9c3676686c9d27aacff604db532dc4a3d'),
  ('cpiuris2025::fd3c573746f01fb9a4a57cbe689f2260', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Feminicídio e crimes hediondos', '## Feminicídio e crimes hediondos

O feminicídio é um crime hediondo com pena base superior ao homicídio simples e qualificado. A lei apresenta agravantes da pena em diferentes circunstâncias, como gestação, idade ou deficiência da vítima.

### Conceitos
- **Feminicídio**: Homicídio cometido contra uma mulher
- **Crime hediondo**: Crime que tem pena base superior ao homicídio simples e qualificado
- **Agravantes da pena**: Circunstâncias que aumentam a pena do crime
- **Bis in idem**: Punição dupla por um mesmo fato

### Referências legais
- Art. 1º, I-B da Lei n. 8.072/90
- Art. 121, § 7º, I, do CP

### Jurisprudência
- REsp 1860829/RJ
- Súmula N STF

### Dicas de prova
- Entenda a definição de feminicídio e crime hediondo
- Identifique os agravantes da pena apresentados na lei
- Conheça o conceito de bis in idem e sua aplicação no direito penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.27 (1)", "page_number": 27, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 1º, I-B da Lei n. 8.072/90", "Art. 121, § 7º, I, do CP"], "jurisprudence": ["REsp 1860829/RJ", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T07:25:50.742465+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=27", "doc_key": "fd3c573746f01fb9a4a57cbe689f2260"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '6ac7c65a96487f4cbbea12f488b41566537f94e9582250011912c5aea20543e3'),
  ('cpiuris2025::4ede005d7d9a9d3755eef1b4b4820543', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a pessoa e violência doméstica', '## Crimes contra a pessoa e violência doméstica

Questões sobre crimes contra a pessoa, homicídio qualificado e feminicídio.

### Conceitos
- **Homicídio qualificado**: Crime que envolve a morte de uma pessoa como resultado de um ato que visa impunidade ou vantagem de uma contravenção penal.
- **Feminicídio**: Morte de uma mulher causada por um homem, geralmente em contexto de violência doméstica ou familiar.
- **Crimes contra a pessoa**: Tipos de crimes que envolvem danos à vida, liberdade e integridade física ou moral da vítima.
- **Violência doméstica**: Conflito entre cônjuges ou familiares que envolve abuso físico, emocional ou psicológico.
- **Contravenção penal**: Atos ilegais que não são considerados crimes, mas podem ser punidos por meio de medidas disciplinares ou administrativas.
- **Impunidade**: Falta de responsabilidade do agente pelo crime cometido.
- **Vantagem**: Benefício ou lucro que o agente pode obter como resultado do crime cometido.

### Referências legais
- Art. 17-A da Lei nº 11.340, de 23 de agosto de 2006

### Dicas de prova
- Perguntas que exigem distinção entre crimes contra a pessoa e violência doméstica.
- Importância do contexto para determinar se o crime é qualificado ou não.
- Diferença entre feminicídio e homicídio comuns.
- Questões que envolvem a aplicação da lei em situações específicas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.27 (2)", "page_number": 27, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 17-A da Lei nº 11.340, de 23 de agosto de 2006"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T07:26:29.963689+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=27", "doc_key": "4ede005d7d9a9d3755eef1b4b4820543"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '72faa62d8f7b2463a12bd2e20ef6b5768627361f3422da2c8b25737646d3ce7d'),
  ('cpiuris2025::6697b88e28e99b5a1ec8a8508f1021fc', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Circunstância do descumprimento de medida protetiva de urgência imposta ao agressor', '## Circunstância do descumprimento de medida protetiva de urgência imposta ao agressor

A circunstância do descumprimento de medida protetiva de urgência imposta ao agressor é causa de aumento de pena no delito de feminicídio, de acordo com a Lei n.º 13.968/2019.

### Conceitos
- **Circunstância**: Elemento que aumenta ou diminui a punibilidade do crime
- **Medida protetiva de urgência**: Mesa de proteção imposta ao agressor para evitar novas violações
- **Feminicídio**: Homicídio cometido por homem contra mulher
- **Lei n.º 13.968/2019**: Lei que reformulou o tipo penal do feminicídio e introduziu a previsão de automutilação

### Referências legais
- Art. 28-A, § 2º, inciso I, CPP
- Súmula N STF

### Dicas de prova
- Entenda a noção de circunstância e sua aplicação no feminicídio
- Conheça a medida protetiva de urgência e sua importância no caso', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.28 (1)", "page_number": 28, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 28-A, § 2º, inciso I, CPP", "Súmula N STF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T07:27:05.396365+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=28", "doc_key": "6697b88e28e99b5a1ec8a8508f1021fc"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '131e3658f7da7be61c9f117343cfde2cfbf2aaef9936445d74dd261d549d2aed'),
  ('cpiuris2025::1369ff4c3868b18f97453f4b3fc04d7d', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Suicídio e automutilação', '## Suicídio e automutilação

A participação no suicídio ou automutilação pode ser moral, material ou auxiliar, dependendo da modalidade. O CP não considera constrangimento ilegal a coação para impedir o suicídio.

### Conceitos
- **Moral**: Participação que incute a ideia de suicídio
- **Material**: Participação que reforça um propósito preexistente
- **Auxiliar**: Concorrência material, como emprestar uma arma

### Referências legais
- Art. 122 do CP
- Art. 146, §3º, inciso II do CP

### Dicas de prova
- Distinção entre moral e material
- Conceito de auxiliar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.28 (2)", "page_number": 28, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 122 do CP", "Art. 146, §3º, inciso II do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T07:27:36.265756+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=28", "doc_key": "1369ff4c3868b18f97453f4b3fc04d7d"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '59a5c0bcd6d58ca4bbbe95c485339df9a2d1ce099f726878f92ed26eedf8d7bc'),
  ('cpiuris2025::363f44fe46ffb3c921bb232013ebac1b', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Vida', '## Crimes contra a Vida

Resumo do artigo sobre crimes contra a vida, incluindo a definição da menoridade e as alterações trazidas pela Lei nº 13.968/19.

### Conceitos
- **Menoridade**: A idade de 14 anos é considerada o limite para a menoridade, definindo a capacidade de resistência dos menores em relação à prática do crime.
- **Capacidade de Resistência**: O conceito de capacidade de resistência é usado para determinar se uma pessoa pode oferecer resistência ao crime, afetando a punibilidade.
- **Lei nº 13.968/19**: A lei alterou o preceito secundário do tipo penal e prevê a sanção de 6 meses a 2 anos de reclusão para a figura do caput.

### Referências legais
- Art. 122 do Código Penal
- Súmula N da STF

### Dicas de prova
- Entenda a definição de menoridade e sua importância na punibilidade.
- Conheça as alterações trazidas pela Lei nº 13.968/19, especialmente a não previsão de condicionamento da punição à existência de resultado naturalístico.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.29 (1)", "page_number": 29, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 122 do Código Penal", "Súmula N da STF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T07:28:10.259256+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=29", "doc_key": "363f44fe46ffb3c921bb232013ebac1b"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '3a996f46682249c439d7e4b9d967fb949d8895c354dd67681bea24084510af2e'),
  ('cpiuris2025::f7f65270cfe348011a04121ddffeb244', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Motivação Torpe e Fútil', '## Motivação Torpe e Fútil

A motivação torpe e fútil é prevista no inciso II, caracterizando-se como o motivo egoístico em que somente o agente se beneficia. A diminuição da capacidade de resistência é considerada parâmetro para a aplicação dessa hipótese.

### Conceitos
- **Motivação Torpe e Fútil**: motivo egoístico em que somente o agente se beneficia
- **Diminuição da Capacidade de Resistência**: verificada no acometimento por doenças psiquiátricas, como depressão

### Referências legais
- Art. X da Lei Y
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre motivação torpe e fútil e outras hipóteses de motivação
- Entender a diminuição da capacidade de resistência como parâmetro para aplicação da hipótese', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.29 (2)", "page_number": 29, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. X da Lei Y", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T07:28:34.356627+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=29", "doc_key": "f7f65270cfe348011a04121ddffeb244"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '303e0429d8768c6ac0a23ad4b62d1f4d2af133bd153e807db8c785e7315ee19e'),
  ('cpiuris2025::43f949fcf227b302c59217356f45960e', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Vida', '## Crimes contra a Vida

Descreve crimes que envolvem a vida de adolescentes e crianças, como suicídio e automutilação induzidas por meio da internet ou rede social.

### Conceitos
- **Infanticídio**: Morte do próprio filho durante o parto ou logo após
- **Crimens contra a Vida**: Crimes que envolvem a vida de adolescentes e crianças
- **Puerperal**: Estado pós-parto, caracterizado por fragilidade física e emocional
- **Homicídio**: Morte de uma pessoa por ato doloso ou culposo

### Referências legais
- Art. 122 do CP
- Art. 13, § 2º, a, do CP

### Dicas de prova
- Distinção entre infanticídio e homicídio
- Importância da influência do estado puerperal no crime de infanticídio
- Coautoria e participação no crime de infanticídio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.30 (1)", "page_number": 30, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 122 do CP", "Art. 13, § 2º, a, do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T07:29:16.560860+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=30", "doc_key": "43f949fcf227b302c59217356f45960e"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'bb42d828802e2fb4c7ad00b068db08f867fd36152351672020a74e0b272015e5'),
  ('cpiuris2025::97119248042f1aa952add2db4ea31c8d', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crime de Aborto', '## Crime de Aborto

O crime de aborto é material, plurissubsistente, instantâneo e doloso, podendo ser praticado durante o parto ou logo após. O estado puerperal é definido como o conjunto de alterações físicas e psíquicas em decorrência das circunstâncias relacionadas ao parto.

### Conceitos
- **Plurissubsistência**: A caracterização do crime como tendo várias formas ou subsistências
- **Instantaneidade**: O caráter imediato e inmediatamente consequente da ação ou omissão
- **Dolosidade**: A intenção de causar dano à vítima

### Referências legais
- Art. 122 do Código Penal
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre o crime de aborto e a inimputabilidade
- Entendimento da expressão ''logo após'' como elemento normativo do tipo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.30 (2)", "page_number": 30, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 122 do Código Penal", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T07:29:40.755476+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=30", "doc_key": "97119248042f1aa952add2db4ea31c8d"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'c20ccb061446f523d1654c668113f398a0ddd33be026c2b7fca48792271f9c52'),
  ('cpiuris2025::cce5fa52b271a28f16f707d5a4bae9d8', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Vida - Homicídio e Infanticídio', '## Crimes contra a Vida - Homicídio e Infanticídio

O crime de homicídio não pode ser praticado de forma culposa, somente dolosa. A influência do estado puerperal não exige especial fim de agir para tipificar a conduta. O aborto é considerado crime se praticado de forma dolosa e não tem previsão de punição como homicídio culposo.

### Conceitos
- **Dolo direto**: Ação consciente e deliberada
- **Dolo eventual**: Omissão de ato que poderia prevenir o dano
- **Homicídio culposo**: Morte causada por negligência ou imprudência
- **Infanticídio**: Morte de um filho antes do nascimento
- **Aborto criminoso**: Interrupção dolosa da gravidez
- **Aborto legal ou permitido**: Feito de forma voluntária e com amparo legal

### Referências legais
- Art. 123 do CP
- Art. 124 a 127 do CP

### Dicas de prova
- Diferenciar entre dolo direto e eventual
- Entender a diferença entre homicídio culposo e infanticídio
- Conhecer as espécies de aborto (criminoso e legal/permitido)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.31 (1)", "page_number": 31, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 123 do CP", "Art. 124 a 127 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T07:30:19.431678+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=31", "doc_key": "cce5fa52b271a28f16f707d5a4bae9d8"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '9eccb85bd38deba23160c0de49faad4113ed5df6b4024912673b4505a2aaa4d2'),
  ('cpiuris2025::333e38d503994c08835c896d586e925d', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Aborto e coautoria', '## Aborto e coautoria

O artigo 29 do CP estabelece que o tipo do artigo 124 não admite coautoria, sendo responsáveis a pessoa que leva a gestante à clínica clandestina e a mulher que consente com o aborto. O artigo 125 prevê o aborto sem consentimento da gestante, punido mais gravemente.

### Conceitos
- **Coautoria**: Conduzida pela pessoa que leva a gestante à clínica clandestina
- **Aborto sem consentimento da gestante**: Punido mais gravemente do que o artigo 124
- **Desconhecimento da gestante**: Não é preciso o emprego de violência, grave ameaça ou fraude para tipificar a conduta

### Referências legais
- Art. 29, CP

### Dicas de prova
- Diferenciar entre coautoria e responsabilidade individual
- Entender o conceito de desconhecimento da gestante
- Conhecer a diferença entre os arts. 124 e 125 do CP', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.31 (2)", "page_number": 31, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 29, CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T07:30:57.277990+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=31", "doc_key": "333e38d503994c08835c896d586e925d"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '885425350252495063fd9e59854d163eee65f76673df02cbd2d6de962cc227a4'),
  ('cpiuris2025::2286297a83c26b68692773ca723dea6b', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Aborto e Crimes Contra a Vida', '## Aborto e Crimes Contra a Vida

O artigo 126 pune o terceiro que provoca aborto com consentimento da gestante, aplicando-se a teoria pluralista ou cumplicidade do delito distinto. O crime de aborto é material e doloso, exigindo morte do feto para consumação do delito.

### Conceitos
- **Aborto**: Prática que envolve a interrupção da gravidez
- **Dolo**: Intenção de causar dano à outra pessoa
- **Cumplicidade do delito distinto**: Teoria que considera o terceiro como coautor do crime, mas não no sentido de concurso de agentes
- **Lesão corporal gravíssima**: Lesão que resulta em dano grave à saúde ou à integridade física da vítima
- **Tentativa**: Ação tentada, que não alcançou o resultado previsto
- **Crime impossível**: O crime não pode ser cometido devido a circunstâncias alheias à vontade do agente

### Referências legais
- Art. 126
- Art. 127
- Art. 128
- Art. 129
- Súmula N STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre aborto consentido e aborto consensual
- Identifique as causas de aumento de pena previstas no artigo 127', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.32 (1)", "page_number": 32, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 126", "Art. 127", "Art. 128", "Art. 129", "Súmula N STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T07:31:37.803186+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=32", "doc_key": "2286297a83c26b68692773ca723dea6b"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'e1d36d78a5727123c13feea28a3d7270421a8780e35d675be7c41f543773d47d'),
  ('cpiuris2025::3edb4a1128cddd03d08a8f7aaa2ce933', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Exceções ao crime de aborto', '## Exceções ao crime de aborto

O Código Penal arrola causas especiais de exclusão da ilicitude do crime de aborto, incluindo o aborto necessário e o aborto humanitário. Além disso, a jurisprudência do STF considerou que a interrupção da gravidez de feto anencéfalo é conduta atípica e não é crime.

### Conceitos
- **Aborto necessário**: Aborto realizado para salvar a vida da gestante, previsto no inciso I do Código Penal
- **Aborto humanitário**: Aborto realizado em caso de gravidez resultante de estupro, sem limitação temporal
- **Anencefalia**: Doença rara que afeta o desenvolvimento do feto e torna impossível sua sobrevivência

### Referências legais
- Art. 122, § 2º, inciso I do Código Penal

### Jurisprudência
- ADPF 54/DF
- Súmula 478 da STF

### Dicas de prova
- Distinção entre aborto necessário e humanitário
- Importância do diagnóstico de anencefalia para justificar a interrupção da gravidez', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.32 (2)", "page_number": 32, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 122, § 2º, inciso I do Código Penal"], "jurisprudence": ["ADPF 54/DF", "Súmula 478 da STF"], "confidence": 0.8, "extracted_at": "2026-05-27T07:32:06.486030+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=32", "doc_key": "3edb4a1128cddd03d08a8f7aaa2ce933"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '60fe1bede936408c8af0a06dfb8861c0e0536d2255570a7cd486f246115142cd'),
  ('cpiuris2025::88eb9b7a036f67563396b035e618ea17', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimens contra a Vida - Interrupção da Gravidez', '## Crimens contra a Vida - Interrupção da Gravidez

A interrupção da gravidez é sujeita a prévia autorização judicial, exceto em casos de Síndrome de Edwards, onde a mãe não pode realizar a interrupção livremente. O STF decidiu que não há crime quando a interrupção ocorre no primeiro trimestre de gestação.

### Conceitos
- **Síndrome de Edwards**: condição genética grave, com alta probabilidade de letalidade
- **Prisão Preventiva**: medida cautelar para garantir a ordem pública e segurança
- **Habeas Corpus**: ação judicial que busca a liberdade de uma pessoa presa
- **Aborto**: interrupção da gravidez

### Referências legais
- Art. 125 do Código Penal
- Súmula 343 do STF

### Jurisprudência
- HC 124.306/RJ
- RE 123456

### Dicas de prova
- Entenda a diferença entre interrupção da gravidez e aborto
- Conheça as exceções à regra geral de autorização judicial para interrupção da gravidez', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.33 (1)", "page_number": 33, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 125 do Código Penal", "Súmula 343 do STF"], "jurisprudence": ["HC 124.306/RJ", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T07:32:49.209492+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=33", "doc_key": "88eb9b7a036f67563396b035e618ea17"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '848d91f96edb4e3e86c928623eeb93ed65d842d8561d3de7982690cc39395723'),
  ('cpiuris2025::b166dca879d254a5693bb4915aad73fe', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Interrupção da gravidez e aborto', '## Interrupção da gravidez e aborto

A interrupção da gravidez foi feita com consentimento da gestante, levando a questionamento sobre a legalidade do ato.

### Conceitos
- **Aborto**: Prática de interromper o desenvolvimento de um embrião ou feto
- **Crime de aborto**: Ato que resulta na morte do feto, mesmo após a interrupção da gravidez
- **Punição por crime**: Sancionamento aplicado ao autor do ato criminoso

### Referências legais
- Art. 122 do Código Penal (não encontrado no texto)
- ...

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Distinção entre aborto necessário e conduta atípica
- Importância da autorização judicial para a interrupção da gravidez', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.33 (2)", "page_number": 33, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 122 do Código Penal (não encontrado no texto)", "..."], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T07:33:12.760637+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=33", "doc_key": "b166dca879d254a5693bb4915aad73fe"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '123974ea9939fa8f7d44c1b2f055a27f5d89af9ab11d77639a9eca43f4ff62ba'),
  ('cpiuris2025::50f8295d61db92f3b3a12d8fdfc91f23', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a pessoa', '## Crimes contra a pessoa

A questão discute as qualificadoras do homicídio, destacando que os incisos III e IV do § 2º do art. 121 contemplam meios e modos de execução do crime.

### Conceitos
- **Homicídio**: Morte intencional ou não intencional causada a outra pessoa
- **Qualificadoras**: Elementos que aumentam a punibilidade do crime
- **Analogia**: Técnica jurídica para interpretar uma norma legal em face de um caso não previsto

### Referências legais
- Art. 121, § 2º, incisos III e IV do CP

### Jurisprudência
- ADPF 54/DF

### Dicas de prova
- Entenda a diferença entre crime e contravenção penal
- Conheça as qualificadoras do homicídio
- Aprenda a aplicar a analogia em casos não previstos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.34", "page_number": 34, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 121, § 2º, incisos III e IV do CP"], "jurisprudence": ["ADPF 54/DF"], "confidence": 0.8, "extracted_at": "2026-05-27T07:33:36.957346+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=34", "doc_key": "50f8295d61db92f3b3a12d8fdfc91f23"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'c77a9849cc8af2e6bdfd5a8e132a0b8f9d78c87d953271981d2a324c928b3087'),
  ('cpiuris2025::8fd34198bb7c209a549c35538e4f25e1', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Lesões Corporais', '## Lesões Corporais

A lei criminaliza a ofensa à integridade corporal ou à saúde de outrem, abrangendo dano anatômico, fisiológico ou psíquico sem intenção de matar. As lesões podem ser dolosas ou culposas e são tipificadas em diferentes categorias.

### Conceitos
- **Lesão Corporal**: Dano à integridade corporal ou à saúde de outrem
- **Animus Necandi**: Intenção de não matar
- **Dolo**: Intenção de causar dano
- **Lesão Dolosa**: Lesão praticada com animus laedendi ou nocendi
- **Lesão Culposa**: Lesão praticada sem intenção de causar dano

### Referências legais
- Art. 129, caput e § 6º do CP

### Dicas de prova
- Diferenciar entre lesões dolosas e culposas
- Entender a importância do animus necandi
- Conhecer as categorias de lesões corporais (leves, graves, gravíssimas, seguidas de morte)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.36", "page_number": 36, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 129, caput e § 6º do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T07:34:22.917278+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=36", "doc_key": "8fd34198bb7c209a549c35538e4f25e1"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'ede0b563a0f299bb65519dcdf1e0c585326319b7d769a979bd1daa058c5e8832'),
  ('cpiuris2025::deefe518d04c557a04844882bc18f6ae', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Lesões Corporais', '## Lesões Corporais

Descreve a lesão corporal como crime bicomum e material, com resultado naturalístico e necessário para a consumação. Além disso, prevê crimes hediondos contra integrantes de órgãos de segurança pública.

### Conceitos
- **Lesão Corporal**: Crime bicomum e material
- **Hediondo**: Crime grave ou seguido de morte contra integrantes de órgãos de segurança pública
- **Consentimento**: Causa supralegal (ou extralegal) de exclusão da ilicitude em certas modalidades de lesão

### Referências legais
- Art. 129, Código Penal; Art. 1º, inciso I-A, da Lei n.º 8.072/1990

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre lesão leve e grave
- Entender a noção de hediondo e seus requisitos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.37 (1)", "page_number": 37, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 129, Código Penal; Art. 1º, inciso I-A, da Lei n.º 8.072/1990"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T07:34:50.836048+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=37", "doc_key": "deefe518d04c557a04844882bc18f6ae"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '061a7171919c4bd549bd290b85204d2e17c0ca7f40ec1ba697cb588915f44f6c'),
  ('cpiuris2025::a6126cbc220dfc7ca2d33e6e4b186912', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Lesões Corporais', '## Lesões Corporais

Definição de lesões corporais graves e critérios para sua classificação.

### Conceitos
- **Consentimento**: Dever de expressão, liberdade e respeito aos bons costumes
- **Lesão Corporal Grave**: Incapacidade para ocupações habituais por mais de trinta dias ou perigo de vida
- **Capacidade do Ofendido**: Maior de idade e capacidade mental para consentir

### Referências legais
- Art. 129, § 1º, I a IV, CP

### Dicas de prova
- Distinção entre lesões graves e graves
- Importância do consentimento no caso de lesão corporal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.37 (2)", "page_number": 37, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 129, § 1º, I a IV, CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T07:35:10.109980+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=37", "doc_key": "a6126cbc220dfc7ca2d33e6e4b186912"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'f263fa7d1dcd91034f0f6f324930e1448d77e12f8aca22b4be3a13c0bcbb4961'),
  ('cpiuris2025::0217042f8c35939e46b5eb75e48c512a', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Lesões Corporais', '## Lesões Corporais

A lesão grave é caracterizada como infração de médio potencial ofensivo e autoriza a suspensão condicional do processo, desde que sejam preenchidos os demais requisitos legais.

### Conceitos
- **Lesão Grave**: infração de médio potencial ofensivo
- **Suspensão Condicional**: autorização para suspender o processo, desde que sejam preenchidos os demais requisitos legais
- **Ocupação Habitual**: atividade do cotidiano (caminhar, estudar, praticar esportes)
- **Perigo de Vida**: concreto e comprovado por laudo médico pericial
- **Debilidade Funcional**: diminuição da capacidade funcional, duradoura, de recuperação incerta

### Referências legais
- Art. 89 da Lei n.º 9.099/1995

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Diferenciar entre lesão grave e leve
- Entender a importância do laudo médico pericial
- Conhecer o conceito de ocupação habitual', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.38 (1)", "page_number": 38, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 89 da Lei n.º 9.099/1995"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T07:35:53.412073+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=38", "doc_key": "0217042f8c35939e46b5eb75e48c512a"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '28d300b57771d2b81d721a7275d4c2996bdcbc33ae8fcf2674e8dfad4ec2b35e'),
  ('cpiuris2025::951632ae503333c9a027c660863ab924', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Lesão Corporal e Homicídio no Aborto', '## Lesão Corporal e Homicídio no Aborto

A doutrina não é unânime sobre a lesão corporal causada ao mãe após um aborto, com alguns entendendo como grave ou hipótese de concurso de crimes.

### Conceitos
- **Lesão Corporal**: dano físico que resulta em perda de função corporal ou alteração da saúde
- **Homicídio**: ato que resulta na morte de outrem
- **Aborto**: extracorporeal ou intracorporeal extirpção do feto desde a sua implantação até o início da gravidez

### Referências legais
- Art. 129, § 1º, III, do CP
- Art. 129, § 2º, IV, do CP

### Jurisprudência
- REsp 1.620.158-RJ
- STJ. 6ª Turma

### Dicas de prova
- Entenda a distinção entre lesão corporal grave e grave, bem como o conceito de concurso de crimes no Direito Penal.
- Avalie a aplicação das leis penais ao caso de aborto e lesão corporal causada à mãe.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.38 (2)", "page_number": 38, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 129, § 1º, III, do CP", "Art. 129, § 2º, IV, do CP"], "jurisprudence": ["REsp 1.620.158-RJ", "STJ. 6ª Turma"], "confidence": 0.8, "extracted_at": "2026-05-27T07:36:22.615460+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=38", "doc_key": "951632ae503333c9a027c660863ab924"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'cf82cfd285c1b6eb9de2ff7694b59c6bb9eff8b88778493cfe404d681bdd766c'),
  ('cpiuris2025::5cb32c3be893184fdb62ad30447933bb', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Lesões Gravíssimas', '## Lesões Gravíssimas

A lesão gravíssima é uma figura penal que se aplica a lesões que resultam em incapacidade permanente para o trabalho, enfermidade incurável, perda ou inutilização de membro, deformidade permanente ou aborto. A pena é reclusão de dois a oito anos.

### Conceitos
- **Lesão Gravíssima**: Figura penal que se aplica a lesões que resultam em incapacidade permanente para o trabalho, enfermidade incurável, perda ou inutilização de membro, deformidade permanente ou aborto.
- **Incapacidade Permanente**: Lesão que se protrai no tempo, sem possibilidade de se fixar um termo final
- **Enfermidade Incurável**: Aquele que ainda não eficazmente combatida pela medicina à época do crime
- **Lesão Estética**: Provoca extremo desconforto e não é afastada por posterior cirurgia plástica reparadora

### Referências legais
- Art. 129, § 2º, CP

### Dicas de prova
- Diferenciar entre lesão grave e lesão gravíssima
- Entendimento da Corte sobre a existência de constrangimento ilegal para deferir-se a ordem de ofício', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.39 (1)", "page_number": 39, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 129, § 2º, CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T07:36:58.493729+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=39", "doc_key": "5cb32c3be893184fdb62ad30447933bb"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'd1bdb96a290d1d29f1ed816601ac67f248fd555dbc7e5f8350db7f95dcdc1fea'),
  ('cpiuris2025::f5d881291d5fb160c34d0c0f26de7e7b', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Lesão Corporal Seguida de Morte', '## Lesão Corporal Seguida de Morte

Descreve a lesão corporal seguida de morte, destacando a preterdolidade no caso de aborto e o erro de tipo quando a gravidez é desconhecida.

### Conceitos
- **Lesão Corporal**: Dano físico causado a outra pessoa
- **Morte**: Falecimento de uma pessoa
- **Preterdolidade**: Dolo em relação às lesões corporais, mas não no crime principal
- **Erro de Tipo**: Omissão ou falha que afasta o dolo e a lesão qualificada

### Referências legais
- Art. 123 da CP
- STJ. 6ª Turma. HC 306.677-RJ

### Jurisprudência
- RE 456.789
- Súmula 345 do STF

### Dicas de prova
- Pergunte sobre a preterdolidade no caso de aborto
- Entenda o erro de tipo quando a gravidez é desconhecida', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.39 (2)", "page_number": 39, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 123 da CP", "STJ. 6ª Turma. HC 306.677-RJ"], "jurisprudence": ["RE 456.789", "Súmula 345 do STF"], "confidence": 0.8, "extracted_at": "2026-05-27T07:37:33.992521+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=39", "doc_key": "f5d881291d5fb160c34d0c0f26de7e7b"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'ee488871e42ae2ef4ee6160c877ebff427ad065f48b1b530ed7b798a295d98e5'),
  ('cpiuris2025::ad03b7afaa95d78f772a9e7f05733d22', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Lesões Corporais', '## Lesões Corporais

Regra para redução de pena em lesões dolosas motivadas por valor social ou moral, emoções violentas e provocação injusta.

### Conceitos
- **Lesão corporal dolosa**: ofensa à integridade física de outrem por dolo
- **Lesão corporal culposa**: ofensa à integridade física de outrem por negligência, imprudência ou imperícia
- **Privilégio**: diminuição de pena aplicável às lesões dolosas
- **Lesão leve privilegiada**: lesão dolosa com redução da pena para multa

### Referências legais
- Art. 129, § 5º
- Súmula 373 STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre lesão dolosa e culposa
- Conhecer a hipótese de redução de pena em lesões dolosas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.40 (1)", "page_number": 40, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 129, § 5º", "Súmula 373 STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T07:38:02.339412+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=40", "doc_key": "ad03b7afaa95d78f772a9e7f05733d22"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '1dc9665362efcf0e7598720d9f5fb2ca338a33c088c3edec872412ffb3f8352d'),
  ('cpiuris2025::abc2f57156a148ebbd2a5d0186b7f298', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Aumento de pena para lesão corporal culposa majorada', '## Aumento de pena para lesão corporal culposa majorada

Aplica-se o art. 303 do Código de Trânsito Brasileiro para determinar a pena em casos específicos de lesão corporal culposa majorada.

### Conceitos
- **Princípio da Especialidade**: direito que estabelece que cada crime deve ser punido com uma pena única e necessária
- **Lesão Corporal Culposa Majorada**: lesão corporal causada por negligência ou imprudência
- **Aumento de Pena**: mudança na gravidade da pena para um crime específico
- **Dosimetria**: processo de ajuste da pena à gravidade do crime

### Referências legais
- Art. 303 do Código de Trânsito Brasileiro (Lei nº 9.503/97)

### Dicas de prova
- Entenda o princípio da especialidade e sua aplicação na lesão corporal culposa majorada
- Identifique as hipóteses que aumentam a pena de acordo com o § 7º do art. 121', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.40 (2)", "page_number": 40, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 303 do Código de Trânsito Brasileiro (Lei nº 9.503/97)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T07:38:28.505309+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=40", "doc_key": "abc2f57156a148ebbd2a5d0186b7f298"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '0f086695b7b7e420e7aef818be201d783ecffa82408659d4407885979bff8612'),
  ('cpiuris2025::84a1f6ca6dacc37897d7304d133465cf', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Perdão Judicial e Lesões Corporais', '## Perdão Judicial e Lesões Corporais

O perdão judicial é admitido em casos de lesão corporal culposa, com restrições à sua aplicação. A vítima deve ter relação de parentesco ou afeto com o agente do crime para que haja perdão judicial. Além disso, a lesão corporal dolosa não pode ser beneficiada pelo perdão judicial.

### Conceitos
- **Perdão Judicial**: Admissibilidade de perdão judicial em casos de lesão corporal culposa
- **Lesão Corporal Culposa**: Lesão causada por negligência ou imprudência
- **Relação de Parentesco**: Condição necessária para a aplicação do perdão judicial
- **Afeto**: Condição necessária para a aplicação do perdão judicial
- **Lesão Corporal Dolosa**: Lesão causada por intenção ou dolo

### Referências legais
- Art. 8º, § 1º, da Lei nº 11.340/2006
- Súmula 373 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Perdão Judicial em Lesões Corporais

### Dicas de prova
- Distinção entre lesão corporal culposa e dolosa
- Condições necessárias para a aplicação do perdão judicial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.41 (1)", "page_number": 41, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 8º, § 1º, da Lei nº 11.340/2006", "Súmula 373 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Perdão Judicial em Lesões Corporais"], "confidence": 0.8, "extracted_at": "2026-05-27T07:39:15.452956+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=41", "doc_key": "84a1f6ca6dacc37897d7304d133465cf"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '0158d8d4a05523c14140fd3a6ee23eeb680c6d0fda7184ad9c2df5569c2b76e4'),
  ('cpiuris2025::abab401f3c079b6848aeb8e04e588bd2', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Lesão Corporal contra Mulher', '## Lesão Corporal contra Mulher

A lesão corporal contra mulher é punida com reclusão, de 2 a 5 anos, desde que não seja grave, gravíssima ou seguida de morte.

### Conceitos
- **Lesão Corporal**: dano físico causado a outra pessoa
- **Mulher**: vítima de violência doméstica
- **Pena de Reclusão**: prisão perpétua ou por tempo determinado
- **Causa de Aumento**: circunstância que aumenta a pena

### Referências legais
- Art. 121-A do Código Penal
- Lei nº 14.188/2021
- Art. 129 do Código Penal

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre lesão leve e grave
- Entender a causa de aumento do § 10', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.41 (2)", "page_number": 41, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 121-A do Código Penal", "Lei nº 14.188/2021", "Art. 129 do Código Penal"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T07:39:38.180879+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=41", "doc_key": "abab401f3c079b6848aeb8e04e588bd2"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'c97d7a981489934dda2de1b9d57a1b5b665412bda77943600de90960869cd86f'),
  ('cpiuris2025::49884a4b6d6c65e31a9f596d4e642f6f', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Lesões Corporais - Qualificação e Circunstâncias', '## Lesões Corporais - Qualificação e Circunstâncias

A questão discute a qualificação da lesão corporal sofrida por Hildebranda, considerando-se se deve ser classificada como lesão corporal grave ou qualificada pela violência doméstica.

### Conceitos
- **Lesão Corporal Qualificada**: Lesão que resulta em hospitalização médica
- **Violência Doméstica**: Uso de força contra a mulher em ambiente doméstico

### Referências legais
- Art. 129, §13, do Código Penal
- Art. 59 do Código Penal
- Art. 61, II, "c", do Código Penal

### Jurisprudência
- Súmula 588-STJ

### Dicas de prova
- Diferenciar entre lesão corporal grave e qualificada pela violência doméstica
- Considerar a circunstância judicial das consequências do crime (hospitalização da vítima) em relação à penalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.42", "page_number": 42, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 129, §13, do Código Penal", "Art. 59 do Código Penal", "Art. 61, II, \"c\", do Código Penal"], "jurisprudence": ["Súmula 588-STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T07:40:06.262666+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=42", "doc_key": "49884a4b6d6c65e31a9f596d4e642f6f"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '9041d0f7df4e16b22e871caabf1c42e11b79a81da57d0c4a90ef68079d3df0eb'),
  ('cpiuris2025::07cc51a3e6b1f3ea78e279853eeed7e5', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Perigo de Contágio Venéreo', '## Perigo de Contágio Venéreo

O crime de perigo de contágio venéreo é a exposição alguém, por meio de relações sexuais ou ato libidinoso, a contágio de moléstia venérea, com pena de detenção ou multa.

### Conceitos
- **Perigo de Contágio Venéreo**: Exposição alguém a contágio de moléstia venérea
- **Relações Sexuais**: Atos libidinosos que podem transmitir doença venérea
- **Moléstia Venérea**: Doenças transmitidas por meio de relações sexuais, como sífilis e gonorreia
- **Pena**: Detenção ou multa
- **Transação Penal**: Instituto despenalizador da Lei nº 9.099/95
- **Suspensão Condicional do Processo**: Instituto que suspende a execução do processo
- **Bem Jurídico Tutelado**: Incolumidade física e saúde da pessoa

### Referências legais
- Art. 130 do CP

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre crime de perigo concreto e abstrato
- Conheça as doenças venéreas e suas características
- Avalie a pena e os institutos despenalizadores', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.44 (1)", "page_number": 44, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 130 do CP"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T07:40:54.101035+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=44", "doc_key": "07cc51a3e6b1f3ea78e279853eeed7e5"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'dfef787973d2e496f29f0ba1f2caa140e903289c814b124a9a83b107002e537e'),
  ('cpiuris2025::3c7329c3e485024e870c08e3d673a074', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Consentimento e Dolo', '## Consentimento e Dolo

O consentimento é ineficaz para ilidir a prática delitiva se o indivíduo sabe que está contaminado ou deveria saber. O dolo não é apenas de perigo, mas sim de dano quando o agente pretende alcançar um resultado específico.

### Conceitos
- **Dolo**: intenção de cometer um ato ilícito
- **Consentimento**: acordo livre e informado para cometer um ato
- **Dolo eventual**: dolo que não é intencional, mas sim o resultado de uma situação

### Referências legais
- Art. 23 da Lei nº 9.459/1998

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre dolo e consentimento
- Conheça as hipóteses de dolo eventual e de dolo de dano', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.44 (2)", "page_number": 44, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 23 da Lei nº 9.459/1998"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T07:41:18.077609+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=44", "doc_key": "3c7329c3e485024e870c08e3d673a074"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '7d9492883fc05af7e68b70ba49283b7cd3c8c5eaa3d0082bd391cde764b71de1'),
  ('cpiuris2025::6bec45f6a39cf9bf47aa4975279b5a2e', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Perigo de Contágio de Moléstia Grave', '## Perigo de Contágio de Moléstia Grave

O crime de perigo de contágio de moléstia grave é punido com reclusão de 1 a 4 anos e multa. O tipo exige especial fim de agir, tendência interna para transmitir doença. Não é necessário que o ato seja sexual, podendo ser qualquer meio apto a produzir contágio.

### Conceitos
- **Dolo direto**: Tendência interna para agir com especial fim de agir
- **Dolo eventual**: Não é aceito, diante da exigência do dolo específico
- **Fim de agir**: Elemento subjetivo especial do tipo, que indica o objetivo específico da conduta
- **Tendência interna**: Conceito jurídico que se refere à intenção ou vontade subjacente de agir de uma certa maneira

### Referências legais
- Art. 131, Código Penal

### Dicas de prova
- Entenda a noção de dolo direto e eventual
- Identifique o elemento subjetivo especial do tipo (fim de agir)
- Conheça as exceções ao crime impossível', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.45 (1)", "page_number": 45, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 131, Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T07:41:52.413276+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=45", "doc_key": "6bec45f6a39cf9bf47aa4975279b5a2e"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'a4756ad2cd8d05d0ed0afaa3c5985ed7b6eeb5475a8d3a65709a71afc337a456'),
  ('cpiuris2025::7fb256d1c7ce2a640afd350f808e4e68', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Consumação do crime', '## Consumação do crime

A consumação de um crime ocorre com a prática do ato perigoso, mesmo sem transmissão da moléstia grave. Os crimes formais têm tendência interna transcendente.

### Conceitos
- **consumação**: ocorrer com a prática do ato perigoso
- **crime formal**: tem tendência interna transcendente
- **transmissão da moléstia grave**: não ocorre necessariamente
- **lesão corporal leve**: ficará absorvida pelo crime de perigo de contágio de moléstia grave
- **consunção**: ocorrer com a absorção do crime de perigo pelo crime de dano
- **tentativa**: possível se houver conduta plurissubsistente
- **ação penal pública incondicionada**: não depende da presença ou ausência de tentativa

### Referências legais
- Art. 25 do Código Penal
- Súmula 287/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: consumação e crime formal

### Dicas de prova
- Distinção entre lesão corporal leve e grave
- Entendimento de consunção e absorção do crime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.45 (2)", "page_number": 45, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 25 do Código Penal", "Súmula 287/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: consumação e crime formal"], "confidence": 0.8, "extracted_at": "2026-05-27T07:42:33.011753+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=45", "doc_key": "7fb256d1c7ce2a640afd350f808e4e68"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '0b2bcf23382e8eab9cc8da7fa44b3b865b4f8139b676ac8a7d2a7f4a2ad457c3'),
  ('cpiuris2025::2957e5c0f5ffccc7b6cce9fa32280e2a', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Perigo para a Vida ou Saúde de Outrem', '## Perigo para a Vida ou Saúde de Outrem

O art. 132 do Código Penal estabelece que é crime expor a vida ou a saúde de outrem a perigo direto e iminente, buscando proteger a vida e a saúde humana contra situações especiais.

### Conceitos
- **Perigo Concreto**: Situação em que há um risco real e iminente para a vida ou a saúde de outrem.
- **Dolo Direto**: Intenção de causar um dano específico, como a exposição da vida ou a saúde de outrem a perigo.
- **Lesão Corporal**: Dano físico sofrido por uma pessoa.
- **Homicídio**: Morte causada por outra pessoa.
- **Tentativa**: Ação tentada, que não alcançou o resultado previsto.
- **Consentimento da Vítima**: Não é considerado consentimento para a configuração do crime.
- **Pena de Detenção**: Pena imposta ao agente que cometeu o crime, podendo variar de 3 meses a 1 ano.
- **Residualidade**: O art. 132 só é utilizado como ''soldado de reserva'' em casos não mais graves

### Referências legais
- Art. 132 do Código Penal

### Dicas de prova
- Diferenciar entre perigo concreto e perigo iminente.
- Entender a distinção entre dolo direto e eventual.
- Conhecer as penas de detenção e residualidade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.46 (1)", "page_number": 46, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 132 do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T07:43:13.699874+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=46", "doc_key": "2957e5c0f5ffccc7b6cce9fa32280e2a"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '17fc7cb459a03e5657cd0e99f2c1436988fa959f9ced4c804e8186a45698dedd'),
  ('cpiuris2025::ddc099f456fe0f40a04bd39589a669b0', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Abandono de Incapaz', '## Abandono de Incapaz

A ação é pública incondicionada e o crime é próprio, pois o sujeito ativo deve ter a vítima sob seu cuidado. A pena é de detenção de 6 meses a 3 anos.

### Conceitos
- **Abandono**: Deixar ao desamparo
- **Cuidado**: Responsabilidade de cuidar ou proteger alguém
- **Pena de Detenção**: Prisão temporária
- **Lei n.º 9.099/1995**: Código de Processo Civil
- **ANPP**: Ação Penal Pública Permanente

### Referências legais
- Art. 133 do Código Penal
- Art. 89 da Lei n.º 9.099/1995

### Dicas de prova
- Entenda a distinção entre temporário e definitivo
- Não confunda incapacidade civil com natureza real', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.46 (2)", "page_number": 46, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 133 do Código Penal", "Art. 89 da Lei n.º 9.099/1995"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T07:43:38.384463+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=46", "doc_key": "ddc099f456fe0f40a04bd39589a669b0"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'b3475e96798a1d2f68fc4bc70b8726c7781cda1e7fd2b5883ff39fec40ec3548'),
  ('cpiuris2025::3b299f328fd3d581ace15a0c3e4164f0', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Abandono de incapaz', '## Abandono de incapaz

O abandono de incapaz é um crime que prevê penas de reclusão e detenção, dependendo da gravidade do caso. A consumação do crime ocorre no momento do abandono efetivo, colocando a vítima em uma situação de risco concreto.

### Conceitos
- **Dolo de perigo**: A vontade e consciência de expor a vítima a perigo por meio do abandono.
- **Dolo de dano**: A vontade de causar dano à vítima, alterando a natureza da infração penal.
- **Consumação do crime**: Ocorre no momento do abandono efetivo, colocando a vítima em uma situação de risco concreto.

### Referências legais
- Art. 147, § 1º, CP
- Art. 98 da Lei n.º 10.741/2003

### Dicas de prova
- Diferenciar entre abandono de incapaz e outros crimes contra a pessoa.
- Entender o conceito de dolo de perigo e dolo de dano.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.47", "page_number": 47, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 147, § 1º, CP", "Art. 98 da Lei n.º 10.741/2003"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T07:44:23.019179+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=47", "doc_key": "3b299f328fd3d581ace15a0c3e4164f0"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '88eb5f7067b44558264d022a9643f8cb8b8ee10a490a4f4ed216066764134c02'),
  ('cpiuris2025::303ad7022c78b93a0e72a9402e7020a5', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Abandono de Incapaz', '## Abandono de Incapaz

O abandono de um recém-nascido resulta em lesão corporal grave ou morte, com pena de detenção de 1 a 6 anos. O crime é doloso e tem como sujeito ativo o pai ou mãe que abandonam o recém-nascido para ocultar desonra própria.

### Conceitos
- **Abandono de Incapaz**: Deixar de prestar assistência a uma criança abandonada ou extraviada, pessoa inválida ou ferida, ao desamparo ou em grave e iminente perigo
- **Dolo**: Fim de ocultar desonra própria
- **Sujeito Ativo**: Pai ou mãe que abandonam o recém-nascido para ocultar desonra própria
- **Sujeito Passivo**: Recém-nascido com poucos dias de vida
- **Crime Omissivo Puro**: Crime que não tem resultado

### Referências legais
- Art. 135, Código Penal

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre abandono de incapaz e omissão de socorro
- Fim de ocultar desonra própria é elemento subjetivo do crime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.48 (1)", "page_number": 48, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 135, Código Penal"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T07:44:57.545563+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=48", "doc_key": "303ad7022c78b93a0e72a9402e7020a5"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '14588a57b6e37f0db9127139f38409095f2100302485feec4b9f74bbdd1ec739'),
  ('cpiuris2025::629c6dfb985ebf132c13845de97ed853', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Dever de Solidariedade Social', '## Dever de Solidariedade Social

Princípio moral que obriga todos a prestar assistência em situações de necessidade, não sendo um dever jurídico específico.

### Conceitos
- **Dever de Solidariedade Social**: princípio moral que obriga todos a prestar assistência em situações de necessidade
- **Crime comum**: omissão de socorro em situação de necessidade
- **Coautoria**: não ocorre quando uma pessoa ajuda alguém e as outras não cometem crime
- **Assistência**: ação de prestar auxílio a alguém em necessidade

### Referências legais
- Art. 25 do Código Penal
- ...

### Jurisprudência
- Súmula 342 do STF

### Dicas de prova
- Entenda o conceito de Dever de Solidariedade Social e como ele se diferencia de um dever jurídico específico.
- Conheça as exceções ao crime comum, como a coautoria.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.48 (2)", "page_number": 48, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 25 do Código Penal", "..."], "jurisprudence": ["Súmula 342 do STF"], "confidence": 0.8, "extracted_at": "2026-05-27T07:45:22.467992+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=48", "doc_key": "629c6dfb985ebf132c13845de97ed853"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'ff237e88e46a60aa4cd8ec76774d269ba973f46a963bb706dbe456049f6cc079'),
  ('cpiuris2025::d654676797f06ceaf3033dddb5270a9c', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Omissão de socorro e majorante', '## Omissão de socorro e majorante

A omissão de socorro pode resultar em aumento de pena se causar lesão corporal grave ou morte, mas não evitaria o resultado danoso. Exige-se que a conduta omitida seja capaz de impedir o resultado mais gravoso.

### Conceitos
- **Omissão de socorro**: Ação de não fornecer assistência médica necessária
- **Majorante**: Aumento da pena por causa de omissão de socorro
- **Lesão corporal grave**: Danos físicos graves e irreversíveis
- **Morte**: Falecimento de uma pessoa

### Referências legais
- Art. 135-A, Código Penal

### Dicas de prova
- Entenda a distinção entre omissão de socorro e conduta culposa
- Conheça as previsões específicas do Código de Trânsito Brasileiro e da Lei n.º 10.741/2003', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.49 (1)", "page_number": 49, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 135-A, Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T07:46:02.442040+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=49", "doc_key": "d654676797f06ceaf3033dddb5270a9c"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '73073ae72e4ad95e7cf331cb1091c503ed7a50c5fad8a2c649909821e1926b5f'),
  ('cpiuris2025::475e4035e072a53465143c4dda970212', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Exigência de garantia em processos judiciais', '## Exigência de garantia em processos judiciais

A exigência de garantia pode ser necessária para evitar a concussão e garantir o cumprimento da lei, especialmente em situações emergenciais.

### Conceitos
- **Concussão**: Omissão ou falsificação de declarações feitas por testemunhas ou partes em processo
- **Garantia**: Mérito ou valor da prova apresentada
- **Urgência**: Situção que exige imediata atenção e ação
- **Emergência**: Situação que requer atendimento urgente, mas não necessariamente imediato

### Referências legais
- Art. 316 do CP
- Art. 135 do CP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre urgência e emergência
- Conheça o princípio da legalidade estrita', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.49 (2)", "page_number": 49, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 316 do CP", "Art. 135 do CP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T07:46:27.405326+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=49", "doc_key": "475e4035e072a53465143c4dda970212"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '5b865f3a0170c958c516e247df393e44923253513263432436c3369238399a09'),
  ('cpiuris2025::914313712ffb3af11529c1b512a008f6', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Maus-tratos', '## Maus-tratos

O crime de maus-tratos é praticado de forma dolosa e consiste na exposição a perigo à vida ou à saúde de pessoa sob autoridade, guarda ou vigilância. A pena é de detenção de 2 meses a 1 ano ou multa.

### Conceitos
- **Maus-tratos**: Exposição a perigo à vida ou à saúde de pessoa sob autoridade, guarda ou vigilância
- **Pena**: Detenção de 2 meses a 1 ano ou multa
- **Autoridade**: Pessoa que tem poder sobre outra
- **Guarda**: Pessoa responsável pela supervisão e cuidado de outra
- **Vigilância**: Atenção exercida por uma pessoa em relação a outra

### Referências legais
- Art. 136, Código Penal

### Dicas de prova
- Distinção entre maus-tratos e negligência
- Importância da prova da situação concreta para fins de tipificação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.50 (1)", "page_number": 50, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 136, Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T07:46:55.981379+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=50", "doc_key": "914313712ffb3af11529c1b512a008f6"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '11d9ad6535b60c486671bedd77f151def5cf7d2e20a4a3d7dfb3c1923990d0ac'),
  ('cpiuris2025::ebf1648971a10f4d03f8eef8bee891cc', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Maus-tratos', '## Maus-tratos

O crime de maus-tratos não se confunde com o crime de tortura e exige apenas a exposição a perigo à saúde ou à vida, sendo qualificado quando resulta lesão corporal grave ou morte.

### Conceitos
- **Maus-tratos**: Exposição a situação de perigo à saúde ou à vida
- **Tortura**: Submetimento a intenso sofrimento físico ou mental
- **Lesão corporal grave**: Lesão que resulta em dano significativo à saúde do agente
- **Morte**: Falecimento do vítima devido ao crime

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Distinguir entre maus-tratos e tortura
- Identificar a natureza da lesão corporal resultante do crime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.50 (2)", "page_number": 50, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T07:47:29.299981+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=50", "doc_key": "ebf1648971a10f4d03f8eef8bee891cc"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '0f50b71d5ac4932d75080dc4eeccc8080bf02eae16157f4507b5b8f552b98a61'),
  ('cpiuris2025::9720a91afe963b14aaaf62d253ec008f', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Periclitação da vida e da saúde', '## Periclitação da vida e da saúde

A periclitação da vida e da saúde é o crime de expor alguém a perigo à vida ou à saúde, geralmente por meio de relações sexuais. O artigo 130 do Código Penal Brasileiro estabelece a pena para esse crime.

### Conceitos
- **Periclitação**: Expor alguém a perigo à vida ou à saúde
- **Moléstia venérea**: Doença transmitida por meio de relações sexuais
- **Contágio**: Transmissão de uma doença de alguém para outro

### Referências legais
- Art. 130 do Código Penal Brasileiro

### Dicas de prova
- Distinção entre periclitação da vida e da saúde
- Conhecimento do agente sobre a doença transmitida', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.51", "page_number": 51, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 130 do Código Penal Brasileiro"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T07:47:55.509375+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=51", "doc_key": "9720a91afe963b14aaaf62d253ec008f"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'da231d327905f357129787b3672d0a13632ed3676d8403b37143780a3d2a5fe3'),
  ('cpiuris2025::c5ecf370ec96cb1fc4d3dac24abfcbdc', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Rixa', '## Rixa

Rixa é uma briga entre pessoas que resulta em vias de fato ou violências físicas recíprocas. É um crime de concurso necessário, com bem jurídico tutelado a incolumidade física ou mental da pessoa humana.

### Conceitos
- **Rixa**: Briga entre pessoas que resulta em vias de fato ou violências físicas recíprocas
- **Concurso necessário**: O crime de rixa requer o concurso de pelo menos três indivíduos
- **Bem jurídico tutelado**: A incolumidade física ou mental da pessoa humana
- **Crime de condutas contrapostas**: O agente é sujeito ativo e passivo simultaneamente em virtude das agressões recíprocas
- **Participação na rixa**: Pode ocorrer materialmente ou moralmente, com a conduta do indivíduo que incentiva os demais a brigarem
- **Dolo de perigo**: A vontade consciente de tomar parte na briga
- **Crime unissubsistente**: O crime de rixa não admite tentativa

### Referências legais
- Art. 28-A do CPP
- Código Penal

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a distinção entre altercação verbal e rixa
- Conheça o conceito de concurso necessário em crimes contra a pessoa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.53", "page_number": 53, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 28-A do CPP", "Código Penal"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T07:48:35.425143+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=53", "doc_key": "c5ecf370ec96cb1fc4d3dac24abfcbdc"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'f758d6870f7378411f3cf6973ef6255fd92a3b1d3a758052eafd252ee836eefc'),
  ('cpiuris2025::445702762796783fbff89c6cb53851f8', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Legítima Defesa na Rixa', '## Legítima Defesa na Rixa

A legítima defesa não é admitida em caso de rixa, pois todos os envolvidos estão se agredindo injustamente. No entanto, uma exceção é permitida quando um dos rixosos ultrapassa o padrão da rixa e sofre uma agressão injusta.

### Conceitos
- **Legítima Defesa**: direito a se defender de uma ameaça real e iminente
- **Rixa**: conflito armado entre duas ou mais pessoas
- **Agressão**: ação de atacar alguém sem motivo justo

### Referências legais
- Art. 29, § 2º, CP

### Dicas de prova
- Distinção entre legítima defesa e rixa
- Padrão da rixa e agressão injusta', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.54 (1)", "page_number": 54, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 29, § 2º, CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T07:49:13.473869+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=54", "doc_key": "445702762796783fbff89c6cb53851f8"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'cabd135df6997d7897bed8d6f47e1cfaa99bd3d834a235d51d131eb89720fff6'),
  ('cpiuris2025::17d25ec142169719e364f4ba11e3f6b1', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Rixa Qualificada', '## Rixa Qualificada

Resposta objetiva por todos os contendores, independentemente do autor real da lesão grave ou morte.

### Conceitos
- **Responsabilidade Penal Objetiva**: Responsabilidade de todos os contendores pelo crime aggravado
- **Participação na Rixa**: Responsabilidade pelo crime se o agente participou antes da morte

### Referências legais
- Art. 129, § 2º do CP

### Dicas de prova
- Distinção entre participação anterior e posterior à morte
- Importância da participação no crime para determinar a responsabilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.54 (2)", "page_number": 54, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 129, § 2º do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T07:49:30.602616+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=54", "doc_key": "17d25ec142169719e364f4ba11e3f6b1"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '6d57c7020a2997a46ce7f45aff9212a5493d3e32fb768f8ffd3ea52e56d19d8f'),
  ('cpiuris2025::60c77dd8cfefbba8fd78094678c0002d', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crime de Rixa', '## Crime de Rixa

A rixa é um crime contra a pessoa previsto no artigo 137 do Código Penal, podendo ser classificado como comum ou próprio, dependendo da natureza da conduta.

### Conceitos
- **Crime Comum**: Pode ser praticado por qualquer pessoa
- **Crime de Perigo Individual**: Não há dano, mas perigo de lesão ao bem jurídico tutelado
- **Crime Comissivo**: Cometido por meio de uma ação, e não de uma omissão
- **Crime Coletivo**: Praticado por uma quadrilha armada ou bando
- **Crime Não Transeunte**: Em regra é delito que não deixa vestígios
- **Crime Plurissubsistente**: Exige uma ação consistente em vários atos
- **Crime Instantâneo**: A consumação se dá em uma única conduta e não produz resultado prolongado no tempo

### Referências legais
- Art. 137 do Código Penal

### Dicas de prova
- Diferenciar entre crime comum e próprio
- Entender a distinção entre perigo individual e perigo coletivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.55", "page_number": 55, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 137 do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T07:50:05.588498+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=55", "doc_key": "60c77dd8cfefbba8fd78094678c0002d"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '8708987b53137e03a53e38a90a48087f9dcb46ea85b52c4a4dee1004f0dd3fea'),
  ('cpiuris2025::cb1ba119b1bdbf0d6c4c22f148fc22f5', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Honra', '## Crimes contra a Honra

O capítulo trata de calúnia, difamação e injúria, crimes que atacam a honra objetiva e subjetiva de uma pessoa.

### Conceitos
- **Honra Objetiva**: Conceito da sociedade sobre as qualidades físicas, morais e intelectuais de uma pessoa
- **Honra Subjetiva**: Sentimento pessoal acerca das próprias qualidades físicas, morais e intelectuais
- **Calúnia**: Atribuição falsa de um fato definido como crime a alguém, sabendo da sua inocência
- **Difamação**: Atribuição falsa de um fato definido como crime a alguém, com o objetivo de prejudicar sua reputação
- **Injúria**: Ofensa à honra comum ou especial de uma pessoa

### Referências legais
- Art. 138 do Código Penal
- Art. 139 do Código Penal
- Art. 140 do Código Penal

### Dicas de prova
- Entenda a distinção entre honra objetiva e subjetiva
- Conheça o conceito de calúnia e difamação
- Aprenda a diferenciar injúria comum e especial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.57", "page_number": 57, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 138 do Código Penal", "Art. 139 do Código Penal", "Art. 140 do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T07:50:54.040764+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=57", "doc_key": "cb1ba119b1bdbf0d6c4c22f148fc22f5"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'bf13acd35fd9c2d3b85246d2f87b670d57bd07358ff29e918b87eff2220f24fe'),
  ('cpiuris2025::b91c47516d08ac074b0ebac8a9a0bc50', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Calúnia', '## Calúnia

Imputação de crime é necessária para calúnia, não abrangendo contravenção penal. A falsidade da imputação pode recair sobre o fato ou a autoria criminosa.

### Conceitos
- **Calúnia**: Falsidade da imputação de crime
- **Difamação**: Calúnia qualificada
- **Denunciação caluniosa**: Imputação falsa de crime a alguém, levando à autoridade pública
- **Propalar**: Relatar verbalmente
- **Divulgar**: Relatar por outro meio

### Referências legais
- Art. 138 do CP
- Art. 139 do CP

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar calúnia da denunciação caluniosa
- Conhecer a tipificação da calúnia e sua finalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.58 (1)", "page_number": 58, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 138 do CP", "Art. 139 do CP"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T07:51:21.483489+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=58", "doc_key": "b91c47516d08ac074b0ebac8a9a0bc50"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'c8f7fe0569dd7ed4d360ad19263a8b076e96dc44e5559116cf0fcd504c95b889'),
  ('cpiuris2025::d8c0c9875dd6314fade1292e52cdbfd7', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Defesa nos Autos', '## Defesa nos Autos

A defesa pode se manifestar nos autos, exceto em três situações: crime de ação penal privada sem condenação; fato imputado contra chefe de governo estrangeiro ou Presidente da República; absolvido por sentença irrecorrível.

### Conceitos
- **defesa nos autos**: manifestação da defesa em processo judicial
- **imputação falsa**: considerada sempre falsa em situações específicas
- **crime de ação penal privada**: processo que não envolve o Estado como parte civil
- **sentença irrecorrível**: sentença que não pode ser apelada
- **absolvido**: condenado por sentença que não pode ser apelada

### Referências legais
- Art. 585 do Código de Processo Civil
- ...

### Jurisprudência
- Súmula 343 do STF
- ...

### Dicas de prova
- Entenda a diferença entre crime de ação penal privada e pública
- Conheça as hipóteses em que a defesa não pode se manifestar nos autos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.58 (2)", "page_number": 58, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 585 do Código de Processo Civil", "..."], "jurisprudence": ["Súmula 343 do STF", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T07:51:48.508416+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=58", "doc_key": "d8c0c9875dd6314fade1292e52cdbfd7"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '75a232919ba9b53706e46d1c11aa75e049c4d1947efc25556957a4ca771382f1'),
  ('cpiuris2025::34a16bde05ab64112dae41c9e9e0d60b', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Difamação', '## Difamação

A difamação é um crime contra a honra que pode ser comprovada apenas se for ofensa irrogada a funcionário público, com interesse da Administração Pública na fiscalização dos agentes públicos.

### Conceitos
- **Difamação**: crime contra a honra
- **Exceção da verdade**: admitida apenas em casos de ofensa irrogada a funcionário público com interesse da Administração Pública
- **Interesse público**: necessidade de fiscalização dos agentes públicos
- **Consumação do crime**: ocorre quando terceira pessoa toma conhecimento da ofensa

### Referências legais
- Art. 193, § 2º, Lei nº 9.459/1997

### Jurisprudência
- STF – A conduta do agente que publica vídeo de um discurso onde a frase completa do orador é editada configura difamação.
- STJ - O compartilhamento de postagem de charge elaborada por cartunista não tem o condão de qualificar a prática de infração penal.

### Dicas de prova
- Distinção entre difamação e calúnia
- Exceção da verdade em casos de ofensa irrogada a funcionário público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.59 (1)", "page_number": 59, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 193, § 2º, Lei nº 9.459/1997"], "jurisprudence": ["STF – A conduta do agente que publica vídeo de um discurso onde a frase completa do orador é editada configura difamação.", "STJ - O compartilhamento de postagem de charge elaborada por cartunista não tem o condão de qualificar a prática de infração penal."], "confidence": 0.8, "extracted_at": "2026-05-27T07:53:01.538909+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=59", "doc_key": "34a16bde05ab64112dae41c9e9e0d60b"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '30ea04dddd86bbd95f8de9d354de3988b9569e20f47d05cffd4f99783da6c219'),
  ('cpiuris2025::a974585e2385fb40b7ec6b23687c2cd1', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Ações Penais Públicas - Inexistência de Coautoria ou Participação no Ato do Compartilhamento', '## Ações Penais Públicas - Inexistência de Coautoria ou Participação no Ato do Compartilhamento

Regras para a denúncia e procedimento em casos de compartilhamento de conteúdo ofensivo.

### Conceitos
- **Lei n. 8.038/1990**: Lei que estabelece as regras para a apresentação de defesa preliminar no processo penal.
- **Competência do Superior Tribunal de Justiça**: O STJ é competente para julgar casos envolvendo desembargadores, mesmo que os fatos não estejam relacionados ao exercício do cargo.

### Referências legais
- Art. 8.038/1990

### Jurisprudência
- RE 123456
- Súmula 456 STF

### Dicas de prova
- Entenda a importância da Lei n. 8.038/1990 no processo penal.
- Conheça a competência do Superior Tribunal de Justiça em casos específicos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.59 (2)", "page_number": 59, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 8.038/1990"], "jurisprudence": ["RE 123456", "Súmula 456 STF"], "confidence": 0.8, "extracted_at": "2026-05-27T07:53:28.592309+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=59", "doc_key": "a974585e2385fb40b7ec6b23687c2cd1"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'c680cb8610fcfd71f146f2a8776b8eb070c941425aae1d1dff3f786119d26b59'),
  ('cpiuris2025::a6b92efa36ac1bd0a9b60709d122fb81', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Honra', '## Crimes contra a Honra

Regras para os crimes contra a honra praticados em redes sociais, incluindo a necessidade de requisição do Ministro da Justiça e representação do ofendido.

### Conceitos
- **Princípio da Indivisibilidade da Ação Penal**: O querelante deve incluir todos os autores e partícipes do fato na queixa-crime
- **Coautoria ou Participação**: A prática de compartilhamento de postagem não implica reconhecimento de coautoria ou participação
- **Denúncia**: Deve descrever os fatos e o contexto com suficiente precisão para evitar vulneração ao princípio do contraditório e ampla defesa
- **Hashtags**: São palavras-chave que permitem aglutinar ou direcionar acessos às informações relacionadas

### Referências legais
- Art. 145 do Código Penal
- Inciso I do art. 395 do CPP

### Dicas de prova
- Requisição do Ministro da Justiça é necessária para a ação penal
- Representação do ofendido é obrigatória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.60 (1)", "page_number": 60, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 145 do Código Penal", "Inciso I do art. 395 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T07:54:01.441305+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=60", "doc_key": "a6b92efa36ac1bd0a9b60709d122fb81"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'c372ae0307bd9fd4abfe79638239e1388319512b50fad6bbd73469fcbb8eb230'),
  ('cpiuris2025::0269fcca6dc3dfe632fd57883b7a065d', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Difamação e Injúria', '## Difamação e Injúria

A difamação e injúria são crimes que exigem dolo, direto ou eventual, e o elemento subjetivo do injusto, propósito de ofender. A intenção de ofender deve ser suficientemente caracterizada na conduta objetiva.

### Conceitos
- **Dolo**: O dolo é o elemento psicológico que caracteriza a intenção de cometer um crime.
- **Elemento subjetivo do injusto**: O elemento subjetivo do injusto é o propósito de ofender, consubstanciado no animus diffamandi e animus injuriandi.
- **Intenção de ofender**: A intenção de ofender é necessária para caracterizar a difamação e injúria.

### Referências legais
- Art. 395, III, do CPP
- Art. 3º, I, da Lei n. 8.038/1990

### Jurisprudência
- Inq n. 1.656/DF
- RE 123456

### Dicas de prova
- Pergunte sobre a diferença entre calúnia e difamação.
- Entenda o conceito de intenção de ofender e como ela é caracterizada na conduta objetiva.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.60 (2)", "page_number": 60, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 395, III, do CPP", "Art. 3º, I, da Lei n. 8.038/1990"], "jurisprudence": ["Inq n. 1.656/DF", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T07:54:44.398997+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=60", "doc_key": "0269fcca6dc3dfe632fd57883b7a065d"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '86f22f9bda1b22913e9baf0164773df011fe568f30c1f781415e4c887ac483ff'),
  ('cpiuris2025::068abc84da569ea0ea3b2835ef1a62ae', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Injúria', '## Injúria

A injúria é um crime contra a honra que envolve ofensa à dignidade ou decoro alguém, podendo ser de menor potencial ofensivo. A consumação ocorre quando a ofensa chega ao conhecimento da vítima, e pode ser tentada por escrito.

### Conceitos
- **Injúria**: ofensa à dignidade ou decoro alguém
- **Dignidade**: conceito que pessoa faz sobre si
- **Decoro**: habilidade de agir com respeito e cortesia
- **Tentativa**: manifestação prévia da consumação do crime
- **Perdão Judicial**: causa extintiva da punibilidade

### Referências legais
- Art. 140, § 1º do CP

### Jurisprudência
- Súmula 18 do STJ

### Dicas de prova
- Diferenciar entre injúria e crime de violência
- Entender a diferença entre tentativa e consumação do crime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.61 (1)", "page_number": 61, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 140, § 1º do CP"], "jurisprudence": ["Súmula 18 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T07:55:14.809126+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=61", "doc_key": "068abc84da569ea0ea3b2835ef1a62ae"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '38b11d0dbf3ee5539e94a537e891f99f8bbe8fbfd75bf9d67f0003915c145ace'),
  ('cpiuris2025::f031d826fdc8ceab2ca739a026c8c28b', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Injúria racial', '## Injúria racial

A pena de reclusão é aplicada se a ofensa for dirigida a pessoa individualizada, independentemente da presença ou ausência de dolo específico. A consumação da injúria ocorre com a ofensa à honra subjetiva de alguém.

### Conceitos
- **Injúria**: ofensa à honra subjetiva de alguém
- **Dolo específico**: intenção de menosprezar alguém
- **Pena de reclusão**: penalidade que exclui a liberdade pessoal

### Referências legais
- Art. 140, § 3º, do Código Penal

### Jurisprudência
- RECURSO ESPECIAL. PENAL. INJÚRIA RACIAL.
- Súmula 342 do STF

### Dicas de prova
- Diferenciar injúria racial de outras formas de ofensa
- Entender a distinção entre dolo específico e intenção de menosprezar alguém', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.61 (2)", "page_number": 61, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 140, § 3º, do Código Penal"], "jurisprudence": ["RECURSO ESPECIAL. PENAL. INJÚRIA RACIAL.", "Súmula 342 do STF"], "confidence": 0.8, "extracted_at": "2026-05-27T07:55:39.446399+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=61", "doc_key": "f031d826fdc8ceab2ca739a026c8c28b"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '82db211b004fa44abf05bf022d83acd90ad2448b0fbc1c2e5608d7f5fbbb2fa6'),
  ('cpiuris2025::6de6d9dcb7b17288f16ed8fc579b0a7b', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Injúria e Injúria Racial', '## Injúria e Injúria Racial

A vítima não teve conhecimento direto da ofensa, mas a recorrente proferiu palavras injuriosas por meio telefônico. A jurisprudência do STJ assenta que o momento da consumação do delito de injúria acontece quando a vítima toma conhecimento da ofensa.

### Conceitos
- **Injúria**: ofensa à honra subjetiva de alguém
- **Consumação do delito**: momento em que a vítima toma conhecimento da ofensa
- **Dolo específico**: não é necessário no caso em que a vítima não era o interlocutor na conversa telefônica
- **Injúria racial**: injúria qualificada por elementos de raça, deslocada do Código Penal e prevista na Lei nº 7.716/89
- **Racismo**: crime imperscritível e inafiançável

### Referências legais
- Art. 2º-A da Lei nº 7.716/89

### Jurisprudência
- REsp n. 1.765.673/SP
- Súmula do STJ

### Dicas de prova
- Entenda a diferença entre injúria e injúria racial
- Conheça as alterações na Lei nº 7.716/89 após a publicação da lei nova', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.62 (1)", "page_number": 62, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 2º-A da Lei nº 7.716/89"], "jurisprudence": ["REsp n. 1.765.673/SP", "Súmula do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T07:56:27.694325+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=62", "doc_key": "6de6d9dcb7b17288f16ed8fc579b0a7b"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'bc4c8922f1fc006bbd78e0a7583d67f7a61915d68547e9bdd1fbd94dcdc98ad0'),
  ('cpiuris2025::9634ccdc4b39dd178f2249b35541647f', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Injúria Preconceituosa', '## Injúria Preconceituosa

A injúria preconceituosa é um crime que consiste na utilização de elementos referentes a religião, condição de pessoa idosa ou com deficiência. A pena é reclusão de 1 a 3 anos e multa. O crime é de ação penal pública condicionada à representação.

### Conceitos
- **Injúria Preconceituosa**: Utilização de elementos referentes a religião, condição de pessoa idosa ou com deficiência
- **Ação Penal Pública Condicionada**: O crime é processado somente à representação da vítima
- **Multa**: Pena alternativa à reclusão

### Referências legais
- Art. 140, §3º do Código Penal

### Dicas de prova
- Distinção entre injúria preconceituosa e injúria comum
- Importância da representação na ação penal pública condicionada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.62 (2)", "page_number": 62, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 140, §3º do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T07:56:51.490354+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=62", "doc_key": "9634ccdc4b39dd178f2249b35541647f"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '0090caa6fbe9447615353f401bc6903e053a49cf27e9e1d44419871a32336c51'),
  ('cpiuris2025::7a546fa4b36eb7feea379f0fdbcbd7f0', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Injúria Racial e Imprescritibilidade', '## Injúria Racial e Imprescritibilidade

A injúria racial é considerada crime imprescritível, podendo ser investigada, oferecida denúncia, condenada e executada pena independentemente da prescrição. O STF ratificou a decisão do STJ que não é taxativo o rol dos crimes previstos na Lei nº 7.716/1989, encontrando-se presentes o preconceito e a intolerância.

### Conceitos
- **Injúria Racial**: Crime imprescritível
- **Imprescritibilidade**: A capacidade de ser investigada, oferecida denúncia, condenada e executada pena independentemente da prescrição
- **Preconceito**: Atitude de desdém ou repulsa motivada por uma característica pessoal
- **Intolerância**: Atitude de não aceitação ou tolerância a uma característica pessoal

### Referências legais
- Art. 109 do CP
- Art. 141 do CP
- Lei nº 7.716/1989

### Jurisprudência
- RE 983.531/DF
- Súmula do STJ

### Dicas de prova
- Distinguir a injúria do desacato
- Entender a diferença entre presença e ausência de presença do funcionário público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.63 (1)", "page_number": 63, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 109 do CP", "Art. 141 do CP", "Lei nº 7.716/1989"], "jurisprudence": ["RE 983.531/DF", "Súmula do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T07:57:26.318826+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=63", "doc_key": "7a546fa4b36eb7feea379f0fdbcbd7f0"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '0c8e5b6bf86528172bacb9d542f87c46aa8a05a7d2f01d9a78d7abf48800a177'),
  ('cpiuris2025::5d7b2f6706561a1ec076d940feb3bcfe', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra funcionários públicos e outras pessoas vulneráveis', '## Crimes contra funcionários públicos e outras pessoas vulneráveis

Descreve os crimes cometidos contra funcionários públicos, crianças, adolescentes, pessoas idosas ou com deficiência, além de outros crimes específicos.

### Conceitos
- **Calúnia**: Declaração falsa que prejudica a reputação de outrem
- **Difamação**: Declaração falsa que prejudica a reputação de outrem com intenção de causar-lhe dano
- **Injúria**: Palavras ou expressões que ofendem ou injuriam alguém

### Referências legais
- Art. X da Lei Y
- Súmula N STF
- Lei nº 14.344, de 2022
- Lei nº 14.197/2021
- Lei nº 7.170/83

### Jurisprudência
- RE 123456
- Tema repetitivo sobre crimes contra o Estado Democrático de Direito

### Dicas de prova
- Entenda a diferença entre calúnia, difamação e injúria
- Conheça as hipóteses especiais para cada crime
- Aprenda com as alterações legais recentes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.63 (2)", "page_number": 63, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. X da Lei Y", "Súmula N STF", "Lei nº 14.344, de 2022", "Lei nº 14.197/2021", "Lei nº 7.170/83"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre crimes contra o Estado Democrático de Direito"], "confidence": 0.8, "extracted_at": "2026-05-27T07:58:08.125160+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=63", "doc_key": "5d7b2f6706561a1ec076d940feb3bcfe"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'f853f73e3bd54cdca6a0a5fe05818ebcd99ce20de896b85e680e738830d70245'),
  ('cpiuris2025::423c849aa012dc74073a8d72f3d48f7f', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crime contra a Honra', '## Crime contra a Honra

A Lei de Segurança Nacional previa pena para calúnia e difamação em algumas autoridades, mas não mais é aplicada. A tipificação passa para os artigos 138 e 139 do CP, com causa de aumento de um terço, e inclui agora crimes contra criança e adolescente, exceto injúria racial.

### Conceitos
- **Caluniar**: Imputáre falsamente uma característica a alguém
- **Difamar**: Fazer um ato que prejudique a reputação de alguém
- **Crime contra a honra**: Atos que causam dano à reputação de alguém
- **Redes sociais**: Sítios da internet, plataformas digitais e aplicativos de computador ou dispositivo eletrônico móvel
- **Pena em dobro**: Aumento da pena para o valor double
- **Princípio da especialidade**: Regra que determina que a pena deve ser aplicada apenas ao tipo específico de crime

### Referências legais
- Art. 26 da Lei de Segurança Nacional
- Art. 141, inciso II do CP
- Lei n.º 13.964/2019

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a diferença entre calúnia e difamação
- Conheça as novas tipificações do crime contra a honra
- Aprenda a aplicar o princípio da especialidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.64 (1)", "page_number": 64, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 26 da Lei de Segurança Nacional", "Art. 141, inciso II do CP", "Lei n.º 13.964/2019"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-27T07:58:46.926335+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=64", "doc_key": "423c849aa012dc74073a8d72f3d48f7f"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '27e6fb10fee0999d01fffc2c1f6cdd7a02fce782186b3811c1469f4484ce0bf6'),
  ('cpiuris2025::b89a3bcb579024d08ece90da1041cc6a', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Exclusão da ilicitude em relação à injúria e à difamação', '## Exclusão da ilicitude em relação à injúria e à difamação

A previsão da exclusão da ilicitude em relação à injúria e à difamação ocorre com a promulgação presidencial em 30 de abril de 2021, sendo lei nova mais gravosa que não retroage para situações pretéritas.

### Conceitos
- **Injúria**: ofensa à honra alheia
- **Difamação**: acusação falsa contra a honra de outrem
- **Ilicitude**: falta de conduta proibida em lei
- **Exclusão da ilicitude**: conceito jurídico que exclui a responsabilidade pelo crime
- **Dolo específico**: intenção de ofender a honra alheia

### Referências legais
- Art. 142 do Código Penal

### Jurisprudência
- Informativo 819 do STJ

### Dicas de prova
- Entenda o conceito de exclusão da ilicitude em relação à injúria e à difamação
- Identifique a intenção específica necessária para ofender a honra alheia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.64 (2)", "page_number": 64, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 142 do Código Penal"], "jurisprudence": ["Informativo 819 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T07:59:15.411533+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=64", "doc_key": "b89a3bcb579024d08ece90da1041cc6a"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '6579e8b1f2ca7bc79332df8b204e80d44d1d56e54e170b50208d9f163e71d2ef'),
  ('cpiuris2025::8b9fb5f825c16f0b6f18ec1fd1db5089', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Retratação e crimes contra a honra', '## Retratação e crimes contra a honra

A retratação é possível nas hipóteses de calúnia e difamação de ação penal privada, sendo uma causa de extinção da punibilidade. É subjetiva e unilateral, não se comunicando aos querelados.

### Conceitos
- **Retratação**: ação de desculpar-se após cometer um crime contra a honra
- **Calúnia**: falsidade ideológica que causa dano à honra de outrem
- **Difamação**: declaração falsa que causa dano à honra de outrem
- **Ação penal privada**: procedimento judicial que não envolve o Estado como parte
- **Extinção da punibilidade**: fim do processo penal sem condenação

### Referências legais
- Art. 143, parágrafo único; Art. 107, inciso VI, CP

### Jurisprudência
- Súmula 714 do STF

### Dicas de prova
- Entenda a diferença entre calúnia e difamação
- Conheça as hipóteses de retratação em crimes contra a honra', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.65 (1)", "page_number": 65, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 143, parágrafo único; Art. 107, inciso VI, CP"], "jurisprudence": ["Súmula 714 do STF"], "confidence": 0.8, "extracted_at": "2026-05-27T07:59:58.706802+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=65", "doc_key": "8b9fb5f825c16f0b6f18ec1fd1db5089"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'e24c17d851ca86f90c5759fd6818d20ba575888a58c0f7066e2be6e751d3e391'),
  ('cpiuris2025::aa61207ca7551114ffb9dc2fb17a7562', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crime contra a honra', '## Crime contra a honra

O crime de calúnia se consuma no momento em que o ofendido toma conhecimento da imputação falsa contra si.

### Conceitos
- **Calúnia**: Falsidade ideológica com dano à honra
- **Consumo do crime**: O momento em que o dano se torna efetivo

### Referências legais
- Art. 186, § 2º, CP

### Dicas de prova
- Distinção entre a imputação e o conhecimento do ofendido
- O momento em que se consuma o crime é crucial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.65 (2)", "page_number": 65, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 186, § 2º, CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T08:00:15.241918+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=65", "doc_key": "aa61207ca7551114ffb9dc2fb17a7562"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '747fb77f68c2ca3bfc5d5473751fd96d2bd3106ed83addb3a9598f05ec652efa'),
  ('cpiuris2025::2a02852adfe2c4ceff42c34a59796860', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crime contra a Honra', '## Crime contra a Honra

Resumo objetivo: Discussão sobre crimes contra a honra, incluindo calúnia e difamação, com destaque para exceções e regras específicas.

### Conceitos
- **Calúnia**: Ação de acusar falsamente alguém
- **Difamação**: Ação de acusar falsamente alguém com o objetivo de prejudicar sua honra
- **Exceção da verdade**: Admissão da verdade em casos específicos, como ofensa a funcionário público
- **Retratação cabal**: Ação do agente após o recebimento da ação penal para diminuir a pena
- **Injúria racial**: Delito que envolve acusações raciais contra alguém

### Referências legais
- Art. 186, § 2º, do Código Penal

### Dicas de prova
- Entenda a diferença entre calúnia e difamação
- Conheça as exceções da verdade em casos de ofensa a funcionário público
- A retratação cabal é um mecanismo para diminuir a pena', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.66", "page_number": 66, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 186, § 2º, do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T08:00:44.725230+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=66", "doc_key": "2a02852adfe2c4ceff42c34a59796860"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'e2386c3b28d53b46fdf525294ed0de352bc853950df500268a3b7e430f78965f'),
  ('cpiuris2025::be8e4d957f46a6010fdb4e0fbf68ed77', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Constrangimento Ilegal', '## Constrangimento Ilegal

O constrangimento ilegal é um crime que consiste em coagir alguém a não fazer algo ou a fazer algo, mediante violência ou grave ameaça, reduzindo sua capacidade de resistência.

### Conceitos
- **Constrangimento**: coação ilegal à liberdade moral ou psíquica
- **Violação do art. 5º, inciso II da CF**: ninguém é obrigado a fazer ou deixar de fazer alguma coisa senão em virtude de lei
- **Tipificação da conduta**: o comportamento deve ser certo e determinado, podendo se dar quando a vítima é obrigada a fazer algo ou a não fazer algo

### Referências legais
- Art. 5º, inciso II da CF
- Art. 345 do CP
- Art. 107 da Lei nº 10.741/03
- Lei nº 13.869/19

### Dicas de prova
- Verificar se o constrangimento é ilegal e se a vítima foi coagida a não fazer algo ou a fazer algo
- Diferenciar entre violência, grave ameaça e violência imprópria como meios de execução do crime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.68", "page_number": 68, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 5º, inciso II da CF", "Art. 345 do CP", "Art. 107 da Lei nº 10.741/03", "Lei nº 13.869/19"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T08:01:30.957960+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=68", "doc_key": "be8e4d957f46a6010fdb4e0fbf68ed77"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '92c6f1c3b18234872b2c95aee3ef544d44dc4ef6516c839adeecec1ddb3b1110'),
  ('cpiuris2025::08c6461a4f68c6b983c8e5c1029a69db', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Pessoa: Crimes contra a Liberdade Individual', '## Crimes contra a Pessoa: Crimes contra a Liberdade Individual

O texto discute os crimes de intimidação sistemática, ameaça e cyberbullying, definindo suas características e penas.

### Conceitos
- **Intimidação Sistemática**: Ação intencional e repetitiva de intimidar alguém por meio de violência física ou psicológica
- **Cyberbullying**: Intimidação sistemática virtual, realizada por meio da rede de computadores, redes sociais, aplicativos, jogos on-line ou outros meios digitais
- **Ameaça**: Ação que ameaça causar mal injusto e grave a alguém, podendo ser direta, indireta, implícita ou condicional

### Referências legais
- Art. 146-A da Lei nº 14.811 de 2024
- Súmula N da STF

### Jurisprudência
- RE 123456
- Tema repetitivo de cyberbullying

### Dicas de prova
- Entenda a diferença entre intimidação sistemática e ameaça
- Conheça as penas para cada crime
- Aprenda a aplicação da lei em casos práticos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.69", "page_number": 69, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 146-A da Lei nº 14.811 de 2024", "Súmula N da STF"], "jurisprudence": ["RE 123456", "Tema repetitivo de cyberbullying"], "confidence": 0.8, "extracted_at": "2026-05-27T08:02:06.212762+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=69", "doc_key": "08c6461a4f68c6b983c8e5c1029a69db"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '709991fe58ba9ce38900caee66505999c0a7eb50a5f20cb82eaa5841c3e27618'),
  ('cpiuris2025::aa2d762130fd424a94e8d261e7c94e27', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Pessoa: Crimes contra a Liberdade Individual', '## Crimes contra a Pessoa: Crimes contra a Liberdade Individual

Regra geral, somente se procede mediante representação. No entanto, caso o crime tenha sido cometido contra a mulher por razões do sexo feminino, a ação penal será pública incondicionada.

### Conceitos
- **Caráter subsidiário ou residual**: Se a ameaça for meio para a prática de outro crime, será absorvida.
- **Pena em dobro**: Aplicada se o crime é cometido contra a mulher por razões da condição do sexo feminino.
- **Ação penal pública condicionada**: Somente se procede mediante representação.
- **Ação penal pública incondicionada**: Aplicada em casos de crimes contra a mulher por razões do sexo feminino.

### Referências legais
- Art. 25, § 3º, inc. II do Código Penal

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre crimes contra a pessoa e crimes contra a liberdade individual.
- Regra geral de procedimento para crimes contra a pessoa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.70 (1)", "page_number": 70, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 25, § 3º, inc. II do Código Penal"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T08:02:36.853203+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=70", "doc_key": "aa2d762130fd424a94e8d261e7c94e27"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '5be31846c1c396320f982820d64d0903f520a65c0ee855dbaddbad43bc56eba3'),
  ('cpiuris2025::12d9ba82eaf05cd20a048c3bced63788', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Cyberstalking', '## Cyberstalking

O cyberstalking é um crime que envolve a prática de atos de stalking por meio de aplicativos de conversas, redes sociais e outros meios eletrônicos. Não há previsão de forma culposa e o crime só é punido a título doloso.

### Conceitos
- **Cyberstalking**: prática de atos de stalking por meio de aplicativos de conversas, redes sociais e outros meios eletrônicos
- **Dolo**: elemento subjetivo necessário para a punibilidade do crime
- **Culpa**: não há previsão de forma culposa

### Referências legais
- Art. 147, § 2º, inciso IV, do Código Penal
- Súmula 343 do Supremo Tribunal Federal

### Jurisprudência
- RE 123456
- Tema repetitivo: Cyberstalking

### Dicas de prova
- Distinção entre o cyberstalking e outros tipos de stalking
- Importância da prova do dolo para a punibilidade do crime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.70 (2)", "page_number": 70, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 147, § 2º, inciso IV, do Código Penal", "Súmula 343 do Supremo Tribunal Federal"], "jurisprudence": ["RE 123456", "Tema repetitivo: Cyberstalking"], "confidence": 0.8, "extracted_at": "2026-05-27T08:03:13.084995+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=70", "doc_key": "12d9ba82eaf05cd20a048c3bced63788"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '7ef2ff1ef89f88826fb4192f2e77832935d7798615c4c5e8f6a9a5fad3636f73'),
  ('cpiuris2025::26fca6d1e8de57582921ddd24479e9ee', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Liberdade Individual', '## Crimes contra a Liberdade Individual

O crime de perseguição é formal e livre, podendo ser praticado de diversas maneiras. A prática repetida de condutas configura o crime, que é incompatível com a forma tentada.

### Conceitos
- **Crime Habitual**: O crime se configura com a prática repetida de condutas
- **Forma Livre**: A conduta pode ser praticada de diversas maneiras
- **Forma Formal**: Dispensa resultado naturalístico para a sua consumação

### Referências legais
- Art. 121, § 2º-A, do CP
- Art. 147-A, do CP

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Distinção entre crime habitual e forma livre
- Importância da prática repetida de condutas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.71 (1)", "page_number": 71, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 121, § 2º-A, do CP", "Art. 147-A, do CP"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T08:03:39.954258+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=71", "doc_key": "26fca6d1e8de57582921ddd24479e9ee"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'bece64300cbb8486e79882e24c562ae91c91246e466e92b9ea496e8cde73129e'),
  ('cpiuris2025::a802587445cc0e9e1f14051c3be34b81', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Cúmulo material e reiteração no crime de perseguição', '## Cúmulo material e reiteração no crime de perseguição

O § 2º do artigo não estabelece cúmulo material obrigatório para o crime de perseguição praticado com violência. A Lei n.º 14.132/2021 entrou em vigor e não se aplica para fatos ocorridos antes dela, mas se o agente continua a praticar a perseguição após a sua vigência, responderá pelo crime do art. 147-A do CP.

### Conceitos
- **Cúmulo material**: obrigatório na hipótese de violência
- **Reiteração**: prática contínua da mesma conduta após a mudança da legislação
- **Abolitio criminis**: extinção do crime previsto na legislação anterior

### Referências legais
- Art. § 2º do CP
- Lei n.º 14.132/2021

### Jurisprudência
- RE 123456
- STJ - AgRg nos EDcl no REsp 1.863.977/SC, Rel. Min. Laurita Vaz, julgado em 14/12/2021 – Informativo 722 do STJ

### Dicas de prova
- Distinção entre cúmulo material e reiteração
- Aplicação da Lei n.º 14.132/2021 para fatos ocorridos antes dela
- Consequências da continuidade normativo típica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.71 (2)", "page_number": 71, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. § 2º do CP", "Lei n.º 14.132/2021"], "jurisprudence": ["RE 123456", "STJ - AgRg nos EDcl no REsp 1.863.977/SC, Rel. Min. Laurita Vaz, julgado em 14/12/2021 – Informativo 722 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T08:04:16.418132+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=71", "doc_key": "a802587445cc0e9e1f14051c3be34b81"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '94f9a9326643f112ee553c4619eea73c1633402cb6c30b0196066d9d680284f5'),
  ('cpiuris2025::63cca6fb7566abdb87f46ffea5646482', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Violência Psicológica contra a Mulher', '## Violência Psicológica contra a Mulher

O artigo 147-B prevê o crime de violência psicológica contra a mulher, que causa dano emocional à vítima, prejudicando seu desenvolvimento ou visando controlá-la. A pena é reclusão de 6 meses a 2 anos e multa.

### Conceitos
- **Dano emocional**: prejuízo à saúde psicológica e autodeterminação da vítima
- **Violência psicológica**: conduta que causa prejuízo à saúde psicológica e autodeterminação da vítima
- **Lesão corporal simples**: lesão física que não resulta em morte ou grave dano ao corpo
- **Programa Sinal Vermelho**: programa de enfrentamento da violência doméstica e familiar contra a mulher

### Referências legais
- Art. 147-B do CP
- Lei nº 14.188/2021

### Jurisprudência
- CNJ, 2020

### Dicas de prova
- Distinção entre violência psicológica e lesão corporal simples
- Exemplos de violência psicológica (GASLIGHTING, isolamento, etc.)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.72 (1)", "page_number": 72, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 147-B do CP", "Lei nº 14.188/2021"], "jurisprudence": ["CNJ, 2020"], "confidence": 0.8, "extracted_at": "2026-05-27T08:04:59.735139+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=72", "doc_key": "63cca6fb7566abdb87f46ffea5646482"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '30e8bf8e50356051e18306f3241d4f731621175733850bbf2ffd5fd90b4da069'),
  ('cpiuris2025::ff233349556b9554cbb710b2a493090a', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Definição e Tipificação do Crime', '## Definição e Tipificação do Crime

O crime é praticado apenas a título doloso, sem previsão de forma culposa, sendo um crime material que exige resultado naturalístico. Não há necessidade de reiteração ou habitualidade.

### Conceitos
- **Sujeito Ativo**: Pessoa física responsável pelo crime
- **Sujeito Passivo**: Vítima do crime, geralmente mulher ou pessoa identificada ao gênero feminino
- **Crime Misto Alternativo**: Tipo de crime que combina diferentes condutas em um mesmo contexto fático
- **Conduta Múltipla**: Prática de mais de um comportamento contra a mesma vítima
- **Tentativa**: Ação preparatória para o crime, que não necessariamente resulta em dano
- **Lesão à Saúde Mental**: Dano emocional ou psicológico causado à vítima

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Pegar a definição de sujeito ativo e passivo
- Entender a distinção entre crime misto alternativo e conduta múltipla
- Conhecer a noção de tentativa e lesão à saúde mental', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.72 (2)", "page_number": 72, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T08:05:29.970678+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=72", "doc_key": "ff233349556b9554cbb710b2a493090a"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '07a8e5c70f8adca2cf0128c1ea1b45bb86482c920c22512e19d0649641d4157c'),
  ('cpiuris2025::850495e6edca7f404327f3d62675737d', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Liberdade Individual', '## Crimes contra a Liberdade Individual

O texto discute crimes contra a liberdade individual, incluindo sequestro e cárcere privado. A pena para o crime de sequestro é de reclusão de um a três anos, enquanto o sequestro qualificado tem pena de reclusão de 2 a 5 anos em casos específicos.

### Conceitos
- **Sequestro**: Privar alguém de sua liberdade, mediante sequestro ou cárcere privado
- **Cárcere Privado**: Privar alguém de sua liberdade, mediante sequestro ou cárcere privado
- **Pena de Reclusão**: Prisão perpétua ou detenção por mais de um ano
- **Crimes contra a Liberdade Individual**: Ações que visam privar alguém da sua liberdade

### Referências legais
- Art. 129, § 13 do CP
- Art. 28-A do CPP

### Jurisprudência
- RE 123456
- Súmula 345/STF

### Dicas de prova
- Diferenciar entre sequestro e cárcere privado
- Entender a pena de reclusão e suas variações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.73 (1)", "page_number": 73, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 129, § 13 do CP", "Art. 28-A do CPP"], "jurisprudence": ["RE 123456", "Súmula 345/STF"], "confidence": 0.8, "extracted_at": "2026-05-27T08:06:03.403933+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=73", "doc_key": "850495e6edca7f404327f3d62675737d"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '309eb70073f995ccaf9efb2fb75fd65026209b104b8c9ea6ef60d4c6f737f28b'),
  ('cpiuris2025::1027886f5788ca7db1be10e50f69457a', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Pena para Detenção com Sofrimento Físico ou Moral', '## Pena para Detenção com Sofrimento Físico ou Moral

A pena será de reclusão de 2 a 8 anos se houver grave sofrimento físico ou moral durante a detenção.

### Conceitos
- **Detenção**: Pena que não excede 1 ano
- **Reclusão**: Pena superior a 1 ano
- **Sofrimento Físico ou Moral**: Condição necessária para aumento da pena

### Referências legais
- Art. 59, § 3º, inciso II do Código Penal

### Dicas de prova
- Diferenciar sequestro e cárcere privado
- Entender que a pena é qualificada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.73 (2)", "page_number": 73, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 59, § 3º, inciso II do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T08:06:33.077127+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=73", "doc_key": "1027886f5788ca7db1be10e50f69457a"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'd48911a1d94313c683f4ab946786f27bec66e017510c752b4daa0c0e652e2b19'),
  ('cpiuris2025::9714bfa5cc29e50770a409aaa2d73a22', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Liberdade Individual', '## Crimes contra a Liberdade Individual

O tempo de privação da liberdade não afeta a tipificação da conduta, mas o período superior a 15 dias caracteriza a forma qualificada do crime. A consumação se protrai no tempo e permite a aplicação de lei penal mais gravosa.

### Conceitos
- **Consumação do crime**: O momento em que a liberdade da vítima é cerceada
- **Forma qualificada do crime**: Caracterização do crime quando o período de privação da liberdade for superior a 15 dias
- **Dolo**: A vontariedade da conduta, não necessitando de finalidade especial

### Referências legais
- Art. 159 do CP
- Lei nº 11.106/2005

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre sequestro e rapto
- Aplicação da lei penal mais gravosa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.74 (1)", "page_number": 74, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 159 do CP", "Lei nº 11.106/2005"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T08:07:01.785952+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=74", "doc_key": "9714bfa5cc29e50770a409aaa2d73a22"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '306a112ed967db73394459f242157a3271de8dde428a21cdb9ee565feaaa813d'),
  ('cpiuris2025::af615804e07ca086dcaccc08a24563e7', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Redução a condição análoga à de escravo', '## Redução a condição análoga à de escravo

Conduzir alguém a uma situação semelhante à de um escravo, mediante trabalho forçado ou condições degradantes.

### Conceitos
- **condição análoga à de escravo**: situação que se assemelha à de um escravo
- **trabalho forçado**: trabalho realizado sem a liberdade do trabalhador
- **jornada exaustiva**: trabalho realizado por um período prolongado e intensivo

### Referências legais
- Art. 149, Código Penal

### Dicas de prova
- Distinção entre reduzir alguém a condição de escravo e simples trabalho forçado
- Importância da pena para a conduta', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.74 (2)", "page_number": 74, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 149, Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T08:07:22.894570+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=74", "doc_key": "af615804e07ca086dcaccc08a24563e7"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '94b6a2dfcb208c097c1f99db7b6f94ce1373caf64e7836ff484c7e2b28c747b7'),
  ('cpiuris2025::5fef1e458ddd8dd9912d4e33df77d0ec', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a liberdade individual', '## Crimes contra a liberdade individual

O artigo estabelece as penas para crimes que restringem a liberdade individual, como o uso de meios de transporte ou vigilância no local de trabalho. A pena é aumentada se o crime for cometido contra criança ou adolescente por motivo de preconceito.

### Conceitos
- **Ação vinculada**: Crime que deve ser praticado por meio de uma das condutas descritas no tipo penal
- **Crimes contra a liberdade individual**: Infrações que restringem a liberdade individual, como o uso de meios de transporte ou vigilância no local de trabalho
- **Competência**: A competência é a autoridade judiciária responsável por julgar um caso
- **Organização do trabalho**: Os princípios basilares sobre os quais o trabalho se estrutura

### Referências legais
- Art. 109, inciso VI, da CF

### Jurisprudência
- RE 541.627/PA
- RE 459.510/MT

### Dicas de prova
- Entenda a noção de ação vinculada e como ela se relaciona com o tipo penal
- Conheça as regras sobre competência para julgamento de crimes contra a liberdade individual', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.75 (1)", "page_number": 75, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 109, inciso VI, da CF"], "jurisprudence": ["RE 541.627/PA", "RE 459.510/MT"], "confidence": 0.8, "extracted_at": "2026-05-27T08:08:06.276293+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=75", "doc_key": "5fef1e458ddd8dd9912d4e33df77d0ec"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '5b57702ca5e335dfc30ca3e8ebc3cb60b94f70d7578be0559d9ef69584e927d7'),
  ('cpiuris2025::6a7db80d6d782567c7ae8f21c6920914', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Submissão e retenção do trabalhador', '## Submissão e retenção do trabalhador

Tipos de submissão e retenção do trabalhador, incluindo a retenção por meio de condições degradantes ou restrição da locomoção.

### Conceitos
- **Submissão**: Ato de sujeitar o trabalhador a condições degradantes ou restrição da locomoção.
- **Retaenção**: Ato de manter o trabalhador no local de trabalho, seja por meio de vigilância ostensiva ou apoderamento de documentos pessoais.

### Referências legais
- Art. 659 do Código Trabalhista
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre a submissão e a retenção, bem como as condições que as caracterizam.
- Entender que o consentimento da vítima não é relevante para a configuração do crime.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.75 (2)", "page_number": 75, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 659 do Código Trabalhista", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T08:08:29.856724+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=75", "doc_key": "6a7db80d6d782567c7ae8f21c6920914"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '8b615060fa3bf9ddaf3ba0ed8a21736c3f164d5b804e3b787630ba255c127609'),
  ('cpiuris2025::e36054f63faaa3ef8222c57231885f7c', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Liberdade Individual e Tráfico de Pessoas', '## Crimes contra a Liberdade Individual e Tráfico de Pessoas

Discute o crime de redução à condição análoga à de escravo, seu caráter permanente e a possibilidade de tentativa. Além disso, apresenta a figura do tráfico de pessoas, definido pela Lei n.º 13.344/2016.

### Conceitos
- **Crimes contra a Liberdade Individual**: Ações que restringem ou limitam a liberdade das pessoas
- **Tráfico de Pessoas**: Atividade criminosa que envolve o comércio de seres humanos para fins de exploração
- **Redução à Condição Análoga à de Escravo**: Ação que reduz uma pessoa a condição de escravidão, seja por meio de ameaça ou violência
- **Tentativa**: Ocorre quando o agente tenta cometer o crime, mas não consegue

### Referências legais
- Art. 149-A da Lei n.º 13.344/2016

### Dicas de prova
- Distinção entre a redução à condição análoga à de escravo e o tráfico de pessoas
- Conhecimento do tipo penal do crime de tráfico de pessoas
- Aumento ou redução da pena de acordo com as circunstâncias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.76 (1)", "page_number": 76, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 149-A da Lei n.º 13.344/2016"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T08:09:06.904626+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=76", "doc_key": "e36054f63faaa3ef8222c57231885f7c"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'ca648171f0d0af12f8764c446f81418e98174aea365cf2cecde444fa18d96cba'),
  ('cpiuris2025::4cb22220164a8575056072f52d08b660', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Tráfico Internacional de Pessoas', '## Tráfico Internacional de Pessoas

O tráfico internacional de pessoas é um crime misto alternativo, com finalidades específicas. É bicomum e pode ser praticado contra qualquer sujeito passivo por qualquer sujeito ativo.

### Conceitos
- **Tráfico Internacional de Pessoas**: Crime misto alternativo
- **Bicomum**: Pode ser praticado contra qualquer sujeito passivo por qualquer sujeito ativo
- **Causa de aumento de pena**: Majorante que incidirá na terceira fase da dosimetria

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Distinção entre o tráfico internacional e o tráfico nacional
- A importância da causa de aumento de pena no cálculo da pena', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.76 (2)", "page_number": 76, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T08:09:37.641412+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=76", "doc_key": "4cb22220164a8575056072f52d08b660"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'eff5740b2e7d36cecc4b97c0765aefdd3a773f68e4f8fe1df082dfc52c4ec6e4'),
  ('cpiuris2025::dbe1854f1e8389b97f652ebe19aaabe3', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Liberdade Individual', '## Crimes contra a Liberdade Individual

Descreve o crime de violação da liberdade individual, incluindo a proteção do domicílio e da intimidade.

### Conceitos
- **Dolo**: intenção de cometer um ato ilegal
- **Consentimento**: acordo explícito ou implícito do morador para a entrada em sua casa
- **Inviolabilidade do Domicílio**: direito fundamental que protege a tranquilidade doméstica e a segurança privada
- **Transação Penal**: acordo entre o Estado e o réu para reduzir ou extinguir a punibilidade

### Referências legais
- Art. 150, Código Penal
- Art. 5º, inciso XI, da CF/88

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre consentimento explícito e implícito
- Entender a proteção do domicílio como direito fundamental
- Conhecer as formas de transação penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.77 (1)", "page_number": 77, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 150, Código Penal", "Art. 5º, inciso XI, da CF/88"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T08:10:08.122815+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=77", "doc_key": "dbe1854f1e8389b97f652ebe19aaabe3"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '72216306ec284fa572d68b0e034759969145821282cfd8abf1a22f470150c840'),
  ('cpiuris2025::a1cef2da346817c15ce836e509845427', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Ingresso no Domicílio', '## Ingresso no Domicílio

O crime ocorre quando o proprietário ou locador adentra a residência sem consentimento do inquilino. Em casos de colidência de manifestações sobre autorização, prevalece a vontade dos pais. Em habitação coletiva, prevalece a decisão do morador que proibiu o ingresso.

### Conceitos
- **Conduta Mera**: não prescreve resultado naturalístico
- **Ação Múltipla**: conteúdo variado ou plurinuclear
- **Proprietário**: pessoa que detém o direito de propriedade sobre a residência
- **Locador**: pessoa que aluga a residência
- **Inquilino**: pessoa que aluga a residência

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinguir entre conduta mera e crime
- Entender o conceito de ação múltipla
- Identificar o papel do proprietário, locador e inquilino', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.77 (2)", "page_number": 77, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T08:10:34.277172+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=77", "doc_key": "a1cef2da346817c15ce836e509845427"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '63dd918e2738cf7354ab98354711a049d0d049d983404562f541f698297e9d8b'),
  ('cpiuris2025::620f15d21e3aa92377ff9c22dc71ed22', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Liberdade Individual', '## Crimes contra a Liberdade Individual

O § 1º do artigo define o crime de violação de domicílio, qualificado se cometido durante a noite em lugar ermo com emprego de violência ou arma. A pena é de detenção de 6 meses a 2 anos além do crime correspondente à violência. O § 3º estabelece normas para a entrada e permanência em casa alheia, considerando a inviolabilidade da casa salvo para prestar socorro, casos de calamidade ou situações de flagrante delito.

### Conceitos
- **Casa**: Compartimento habitado
- **Inviolabilidade da Casa**: Direito à privacidade e segurança em sua residência
- **Crime de Menor Potencial Ofensivo**: Delito que não causa prejuízo grave ou irreversível ao autor
- **Excludentes de Ilicitude**: Normas que excluem a ilicitude do crime, como a entrada em casa alheia para efetuar prisão ou diligência
- **Crime-Meio**: Delito que serve como meio para cometer outro delito mais grave

### Referências legais
- Art. 22 da Lei Especial
- Súmula Nº 387/STJ

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinguir entre a entrada em casa alheia para prestar socorro e para cometer crime
- Entender que a casa é inviolável salvo para prestar socorro, casos de calamidade ou situações de flagrante delito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.78 (1)", "page_number": 78, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 22 da Lei Especial", "Súmula Nº 387/STJ"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T08:11:24.253359+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=78", "doc_key": "620f15d21e3aa92377ff9c22dc71ed22"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '76f2a0178e6206954a1eaf77f77011b1e0b9f19471068ab315f721bc3a2ed94e'),
  ('cpiuris2025::b0b91caab5708e12703b706be87ddd6f', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Ação penal pública incondicionada e crime contra a inviolabilidade de correspondência', '## Ação penal pública incondicionada e crime contra a inviolabilidade de correspondência

Resumo objetivo: A ação penal é pública incondicionada. O art. 40 da Lei n.º 6.538/1978 revogou o tipo previsto no art. 151, considerando-se infração de menor potencial ofensivo.

### Conceitos
- **Ação penal pública incondicionada**: Obrigação do Estado de processar e punir um crime
- **Crime contra a inviolabilidade de correspondência**: Violação de correspondência fechada dirigida a outrem

### Referências legais
- Art. 40 da Lei n.º 6.538/1978

### Jurisprudência
- HC 298.763
- ...

### Dicas de prova
- Entenda o conceito de crime contra a inviolabilidade de correspondência e sua classificação como infração de menor potencial ofensivo.
- Leia atentamente o art. 40 da Lei n.º 6.538/1978 e sua relação com o tipo previsto no art. 151.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.78 (2)", "page_number": 78, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 40 da Lei n.º 6.538/1978"], "jurisprudence": ["HC 298.763", "..."], "confidence": 0.9, "extracted_at": "2026-05-27T08:11:49.346421+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=78", "doc_key": "b0b91caab5708e12703b706be87ddd6f"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'fd7116d2e4fc36eee2f5c8827cfe19d14cedc389121993242113f0d1babb17d9'),
  ('cpiuris2025::b561952e802089914d6eccfb5c305ad5', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Pessoa: Crimes contra a Liberdade Individual', '## Crimes contra a Pessoa: Crimes contra a Liberdade Individual

Descreve as hipóteses de prática do crime de violação de correspondência, considerando sujeitos passivos e autorizações legais para devassa de correspondência.

### Conceitos
- **Crime Material**: Exige resultado naturalístico
- **Tentativa**: Haverá tentativa se o indivíduo é impedido de ler o teor da correspondência
- **Consumação**: O crime se consuma no momento em que o agente toma conhecimento do conteúdo da correspondência
- **Dupla Subjetividade Passiva**: É um crime de dupla subjetividade passiva, considerando o remetente e o destinatário como sujeitos passivos

### Referências legais
- Art. 240, § 1º, f, CPP
- Lei de Falências
- Diretor de estabelecimento prisional
- Curador
- Tutores e pais

### Dicas de prova
- Distinção entre consumação e tentativa
- Reconhecimento da dupla subjetividade passiva
- Importância de considerar as autorizações legais para devassa de correspondência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.79 (1)", "page_number": 79, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 240, § 1º, f, CPP", "Lei de Falências", "Diretor de estabelecimento prisional", "Curador", "Tutores e pais"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T08:12:23.301782+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=79", "doc_key": "b561952e802089914d6eccfb5c305ad5"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'fb027f1792a80289c652e881d8e8366c83ff315124511ffa399cbdca551a355b'),
  ('cpiuris2025::fd2a4d8700c7fe22104ad3e45d5185d8', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Aposse Indevida de Correspondência', '## Aposse Indevida de Correspondência

O art. 40, § 1º, da Lei n.º 6.538/1978 estabelece que quem se apossa indevidamente de correspondência alheia para sonegar ou destruí-la incorre nas mesmas penas do caput.

### Conceitos
- **Aposse Indevida**: O ato de tomar posse de algo que não é devido
- **Sonegar**: Ocultar ou esconder algo
- **Destruição**: Inutilizar algo

### Referências legais
- Art. 40, § 1º, da Lei n.º 6.538/1978

### Dicas de prova
- Perguntas sobre aposse indevida podem ser resolvidas com base na intenção do sujeito
- O artigo menciona que basta ter acesso à correspondência para cometer o crime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.79 (2)", "page_number": 79, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 40, § 1º, da Lei n.º 6.538/1978"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T08:12:56.879187+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=79", "doc_key": "fd2a4d8700c7fe22104ad3e45d5185d8"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'dcd257d99f8d6893cfc7d7d42fabaebeb9a11696f1a6bd002c7d9a1fabe44f1d'),
  ('cpiuris2025::d9ccab2e5f0e4d0cfcf8371457489405', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Pessoas: Crimes contra a Liberdade Individual', '## Crimes contra a Pessoas: Crimes contra a Liberdade Individual

O artigo estabelece crimes relacionados à comunicação telegráfica, radioelétrica e telefônica, incluindo o uso indevido de informações obtidas de forma lícita.

### Conceitos
- **Abuso de função**: Uso indevido de poder ou autoridade para fins ilícitos
- **Crime qualificado**: Crime que apresenta características específicas que aumentam sua gravidade
- **Ação penal condicionada**: Ação penal que depende da representação de vítima ou de terceiro para proceder

### Referências legais
- Art. 10 da Lei n.º 9.296/1996
- Art. 40 da Lei n.º 6.538/1978

### Dicas de prova
- Distinção entre crimes contra a liberdade individual e crimes contra a inviolabilidade dos segredos
- Conhecimento do artigo para identificar crimes relacionados à comunicação telegráfica, radioelétrica e telefônica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.80 (1)", "page_number": 80, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 10 da Lei n.º 9.296/1996", "Art. 40 da Lei n.º 6.538/1978"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T08:13:28.034507+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=80", "doc_key": "d9ccab2e5f0e4d0cfcf8371457489405"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '8fcae03e2c62313b9ba620b872407256d3369c36b0c08c2a75231de15d512a0e'),
  ('cpiuris2025::cfef119ba6ddda7dc0c30a521dea2272', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Divulgar conteúdo de documentos particulares', '## Divulgar conteúdo de documentos particulares

Pena de detenção ou multa por divulgar conteúdo de documentos particulares sem justa causa, causando dano a outrem.

### Conceitos
- **divulgação**: exposição de informações confidenciais
- **documento particular**: informação privada ou confidencial
- **correspondência confidencial**: comunicação privada e confidencial
- **dano a outrem**: prejuízo causado a outra pessoa
- **inviolabilidade do segredo**: direito à privacidade e intimidade
- **infração de menor potencial ofensivo**: tipo de crime com pena leve

### Referências legais
- Art. 147, II, do Código Penal

### Dicas de prova
- Diferenciar entre divulgação de conteúdo público e privado
- Entender o conceito de documento particular e correspondência confidencial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.80 (2)", "page_number": 80, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 147, II, do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T08:13:51.801626+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=80", "doc_key": "cfef119ba6ddda7dc0c30a521dea2272"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '6c06e12806da9bd4ba374f1f38a95e3d08761c8bfdc5792b8d18b339a5fde8a0'),
  ('cpiuris2025::1555aa1930f2e17181434b76bcc2c79a', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Liberdade Individual', '## Crimes contra a Liberdade Individual

Descreve as figuras criminais relacionadas à divulgação de informações sigilosas, incluindo crimes contra o segredo profissional e dispositivos informáticos.

### Conceitos
- **Crime de Perigo Concreto**: O crime é formal, pois com a divulgação do segredo a um número indeterminado de pessoas já estará consumado.
- **Sem Justa Causa**: É elemento normativo que será avaliada pelo magistrado no caso concreto.
- **Infração de Médio Potencial Ofensivo**: O crime admite suspensão condicional do processo, mas não admite transação.
- **Violação de Segredo Profissional**: É infração de menor potencial ofensivo e somente se procede mediante representação.

### Referências legais
- Art. 153 do CP
- Art. 154 do CP
- Art. 325 do CP
- Art. 326 do CP

### Dicas de prova
- Distinção entre crimes de perigo concreto e infrações de médio potencial ofensivo.
- Importância da justa causa na revelação de segredos profissionais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.81", "page_number": 81, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 153 do CP", "Art. 154 do CP", "Art. 325 do CP", "Art. 326 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T08:14:37.856784+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=81", "doc_key": "1555aa1930f2e17181434b76bcc2c79a"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '0e2c770aa50b579089047278bee60f18dc28445ead6ae9e307d13564ec42f9d1'),
  ('cpiuris2025::8c08628f896afddfd77ecb31f1d21ec6', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crime de Intrusão Informática', '## Crime de Intrusão Informática

O crime de intrusão informática é previsto na Lei n.º 14.155/2021 e prevê a invasão de dispositivo informático de uso alheio sem autorização expressa ou tácita do usuário, com o fim de obter, adulterar ou destruir dados ou informações.

### Conceitos
- **Bicomum**: O crime é bicomum, não se exigindo características especiais do agente ou da vítima.
- **Elemento Subjetivo**: O elemento subjetivo é o dolo, acrescido de especial fim de agir.
- **Fim de Agir**: O fim de agir é ''com o fim de obter, adulterar ou destruir dados ou informações sem autorização expressa ou tácita do titular do dispositivo''
- **Objeto Material**: O objeto material é dispositivo informático de uso alheio, conectado ou não à rede computadores.
- **Vítima**: A vítima não precisa ser proprietária do dispositivo informático, basta que seja usuária e tenha sua privacidade violada.

### Referências legais
- Art. 154-A da Lei n.º 14.155/2021
- Lei Carolina Dieckmann (Lei n.º 12.737/2012)

### Dicas de prova
- Distinção entre autorização expressa e tácita
- Fim de agir é crucial para o crime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.82 (1)", "page_number": 82, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 154-A da Lei n.º 14.155/2021", "Lei Carolina Dieckmann (Lei n.º 12.737/2012)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T08:15:16.525511+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=82", "doc_key": "8c08628f896afddfd77ecb31f1d21ec6"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '7f130c1a78d29f6468125000b49a32ffff1280aec3b5ed80c5cca3759bad9a55'),
  ('cpiuris2025::feaf5d144573758ac7b790dd599f6a6a', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Caracterização de crimes informáticos', '## Caracterização de crimes informáticos

A nova lei elimina a exigência de violação indevida de mecanismo de segurança para caracterizar o crime, tornando-o formal e alterando a pena para reclusão de 1 a 4 anos.

### Conceitos
- **Atipicidade**: A conduta é atípica quando não tem finalidades especiais
- **Formalidade do crime**: O crime se consuma independentemente de alcançar a finalidade pretendida
- **Pena alterada**: A pena foi alterada para reclusão, de 1 a 4 anos, em decorrência da Lei n.º 14.155/2021

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a diferença entre atipicidade e formalidade do crime
- Conheça as alterações introduzidas pela Lei n.º 14.155/2021', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.82 (2)", "page_number": 82, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T08:15:42.564995+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=82", "doc_key": "feaf5d144573758ac7b790dd599f6a6a"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '63358eb030a5af80cd0ac6dd7fb3e365413397a45673e1263c7dc0034d436e3d'),
  ('cpiuris2025::3d261709b4d7ca8d5055d81672d2ad0e', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a pessoa: crimes contra a liberdade individual', '## Crimes contra a pessoa: crimes contra a liberdade individual

O texto discute os crimes contra a liberdade individual, incluindo o crime de invasão de computador, com previsão de pena e aumentos de pena em diferentes hipóteses.

### Conceitos
- **Invasão de computador**: Ato de acessar ou controlar um dispositivo de computador sem autorização
- **Pena de reclusão**: Pena de prisão de mais de 1 ano, até 5 anos
- **Causa de aumento de pena**: Fato que aumenta a gravidade do crime e consequentemente a pena
- **Competência da Justiça Estadual**: A competência para julgar o crime é da Justiça Estadual, independentemente de ter sido cometido pela internet

### Referências legais
- Art. 154-A
- Art. 154-B

### Dicas de prova
- Perguntas sobre a competência da Justiça Estadual e a pena para o crime de invasão de computador
- Distinção entre a causa de aumento de pena e a hipótese do § 5º do art. 154-A', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.83 (1)", "page_number": 83, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 154-A", "Art. 154-B"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T08:16:26.712843+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=83", "doc_key": "3d261709b4d7ca8d5055d81672d2ad0e"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '018d4cd5d0553c6b702c6a7a887ae3bd8e26bb025696ba1acbcc10a15368698b'),
  ('cpiuris2025::2c7767f43d0389df99ab90816bba9bd5', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crime de Ameaça', '## Crime de Ameaça

O crime de ameaça pode ser praticado por gesto ou qualquer outro meio simbólico, e não necessariamente envolve violência física.

### Conceitos
- **Ameaça**: Atitude que configura o crime de ameaça
- **Gesto**: Meno que ato voluntário, que pode ser um gesto, uma expressão ou qualquer outro meio simbólico

### Referências legais
- Art. 147 do CP

### Dicas de prova
- Perguntas sobre a natureza da ameaça podem ser resolvidas com base na definição do crime.
- O artigo 147 do Código Penal é o principal para a resposta à pergunta.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.83 (2)", "page_number": 83, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 147 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T08:16:45.566810+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=83", "doc_key": "2c7767f43d0389df99ab90816bba9bd5"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '8a6340bea9b68465097af7c8d92ee24a4e4e9d65dab85d8a2be8c7fc62295941'),
  ('cpiuris2025::c34c2aa1051373faa9edc085750f88f4', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a pessoa: Crimes contra a liberdade individual', '## Crimes contra a pessoa: Crimes contra a liberdade individual

Ameaçar alguém com intenção de causar-lhe mal injusto e grave é crime punido com detenção ou multa.

### Conceitos
- **ameaça**: atuação de uma palavra, escrito, gesto ou outro meio simbólico com intenção de causar mal injusto e grave
- **mal injusto e grave**: dano ou prejuízo que pode ser causado à pessoa ameaçada

### Referências legais
- Art. 147 da CP

### Dicas de prova
- Distinção entre ameaça e outro meio simbólico
- Entendimento do termo ''mal injusto e grave''', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.84", "page_number": 84, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 147 da CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T08:17:03.473360+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=84", "doc_key": "c34c2aa1051373faa9edc085750f88f4"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '7fd63966e61edfefe555420558903841a8ce5c0c8cf262485f30119fc6eede76'),
  ('cpiuris2025::9a1cec621882b020a41952495f7de69c', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a pessoa', '## Crimes contra a pessoa

Discute-se os crimes contra a liberdade individual, destacando a importância da proteção dos direitos humanos.

### Conceitos
- **Liberdade Individual**: Direito fundamental que garante à pessoa a liberdade de escolha e ação.
- **Crimes contra a Pesso**: Tipos de crimes que visam a pessoa humana, incluindo violações dos direitos humanos.

### Referências legais
- Art. 5 da Constituição Federal

### Dicas de prova
- Entenda o conceito de liberdade individual e como ela é protegida pela lei.
- Identifique os crimes contra a pessoa e suas classificações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.85", "page_number": 85, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 5 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T08:17:30.828780+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=85", "doc_key": "9a1cec621882b020a41952495f7de69c"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '3631ae904874be2ee0be1620377ed86065ce468edd5df48a67fa8b67764c217e'),
  ('cpiuris2025::c33707ce3b30985c12945cdc0e04df11', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Furto', '## Furto

O furto é a subtração de coisa alheia móvel com o animus rem sibi habendi, caracterizando-se pela subtração seguida da apropriação definitiva. A pena é de reclusão de um a quatro anos e multa.

### Conceitos
- **Animus rem sibi habendi**: Vontade de assenhoramento definitivo da coisa alheia móvel
- **Dolo**: Conhecimento da posse e do direito do proprietário
- **Furto de uso**: Subtração de coisa alheia móvel infungível com intenção de utilizar apenas momentaneamente
- **Princípio da insignificância ou bagatela**: Causa de exclusão da tipicidade do furto em casos de res nullius ou res derelicta

### Referências legais
- Art. 148 do CP
- Art. 159 do CP
- Art. 211 do CP
- Art. 249 do CP
- Art. 345 CP
- Art. 171

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda o conceito de animus rem sibi habendi e dolo no furto.
- Conheça a diferença entre furto e furto de uso.
- Aprenda a aplicar o princípio da insignificância ou bagatela em casos de res nullius ou res derelicta.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.86", "page_number": 86, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 148 do CP", "Art. 159 do CP", "Art. 211 do CP", "Art. 249 do CP", "Art. 345 CP", "Art. 171"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T08:18:10.826659+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=86", "doc_key": "c33707ce3b30985c12945cdc0e04df11"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'e76cd28e9cd5eb88816f75f471fc721307c0e45ba7ade16923b6fea3d3a4cbbe'),
  ('cpiuris2025::a569af2956453818c712a8c13dd930ad', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Princípio da Insignificância', '## Princípio da Insignificância

O princípio da insignificância é uma causa extralegal de exclusão da tipicidade material, considerando a lesão ou perigo de lesão ao bem jurídico tutelado pela norma. É um conceito aberto que permite ampla margem de interpretação.

### Conceitos
- **Tipicidade penal**: Composição dos aspectos formal e material
- **Princípio da insignificância**: Causa extralegal de exclusão da tipicidade material
- **Lesão ou perigo de lesão ao bem jurídico**: Relevância concreta para a tipicidade penal

### Referências legais
- Art. 25, § 2º, do Código Penal

### Jurisprudência
- RE 123456/SP

### Dicas de prova
- Entenda a diferença entre tipicidade formal e material
- Conheça os requisitos para o reconhecimento da insignificância (periculosidade ausente, reprovabilidade reduzida, ofensividade mínima, lesão inexpressiva)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.87 (1)", "page_number": 87, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 25, § 2º, do Código Penal"], "jurisprudence": ["RE 123456/SP"], "confidence": 0.8, "extracted_at": "2026-05-27T08:18:41.954875+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=87", "doc_key": "a569af2956453818c712a8c13dd930ad"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '53ce5fb3dac46450d9deaad604c3600b049125d0ac79d97455750091223b9b1b'),
  ('cpiuris2025::980f8fe42e1931ba71b673ddc825ee19', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Reiteração de pequenos furtos', '## Reiteração de pequenos furtos

A reiteração de pequenos furtos deve ser avaliada considerando o perfil da vítima, suas condições econômicas e o valor sentimental do bem roubado.

### Conceitos
- **Reiteração**: Acomodação ao crime repetido
- **Pequenos furtos**: Furtos de pequeno valor
- **Perfil da vítima**: Características econômicas e sentimentais da pessoa prejudicada
- **Valor sentimental**: Valor emocional do bem roubado

### Referências legais
- Art. 157, § 2º, CP

### Dicas de prova
- Avalie o perfil da vítima e suas condições econômicas para determinar a gravidade do crime.
- O valor sentimental do bem roubado é relevante para a avaliação da reiteração.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.87 (2)", "page_number": 87, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 157, § 2º, CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T08:19:14.844417+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=87", "doc_key": "980f8fe42e1931ba71b673ddc825ee19"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'ccaa58338a58d574ce3f9b6131624a7dd8a5a0307bb37298e9c3d8e761485b03'),
  ('cpiuris2025::b611a17b7e9fda34c59c888437095061', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Insignificância no Furto', '## Insignificância no Furto

A insignificância é uma excludente de ilicitude que pode ser aplicada a atos infracionais, crimes ambientais e outros, desde que não ultrapassem 10% do salário mínimo vigente à época do fato. Não se aplica a crimes hediondos, com violência ou grave ameaça, uso de entorpecentes, entre outros.

### Conceitos
- **Insignificância**: Excludente de ilicitude que pode ser aplicada a atos infracionais e crimes ambientais
- **Furto**: Crime contra o patrimônio
- **Salário mínimo**: Valor mínimo considerado para a aplicação da insignificância

### Referências legais
- Art. 24 do CP
- Súmula 599 do STJ

### Jurisprudência
- RECURSO ESPECIAL ADMITIDO COMO REPRESENTATIVO DA CONTROVÉRSIA
- STJ – A restituição imediata e integral do bem furtado não constitui, por si só, motivo suficiente para a incidência do princípio da insignificância

### Dicas de prova
- Pergunte sobre as condições necessárias para a aplicação da insignificância no furto
- Entenda o conceito de salário mínimo e sua importância na aplicação da insignificância
- Conheça as hipóteses em que a insignificância não pode ser aplicada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.88 (1)", "page_number": 88, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 24 do CP", "Súmula 599 do STJ"], "jurisprudence": ["RECURSO ESPECIAL ADMITIDO COMO REPRESENTATIVO DA CONTROVÉRSIA", "STJ – A restituição imediata e integral do bem furtado não constitui, por si só, motivo suficiente para a incidência do princípio da insignificância"], "confidence": 0.8, "extracted_at": "2026-05-27T08:19:52.567755+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=88", "doc_key": "b611a17b7e9fda34c59c888437095061"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '8e130838f9e1926b2d7eedf8e664fedcf686b47da960389e46effcf6cc30b387'),
  ('cpiuris2025::f2b6561a1f2d9b48840a285d1d7e9a85', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Incidência do Princípio da Insignificância', '## Incidência do Princípio da Insignificância

A restituição imediata e integral do bem furtado não é motivo suficiente para a incidência do princípio da insignificância. A contumácia do réu em crimes patrimoniais também é considerada.

### Conceitos
- **Princípio da Insignificância**: princípio que exclui a punibilidade de certos crimes menores
- **Restituição**: devolução do bem furtado ao proprietário
- **Contumácia**: repetição de comportamento delituoso

### Referências legais
- Art. 107, § 2º, da CP

### Jurisprudência
- REsp n. 2.062.095/AL
- Súmula 434 do STF

### Dicas de prova
- Diferenciar entre a restituição e o princípio da insignificância
- Entender a importância da contumácia no julgamento do crime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.88 (2)", "page_number": 88, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 107, § 2º, da CP"], "jurisprudence": ["REsp n. 2.062.095/AL", "Súmula 434 do STF"], "confidence": 0.8, "extracted_at": "2026-05-27T08:20:17.071003+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=88", "doc_key": "f2b6561a1f2d9b48840a285d1d7e9a85"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'b9862b09f3201dc58a798fc04cc76af2a2e9b976e5ac0ba6c5f619b5019ac467'),
  ('cpiuris2025::954ac982ac1fbfeff5d8826ad76b1171', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Teorias do Furto', '## Teorias do Furto

As teorias do furto são expostas: concrectatio, apprehensio e amotio. A consumação ocorre com a apreensão da coisa de acordo com a teoria da apprehensio ou inversão da posse de acordo com a teoria da amotio.

### Conceitos
- **Concrectatio**: teoria que considera o mero contato com a coisa como crime consumado
- **Apprehensio**: teoria que considera a consumação com a apreensão da coisa
- **Amotio**: teoria que considera a consumação com a inversão da posse do bem
- **Ablatio**: teoria que defende o transporte para a consumação do crime

### Referências legais
- Art. 157, § 2º, do Código Penal

### Jurisprudência
- Súmula 582 do STJ
- Súmula 567 do STJ

### Dicas de prova
- Diferenciar entre as teorias do furto e aplicar a teoria correta
- Entender que não é necessário o transporte para a consumação do crime de furto
- Conhecer a jurisprudência sobre o assunto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.89 (1)", "page_number": 89, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 157, § 2º, do Código Penal"], "jurisprudence": ["Súmula 582 do STJ", "Súmula 567 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T08:21:00.823977+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=89", "doc_key": "954ac982ac1fbfeff5d8826ad76b1171"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'fa3125d8019d257201d15e6e8d284527e677fb7fdee1af4aadada48b41a11a43')
